CREATE TRIGGER [dbo].[OrdTgt_INUPDL] ON [dbo].[OrdTgt] 
    FOR INSERT,UPDATE,DELETE  
    NOT FOR REPLICATION
AS  
BEGIN  
	/* Trigger Version 3.02.0 (Speed Optimization) */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'OrdTgt' )  
	RETURN  
  
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wCurrPrtn='C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where OtPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where OtPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.OtPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<> 1)
	Begin
		 /******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		If @mode in ('A','C')
			Begin 
			/* Current Partition */
			select @ROW =Count('x')  From inserted where  OtPrtKey=@wCurrPRtn and
			Exists ( select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not  like '%,'+ OtCoCd +',%') 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
				Begin 
					select @errmsg= 'Cannot Insert /Update ' 
					goto ErrHndlr 
				end 
			End 

			If @mode in ('D')
			Begin 
			/* Current Partition */
			select @ROW =Count('x')  From Deleted where OtPRtKey=@wCurrPRtn and 
			Exists ( select 'x' From SysDb where (SysId='EMR' and ',' + SdCoCd + ',' Not  like '%,'+ OtCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
				Begin 
					select @errmsg= 'Cannot Delete ' 
					goto ErrHndlr 
				end 
			End 		
	End		
 
 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		/* Current Partition */
		select @Row= Count('x') from deleted del where del.OtPrtKey=@wCurrPrtn and
			 not exists (Select 'x' from inserted ins where ins.OtCoCd= del.OtCoCd
					and ins.OtTc= del.OtTc and ins.OtYy= del.OtYy and ins.OtChr= del.OtChr
					and ins.OtNo= del.OtNo and ins.OtSr= del.OtSr and ins.OtPrtKEy=del.OtPrtKey)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Change Company Code/ Tc/Yy/Chr/No/Sr'
			GoTo ErrHndlr
		end
	End
	if @mode in ('A','C')
	Begin
		/****** OrderNo should exist in OrdMst table ******/
		/* Current Partition */
		select @row= count('x') from inserted where OtPrtKey=@wCurrPRtn and
			not exists (select 'x' from OrdMst where OmCoCd= OtCoCd and OmTc= OtTc
			and OmYy= OtYy and OmChr= OtChr and OmNo= OtNo and OmPrtKEy=OtPRtkey)
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Not Defined In Order Master'
			goto ErrHndlr
		end

		/******  OtSr  >=  0  ******/
		/* Current Partition */
		select @row= count('x') from inserted where OtPrtKey=@wCurrPRtn and OtSr< 0
		if @row> 0
		begin
			select @errmsg= 'Order Target Serial Should Be Greater Than Zero'
			goto ErrHndlr
		end

		/*** (Jen 2.13) ***/
		/****** Cannot insert records if Order linked to a Return Memo ******/
		/* Current Partition */
		select @row= count('x') from inserted where OtPRtKey=@wCurrPrtn and
			exists (select 'x' from OrdMst where OmCoCd= OtCoCd and OmTc= OtTc 
			and OmYy= OtYy and OmChr= OtChr and OmNo= OtNo and OmPRtKey=OtPrtKey and OmReNo> 0)
		if @row> 0
		begin
			select @errmsg= 'Cannot Enter Record In OrdTgt Table As Order Master Linked To Return Memo'
			goto ErrHndlr
		end
		/*** (Jen 2.13) ***/

		/******  OtRmCtg  =  PMCd ('RMCTG')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where OtPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= OtRmCtg)
		if @row> 0
		begin
			select @errmsg= 'Raw Material Category Not Defined'
			goto ErrHndlr
		end

		/******  OtRmSCtg  =  PSCd ('RMSCTG', OtRmCtg)  ******/
		/* Current Partition */
		select @row= count('x') from inserted where OtPRtKey=@wCurrPRtn and
			not exists (select 'x' from Param where PTyp= 'RMSCTG'
			and PMCd= OtRmCtg and PSCd= OtRmSCtg)
		if @row> 0
		begin
			select @errmsg= 'Raw Material Sub Category Not Defined'
			goto ErrHndlr
		end
		
		/******  OtCol  =  RmCol and Current Partition  ******/
		/* Uma changed */
		select @row= count('x') from inserted where OtPRtKEy=@wCurrPRtn and OtCol <> '*' and OtCol <>'' and  
			Not exists (Select 'x' from RmMst where RmZ= 'N' and RmCtg= OtRmCtg and RmSCtg= OtRmSCtg and RmCol =OtCol  and RmPrtKey=OtPrtKey )
		if @row> 0
		begin
			select @errmsg= 'Raw Material Colour Not Defined'
			goto ErrHndlr
		end	
		
		/******  OtRngSz  =  RmRngSz and Current Partition  ******/
		/* Uma changed - Blank is allowed*/
		select @row= count('x') from inserted where OtPRtKEy=@wCurrPRtn and OtRmRSZ <> '*' and   OtRmRSZ <> '' and
			Not exists (Select 'x' from RmRt  where RrCtg = OtRmCtg and RrSctg = OtRmSCtg and RrRngSz =OtRmRSZ and RrPrtKey =OtPrtKey )
		if @row> 0
		begin
			select @errmsg= 'Raw Material Range Size Not Defined'
			goto ErrHndlr
		end	

		/******  OtRmCd  =  RmCd from RmMst (RmCtg= OtRmCtg, RmSCtg= OtRmSCtg, RmZ= 'N')  ******/
		/* Current Partition */
		/* **** Manali 3.5.0 - 17/11/07 - RmCd Change within Main Metals Allowed  */
		/* Uma changed */
		select @row= count('x') from inserted where OtPRtKEy=@wCurrPRtn and OtRmCd <> '' and 
			(Not exists (Select 'x' from RmMst where 
						(((OtRmCtg In ('G', 'P', 'S', 'L','M') And RmCtg In ('G', 'P', 'S', 'L','M')) Or (OtRmCtg In ('D', 'C') And RmCtg In ('D', 'C')  and OtRmSCtg=RmSCtg))
								 and RmCd=OtRmCd and RmPrtKey=OtPrtKey and RmZ= 'N') Or 
						(OtRmCtg Not In ('G', 'P', 'S', 'L','M','D','C') and RmCtg= OtRmCtg and RmSCtg= OtRmSCtg and RmCd= OtRmCd and RmPrtKey=OtPrtKey and RmZ= 'N')
			))
		if @row> 0
		begin
			select @errmsg= 'Raw Material Code Not Defined'
			goto ErrHndlr
		end
		
		
		                         
                              
                              
		/*	select @row= count('x') from inserted where OtPRtKEy=@wCurrPRtn and
			not exists (select 'x' from RmMst where RmCtg= OtRmCtg
			and RmSCtg= OtRmSCtg and RmCd= OtRmCd and RmPrtKey=OtPrtKey and RmZ= 'N')
		if @row> 0
		begin
			select @errmsg= 'Raw Material Code Not Defined'
			goto ErrHndlr
		end	*/
	End
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

/****** Object:  Trigger dbo.ClrSet_INUPDL    Script Date: 02/04/05 10:28:06 AM ******/
ALTER TRIGGER [ClrSet_INUPDL] ON [ClrSet] 
    FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'ClrSet' )
		RETURN
	select @mode=case (select count('x') from inserted) when 0 then 'D'
		     else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
		     end
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where
			 not exists (Select 'x' from inserted ins where ins.CsCd= del.CsCd)
		If @Row > 0
		Begin
			Select @ErrMsg= 'Cannot Change Color Code'
			GoTo ErrHndlr
		End
	End
	if @mode in ('A','C')
	begin
		/****** CsCd <> '' ******/
		select @row= count('x') from inserted where CsCd= ''
		if @row> 0
		Begin
			select @errmsg= 'Color Code Cannot Be Blank'
			goto ErrHndlr
		end
		/****** CsName <> '' ******/
		select @row=count('x') from inserted where CsName= ''
		if @row>0
		Begin
			select @errmsg= 'Description Cannot Be Blank'
			goto ErrHndlr
		end
		/****** Cs3D = Valid PMCd('YN')  ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where
				    PTyp='YN' and PMCd= Cs3D)
		if @row> 0
		Begin
			select @errmsg= 'Object 3D Option Not Defined'
			goto ErrHndlr
		end
		/****** CsGrdInset = Valid PMCd('YN')  ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where
				    PTyp='YN' and PMCd= CsGrdInset)
		if @row> 0
		Begin
			select @errmsg= 'Grid Appearance Option Not Defined'
			goto ErrHndlr
		end
		/****** CsEdit = Valid PMCd('YN')  ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where
				    PTyp= 'YN' and PMCd= CsEdit)
		if @row> 0
		Begin
			select @errmsg= 'Record Editability Not Defined'
			goto ErrHndlr
		end
		/****** CsBtnHeightSet1, CsBtnHeightSet1, CsBtnWidthSet1, CsBtnHeightSet2,
			CsBtnWidthSet2, CsADCBtnHeight, CsADCBtnWidth, CsTlBarBtnHeight,
			CsTlBarBtnWidth > 0  ******/
		select @row= count('x') from inserted where
			CsBtnHeightSet1< 0 Or CsBtnWidthSet1< 0 Or
			CsBtnHeightSet2< 0 Or CsBtnWidthSet2< 0 Or CsADCBtnHeight< 0 Or
			CsADCBtnWidth< 0 Or CsTlBarBtnHeight< 0 Or CsTlBarBtnWidth< 0
		if @row> 0
		Begin
			select @errmsg= 'Button Height/ Width Should Be >= Zero'
			goto ErrHndlr
		end
		/****** Atleast the Height or Width Should Be Zero  ******/
		select @row= count('x') from inserted where
			CsBtnHeightSet1<> 0 and CsBtnWidthSet1<> 0
		if @row> 0
		Begin
			select @errmsg= 'Set1 Button Height Or Width Should Be Zero'
			goto ErrHndlr
		end
		/****** Atleast the Height or Width Should Be Zero  ******/
		select @row= count('x') from inserted where
			CsBtnHeightSet2<> 0 and CsBtnWidthSet2<> 0
		if @row> 0
		Begin
			select @errmsg= 'Set2 Button Height Or Width Should Be Zero'
			goto ErrHndlr
		end
		/****** Atleast the Height or Width Should Be Zero  ******/
		select @row= count('x') from inserted where
			CsADCBtnHeight<> 0 and CsADCBtnWidth<> 0
		if @row> 0
		Begin
			select @errmsg= 'ADC Button Height Or Width Should Be Zero'
			goto ErrHndlr
		end
		/****** Atleast the Height or Width Should Be Zero  ******/
		select @row= count('x') from inserted where
			CsTlBarBtnHeight<> 0 and CsTlBarBtnWidth<> 0
		if @row> 0
		Begin
			select @errmsg= 'Tool Bar Button Height Or Width Should Be Zero'
			goto ErrHndlr
		end
		/*
		CsBtnTopDiffSet1, CsBtnLeftDiffSet1, CsBtnTopDiffSet2,
		CsBtnLeftDiffSet2, CsADCDiffTop, CsADCDiffLeft,
		CsTlBarBtnGap
		*/
		/****** Picture Fields ******/
		/****** CsFlxPic, CsHlpPic can be blank ******/
		/****** CsMDIPic, CsFormPic, CsBtnPicSet1, CsBtnPicSet2, CsADCBtnPic, CsTlBarPic cannot be blank ******/
		select @row= count('x') from inserted where CsCd<> 'DFCLR' and
			(CsMDIPic= '' or CsFormPic= '' or CsBtnPicSet1= '' or CsBtnPicSet2= ''
			or CsADCBtnPic= '' or CsTlBarPic= '')
		if @row> 0
		Begin
			select @errmsg= 'MDI/ Form/ Button/ ADC/ ToolBar Picture Paths Cannot Be Blank'
			goto ErrHndlr
		end
		/****** Colour Codes <> '' ******/
		select @row= count('x') from inserted where (CsMedBckClr = ''
			or CsMedForClr = '' or CsMedBckClrDisa = '' or CsMedBckClrSel = ''
			or CsLblForClr = '' or CsFlxBckClr = '' or CsFlxBckClrBkg = ''
			or CsFlxBckClrFix = '' or CsFlxBckClrSel = '' or CsFlxBckClrSelRow = ''
			or CsFlxBckClrSelTxt = '' or CsFlxForClr = '' or CsFlxForClrFix = ''
			or CsFlxForClrSel = '' or CsFlxForClrSelTxt = '' or CsFlxGrdClr = ''
			or CsFlxGrdClrFix = '' or CsFlxGrdClrFix1 = '' or CsBtnForClrSet1 = ''
			or CsBtnDisaClrSet1 = '' or CsBtnMaskClrSet1 = '' or CsBtnForClrSet2 = ''
			or CsBtnDisaClrSet2 = '' or CsBtnMaskClrSet2 = '' or CsADCBtnForClr = ''
			or CsADCBtnDisaClr = '' or CsADCBtnMaskClr = '' or CsHlpBckClr = ''
			or CsHlpBckClrBkg = '' or CsHlpBckClrFix = '' or CsHlpBckClrSel = ''
			or CsHlpBckClrSelRow = '' or CsHlpForClr = '' or CsHlpForClrFix = ''
			or CsHlpForClrSel = '' or CsHlpGrdClr = '' or CsHlpGrdClrFix = ''
			or CsSysActiveCaption = '' or CsSysMenu = '' or CsSysWindowFrame = ''
			or CsSysMenuText = '' or CsSysCaptionText = '' or CsSysHighLight = ''
			or CsSysHighLightText = '' or CsSysBtnFace = '' or CsSysBtnShadow = ''
			or CsSysGrayText = '' or CsSysBtnText = '' or CsSysBtnHighLight = ''
			or CsTabBckClr = '' or CsTabPgClr = '' or CsTabBorderClr = ''
			or CsTabShadowClr = '' or CsTabForClr = '' or CsTabHighLightClr = ''
			or CsLblMainClr = '' or CsLineBdrClr = '' or CsTlBarBtnForClr = ''
			or CsTlBarBtnDisaClr = '' or CsTlBarBtnMaskClr = ''
			or CsDstForClr = '' or CsDstBckClr = '' 
			/*** (Jen 2.14 Patch 1 ***/ 
			or CsFraBckClr= ''
			/*** (Jen 2.14 Patch 1 ***/ 
			)
		if @row> 0
		Begin
			select @errmsg= 'Colour Values Cannot Be Blank'
			goto ErrHndlr
		end
		/* Select SUBSTRING(CsMDIPic, 1, 1), (case when SUBSTRING(CsMDIPic, 1, 8000)= 0x3000 then 'a' else 'b' end) as CsMDIPic from ClrSet where CsCd= 'AA' */
		/****** Picture Field Cannot Be Blank  ******/
		/* CsFormPic, CsFlxPic, CsBtnPicSet1, CsBtnPicSet2, CsADCBtnPic, CsHlpPic, CsMDIPic, CsTlBarPic */
/*		select @row= count('x') from inserted where
			(DataLength(CsFormPic)<= 2 and SUBSTRING(CsMDIPic, 1, 2)= 0x3000)
			Or (DataLength(CsFlxPic)<= 2 and SUBSTRING(CsFlxPic, 1, 2)= 0x3000)
			Or (DataLength(CsBtnPicSet1)<= 2 and SUBSTRING(CsBtnPicSet1, 1, 2)= 0x3000)
			Or (DataLength(CsBtnPicSet2)<= 2 and SUBSTRING(CsBtnPicSet2, 1, 2)= 0x3000)
			Or (DataLength(CsADCBtnPic)<= 2 and SUBSTRING(CsADCBtnPic, 1, 2)= 0x3000)
			Or (DataLength(CsHlpPic)<= 2 and SUBSTRING(CsHlpPic, 1, 2)= 0x3000)
			Or (DataLength(CsMDIPic)<= 2 and SUBSTRING(CsMDIPic, 1, 2)= 0x3000)
			Or (DataLength(CsTlBarPic)<= 2 and SUBSTRING(CsTlBarPic, 1, 2)= 0x3000)
		if @row> 0
		Begin
			select @errmsg= 'Picture Fields Cannot Be Blank'
			goto ErrHndlr
		end
*/
	End
	/****** If In Use Do Not Allow Delete ******/
	if @mode = 'D'
	Begin
		/****** Check For Use In Param ******/
		select @row= count('x') from deleted del where CsCd= 'DFCLR'
		if @row> 0
		Begin
			select @errmsg= 'Cannot Delete Default Color Code'
			goto ErrHndlr
		end
		/****** Check For Use In Param ******/
		select @row= count('x') from deleted del where
			exists (select 'x' from Param where PTyp= 'USR' and PValue2= CsCd)
			or exists (select 'x' from Param where PTyp= 'DEFCLR' and PValue= CsCd)
		if @row> 0
		Begin
			select @errmsg= 'Cannot Delete As Color Cd Used In Param (Type= USR or DEFCLR)'
			goto ErrHndlr
		end
	End
	return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
END

GOGO

/****** Object:  Trigger dbo.Param_INUPDL    Script Date: 18/03/01 12:20:00 AM ******/
ALTER TRIGGER [cParam_INUPDL] ON [cParam] 
           FOR INSERT,UPDATE,DELETE
		   NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @PTyp varchar(8)
	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'cParam' )
		RETURN

	Set DateFormat DMY 

	/***Geeta****From CRM 2.12 Onwards 
	NOTE::	***PTYP  Should be Unique in Param,vParam & cParam*****************/ 


	/****** Determining whether the trigger has been called in an insert, update or delete mode ******/
	/****** If there no records in inserted the the mode is 'Delete' 			         ******/
	/****** If there no records in deleted the the mode is 'Insert' 				         ******/
	/****** If there records in both inserted and deleted the the mode is 'Update' 		         ******/
	select @mode=case (select count('x') from inserted) when 0 then 'D'
	else
	case (select count('x') from deleted) when 0 then 'A' else 'C' end
       	end 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		 if @mode in ('A','C','D')
		 Begin  
			 if Not exists (Select 'x' From SysDb where SysId='CRM' and  SysDb ='WEB' )   
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

 	/******** Records Of Only One PTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(cPTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One PTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(cPTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/*** Storing PTyp In The Variable @PTyp ***/
	select @PTyp= case  when @mode in ('C', 'A') then (Select max(cPTyp) from inserted)  else (Select max(cPTyp) from deleted) end  



	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	select @Row=Count('x') from cParam cPm where (@PTyp= 'PTYP') or 
		(cPm.cPTyp= 'PTYP' and cPm.cPMCd= @PTyp and cPm.cPValue= 'M')
	If @Row > 0
	begin 
		Select @ErrMsg= 'Cannot Add/Change/Delete Microway Parameter - '+ @PTyp
		GoTo ErrHndlr
	end		


 	/******** Key Cannot Be Changed  (i.e. cPTyp, cPMCd and cPSCd cannot be changed) ********/ 
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.cPTyp= del.cPTyp and ins.cPMCd= del.cPmCd and ins.cPSCd= del.cPSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Crm Param Key'
			GoTo ErrHndlr
		end
	End


	if @mode in ('A','C')
	BEGIN
		/*** Only a valid PTyp can be entered (i.e. a valid cPMCd from cParam where cPTyp= 'PTYP') ***/
		select @row=count('x') from inserted ins where ins.cPTyp<> 'PTYP' and 
		not exists (select 'x' from cParam cPrm where cPrm.cPTyp='PTYP' and cPrm.cPMCd= ins.cPTyp)
		if @row>0 
		begin
			select @errmsg='Parameter Type Not Defined'
			goto ErrHndlr
		end
		/*** PMCd cannot be Blank ***/
		select @row= count('x') from inserted where cPMCd= ''  and cPTyp<>'DEFCRMYY'
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end
/* Zubin ('DSGLMT' added) */
		/***  PDesc cannot be blank ***/
		select @row= count('x') from inserted where cPDesc= '' and cPTyp Not in ('LAB','DEFCRMYY', 'DSGLMT')
		if @row>0 
		begin
			select @errmsg= 'Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @PTyp= 'CRMCHR'
		Begin 
			/****** cPSCd = Blank ******/
			select @row= count('x') from inserted where cPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue = ('YN') ******/
			select @row= count('x') from inserted 
				where cPValue not in (Select PMCd From Param where PTyp='YN')
			if @row>0 
			begin
				select @errmsg= 'Enter Running Sr UserWise (Y)/User Customer wise(N).'
				goto ErrHndlr
			end
			/****** Cannot Change Running Sr if OrdMst Rec Exists  ******/
			select @row= count('x') from inserted  ins
				where @Mode='C' and cPValue <> (Select cPValue From Deleted Del where del.cPTyp=ins.cPTyp
						and del.cPMCd=ins.cPMCd and Del.cPScd=ins.cPSCd)
				and Exists (Select 'x' From OrdMst where OmChr='WEB' and OmCrmChr=cPMCd)
			if @row>0 
			begin
				select @errmsg= 'Cannot Change Running Sr. when Orders exists.'
				goto ErrHndlr
			end
			/****** cPNum = 0 ******/
			select @row= count('x') from inserted where cPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** cPDesc225 = Blank ******/
			select @row= count('x') from inserted  where cPDesc225<>''
			if @row> 0 
			begin
				select @errmsg= 'cPDesc225 should be Blank'
				goto ErrHndlr
			end
			/****** cPValue1 = Blank ******/
			select @row= count('x') from inserted where cPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPNum1 = 0 ******/
			select @row= count('x') from inserted where cPNum1<> 0
			if @row>0 
