			end
			/****** cPValue3 = Blank ******/
			select @row= count('x') from inserted where cPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValidYN = Blank ******/
			select @row= count('x') from inserted where cPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'cPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End


		if @PTyp= 'DEFCRMYY'
		Begin
			/********One Record Permitted*************/
			/*select @row= count('x') from cParam where @Mode='A' and cPTyp=@PTyp
				Having Count('x')>1  
			if @row>0 
			begin
				select @errmsg= 'Only one Default Crm Yy is Permitted'
				goto ErrHndlr
			end
			*/
			/****** cPMCd = Blank ******/
			select @row= count('x') from inserted where cPMCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Main Code Should Be Blank'
				goto ErrHndlr
			end

			/****** cPSCd = Blank ******/
			select @row= count('x') from inserted where cPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/***  cPDesc Should be blank ***/
			select @row= count('x') from inserted where cPDesc<>'' 
			if @row>0 
			begin
				select @errmsg= 'Description Should Be Blank'
				goto ErrHndlr
	  		end

			/****** cPValue = Valid PMCd ('YY') ******/
			select @row= count('x') from inserted where 
				Not Exists(Select 'x' From Param where PTyp='YY' and PMCd=cPValue)
			if @row>0 
			begin
				select @errmsg= 'Year Not Defined'
				goto ErrHndlr
			end
				if @row>0 
			/****** cPNum = 0 ******/
			select @row= count('x') from inserted where cPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** cPDesc225 = Blank ******/
			select @row= count('x') from inserted  where cPDesc225<>''
			if @row> 0 
			begin
				select @errmsg= 'cPDesc225 should be Blank'
				goto ErrHndlr
			end
			/****** cPValue1 = Blank ******/
			select @row= count('x') from inserted where cPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPNum1 = 0 ******/
			select @row= count('x') from inserted where cPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** cPValue2 = Blank ******/
			select @row= count('x') from inserted where cPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue3 = Blank ******/
			select @row= count('x') from inserted where cPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValidYN = Blank ******/
			select @row= count('x') from inserted where cPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'cPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End


		if @PTyp= 'LAB'
		Begin 
			/**********Insert Not Allowed**************************/
			select @row= count('x') from inserted where @mode='A'
			if @row>0 
			begin
				select @errmsg= 'Cannot Insert a record for PTyp=''Lab'''
				goto ErrHndlr
			end
			/********LabMCd already specified*************/
			select @row= count('x') from inserted ins where 
			 (Select Count('x') From cParam cp where cp.cPTyp='LAB' and cp.cPValue=ins.cPValue)>1  
			if @row>0 
			begin
				select @errmsg= 'Labour Main Code already specified'
				goto ErrHndlr
			end
			/****** cPSCd = Blank ******/
			select @row= count('x') from inserted where cPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue = '' ******/
			select @row= count('x') from inserted where cPValue<>'' and
				Not exists (Select 'x' From Param where PTyp='LABMCD' and PMCd=cPValue) 
			if @row>0 
			begin
				select @errmsg= 'Enter a Valid labour Main Code'
				goto ErrHndlr
			end
			/****** cPNum = 0 ******/
			select @row= count('x') from inserted where cPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** cPDesc225 = Blank ******/
			select @row= count('x') from inserted  where cPDesc225<>''
			if @row> 0 
			begin
				select @errmsg= 'cPDesc225 should be Blank'
				goto ErrHndlr
			end
			/****** cPValue1 = Blank ******/
			select @row= count('x') from inserted where cPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPNum1 = 0 ******/
			select @row= count('x') from inserted where cPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** cPValue2 = Blank ******/
			select @row= count('x') from inserted where cPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue3 = Blank ******/
			select @row= count('x') from inserted where cPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValidYN = Blank ******/
			select @row= count('x') from inserted where cPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'cPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End

/* Zubin */ 
		if @PTyp= 'DSGLMT'
		Begin 
			/**********Insert Not Allowed**************************/
			select @row= count('x') from inserted where @mode='A'
			if @row>0 
			begin
				select @errmsg= 'Cannot Insert a record for PTyp=''DSGLMT'''
				goto ErrHndlr
			end
			/****** cPSCd = Blank ******/
			select @row= count('x') from inserted where cPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue = '' ******/
			select @row= count('x') from inserted where cPValue<>''
			if @row>0 
			begin
				select @errmsg= 'cPValue Should Be Blank'
				goto ErrHndlr
			end
			/****** cPNum = 0 ******/
			select @row= count('x') from inserted where cPNum= 0 
			if @row>0 
			begin
				select @errmsg= 'Max Limit Cannot Be Zero'
				goto ErrHndlr
			end
			/****** cPDesc225 = Blank ******/
			select @row= count('x') from inserted  where cPDesc225<>''
			if @row> 0 
			begin
				select @errmsg= 'cPDesc225 should be Blank'
				goto ErrHndlr
			end
			/****** cPValue1 = Blank ******/
			select @row= count('x') from inserted where cPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPNum1 = 0 ******/
			select @row= count('x') from inserted where cPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'cPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** cPValue2 = Blank ******/
			select @row= count('x') from inserted where cPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValue3 = Blank ******/
			select @row= count('x') from inserted where cPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'cPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** cPValidYN = Blank ******/
			select @row= count('x') from inserted where cPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'cPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End
/* Zubin */ 

	end
	if @mode in ('D')
		BEGIN
			/*** In Use Checks ***/
			if @PTyp= 'CRMCHR' 
			Begin 
				/****** Cannot delete CRMCHR in use in OrdMst table ******/
				select @row= count('x') from deleted del where 
					exists (select 'x' from OrdMst where OmCrmChr= cPMCd and cPSCd='')
				if @row> 0 
				begin
					select @errmsg= 'Cannot Delete As Crm character In Use In OrdMst Table ' 
					goto ErrHndlr
				end 
			End

		if @PTyp= 'LAB'
		Begin 
			
			select @row= count('x') from Deleted
			if @row>0 
			begin
				select @errmsg= 'Cannot Delete a Record for PTyp=''Lab'''
				goto ErrHndlr
			end
		End

/* Zubin */ 
		if @PTyp= 'DSGLMT'
		Begin 
			
			select @row= count('x') from Deleted
			if @row>0 
			begin
				select @errmsg= 'Cannot Delete a Record for PTyp=''DSGLMT'''
				goto ErrHndlr
			end
		End
/* Zubin */ 			
		
	END



return
ErrHndlr:
begin
	select @errmsg='|'+@errmsg
	raiserror(@errmsg,16,1)
	rollback transaction 
		end
end

GOGO

ALTER TRIGGER [CrmCustDsg_INUPDL] ON [CrmCustDsg] 
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0
		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CrmCustDsg' )
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
				case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end 
		
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin		
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		 if @mode in ('A','C','D')
		 Begin  
			 if not exists (Select 'x' From SysDb where SysId='CRM' and  SysDb ='WEB' )   
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

	select @row=count('x') from inserted where  
		not exists (select 'x' from Param  where 
				PTyp='DMTCTYP' and  PMCd=ccdDmTcTyp and PSCd='' and PMCd<>'PM')
	if @row>0 
	Begin
		select @errmsg='DMTCTYP Not Defined'
		goto ErrHndlr
	end
 
	select @row=count('x') from inserted where not exists (select 'x' from CrmCustMst where 
			CcCmCd= CcdCmCd)
	if @row>0 
	Begin
		select @errmsg='Customer Code Not Defined'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where 
		not exists (select 'x' from DsgMst where 
				DmTcTyp= ccdDmTcTyp and DmCd= CcdDmCd)
	if @row>0 
	Begin
		select @errmsg='Design Code Not Defined'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where CcdPrefSfx<>'' and CcdDmTcTyp='SM'
	if @row>0 
	Begin
		select @errmsg='Preferred Suffix Should be Blank for Sketch'
		goto ErrHndlr
	end

	/* NOT REQUIRED */ 
/*
	select @row=count('x') from inserted where CcdPrefSfx<>'' and CcdDmTcTyp='DM' and
		not exists( Select 'x' From OrdDsg Join OrdMst 
				on OmCoCd=OdCoCd and OmTc=OdTc and OmYy=OdYy and OmChr=OdChr and OmNo=OdNo 
				where ccdCmCd=OmCmCd and 
					OmTc in (Select PMCd From Param where PTyp='TC' and PValue='PL' and PSCd='') and
					CcdPrefSfx=OdSfx)
	if @row>0 
	Begin
		select @errmsg='Preferred Suffix not Defined'
		goto ErrHndlr
	end
*/

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end


GOGO

ALTER TRIGGER [CrmSzInst_INUPDL] ON [CrmSzInst] 
       FOR INSERT,UPDATE,DELETE
		NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0   RETURN
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CrmSzInst' )
	RETURN
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'
	else
		case (select count('x') from deleted) when 0 then 'A' else 'C' end
	end
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
	
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin
			if Not exists (Select 'x' From SysDb where SysId='CRM' and  SysDb ='WEB' )
			Begin
				select @errmsg= 'Cannot Insert /Update /Delete '
				goto ErrHndlr
			end
		  End
	end		

	/******** Key Cannot Be Changed ********/
	if @mode = 'C'
	Begin
		select @Row= Count('x') from deleted del where
		not exists (Select 'x' from inserted ins where ins.csiCmCd = del.csiCmCd)
		If @Row > 0
		Begin
			Select @ErrMsg= 'Cannot Change Customer Code'
			GoTo ErrHndlr
		End
	End
	
	if @mode in ('A','C')
	begin
		  /****** Customer Code Cannot be Blank ******/
		  select @row=count('x') from inserted where   csiCmCd = ''
		  if @row>0
		  Begin
			select @errmsg='Customer Code Cannot be Blank'
			goto ErrHndlr
		  end
		 /****** Design Category Cannot be Blank ******/
		  select @row=count('x') from inserted where   csiDmCtg = ''
		  if @row>0
		  Begin
			select @errmsg='Design Category Cannot be Blank'
			goto ErrHndlr
		  end
	
		 /****** Design Category Cannot be Blank ******/
		  select @row=count('x') from inserted where   csiSzInst = ''
		  if @row>0
		  Begin
			select @errmsg='Size Instruction Cannot be Blank'
			goto ErrHndlr
		  end
	End
return
ErrHndlr:
 begin
  select @errmsg='|'+@errmsg
  raiserror(@errmsg,16,1)
  rollback transaction
 end
END

GOGO

/****** Object:  Trigger dbo.CrmUsr_INUPDL    Script Date: 26/09/05 ******/  
ALTER TRIGGER [CrmUsr_INUPDL] ON [CrmUsr] 
       FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
 DECLARE @ROW INT  
 DECLARE @mode char(1)  
 DECLARE @errmsg varchar(255)  
 DECLARE @ReplAgt BIT  
	  
 IF @@ROWCOUNT=0   RETURN  
  
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CrmUsr' )  
  RETURN  
  
 select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
   case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   
  
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin	 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin  
			 if Not exists (Select 'x' From SysDb where SysId='CRM' and  SysDb ='WEB' )   
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

  /******** Key Cannot Be Changed ********/   
  if @mode = 'C'  
  Begin  
	  select @Row= Count('x') from deleted del where   
	    not exists (Select 'x' from inserted ins where ins.cuUsrCd= del.cuUsrCd)  
	  If @Row > 0  
	  Begin   
	   Select @ErrMsg= 'Cannot Change Crm User Code'  
	   GoTo ErrHndlr  
	  End  
  End	  
    
 if @mode in ('A','C')  
 begin  
	  /****** Usr Code Cannot be Blank ******/  
	  select @row=count('x') from inserted where   cuUsrCd=''
	  if @row>0   
	  Begin  
	   select @errmsg='User Code Cannot be Blank'  
	   goto ErrHndlr  
	  end  
	
	 /****** Usr Code Cannot be Blank ******/  
	  select @row=count('x') from inserted where   cuUsrName=''
	  if @row>0   
	  Begin  
	   select @errmsg='User Name Cannot be Blank'  
	   goto ErrHndlr  
	  end  


	 /****** cuDefCrmYY= Valid PMCD(PTyp='YY')  ******/  
	  select @row=count('x') from inserted 
		where Not exists (Select 'x' From Param where PTyp='YY' and PMCd=cuDefCrmYY)
	  if @row>0   
	  Begin  
	   select @errmsg='Yy Not Defined'  
	   goto ErrHndlr  
	  end  
	
	 /****** cuCrmChrPermit<>''  ******/  
	  select @row=count('x') from inserted Where cuCrmChrPermit=''
	  if @row>0   
	  Begin  
	   select @errmsg='Permitted Chr Cannot be Blank'  
	   goto ErrHndlr  
	  end  

	 /****** cuCrmChrPermit cannot be allotted to more than one User  ******/  
	 Select @row= Count('x') From Inserted where  
		Exists(select cPMCd,Count('x') From CrmUsr 
			Join cParam On  cPTyp='CRMCHR' and ','+cuCrmChrPermit+',' Like '%,'+cPMCd +',%'
			where Exists (Select  'x' From Inserted where ','+cuCrmChrPermit+',' Like '%,'+cPMCd +',%')
			Group By cPMCd	Having Count('x') >1 ) 
	  if @row>0   
	  Begin  
	   select @errmsg='Same CrmChr Cannot be Assigned To more than one User'  
	   goto ErrHndlr  
	  end  

	  
	 /****** cuDefCrmChr= Valid cPMCD(cPTyp='CRMCHR')  ******/  
	  select @row=count('x') from inserted 
		where  ','+cuCrmChrPermit+',' Not Like '%,'+cuDefCrmChr+',%' 
	  if @row>0   
	  Begin  
	   select @errmsg='This Default Crm Chr is Not Permitted for This User'  
	   goto ErrHndlr  
	  end  
	  
	  
 End  
  
  
 /****** If In Use Do Not Allow Delete ******/  
 if @mode = 'D'   
 Begin  
	select @row= count('x') from deleted del where cuUsrCd='ZSELF'
	  if @row> 0   
	  Begin  
	   select @errmsg= 'Cannot Delete User ''ZSELF'' '  
	   goto ErrHndlr  
	end  

	select @row= count('x') from deleted del where 
	  exists (select 'x' from CrmUsrCust where cuUsrCd= cucUsrCd)  
	  if @row> 0   
	  Begin  
	   select @errmsg= 'Cannot Delete As Crm User Code In Use In CrmUsrCust Table'  
	   goto ErrHndlr  
	end  
	select @row= count('x') from deleted del where 
	  exists (select 'x' from CrmCustMst where ccPrimeUsr= cuUsrCd)  
	  if @row> 0   
	  Begin  
	   select @errmsg= 'Cannot Delete As Crm User Code In Use In CrmCustMst Table'  
	   goto ErrHndlr  
	end  

  End  
  
 return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  


GOGO

/****** Object:  Trigger dbo.CrmUsrCust_INUPDL    Script Date: 26/09/05 ******/  
ALTER TRIGGER [CrmUsrCust_INUPDL] ON [CrmUsrCust] 
       FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
 DECLARE @ROW INT  
 DECLARE @mode char(1)  
 DECLARE @errmsg varchar(255)  
 DECLARE @wSelfCd VARCHAR(8)  
 Declare @wSr Integer
 DECLARE @ReplAgt BIT  
  
 IF @@ROWCOUNT=0   RETURN  
  
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CrmUsrCust' )  
  RETURN  
  
 select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
   case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   

 Select  @wSelfCd='ZSELF'
  
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin  
			 if Not exists (Select 'x' From SysDb where SysId='CRM' and  SysDb ='WEB' )   
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End		
  /******** Key Cannot Be Changed ********/   
  if @mode = 'C'  
  Begin  
	  select @Row= Count('x') from deleted del where   
	    not exists (Select 'x' from inserted ins where ins.cucUsrCd= del.cucUsrCd and ins.cucCmCd= del.cucCmCd )  
	  If @Row > 0  
	  Begin   
	   Select @ErrMsg= 'Cannot Change Crm User Code and Customer Code'  
	   GoTo ErrHndlr  
	  End  
  End	  
    
 if @mode in ('A','C')  
 begin  
	 /****** cucUsrCd=Valid cuUsrCd From CrmUsr ******/  
	  select @row=count('x') from inserted 
		where Not Exists(Select 'x' From CrmUsr where cucUsrCd=cuUsrCd)
	  if @row>0   
	  Begin  
	   select @errmsg='Crm User not Defined'  
	   goto ErrHndlr  
	  end  

	 /****** cucCmCd=Valid ccCmCd From CrmCustMst ******/  
	  select @row=count('x') from inserted 
		where Not Exists(Select 'x' From CrmCustMst where cucCmCd=ccCmCd)
	  if @row>0   
	  Begin  
	   select @errmsg='Crm Customer not Defined'  
	   goto ErrHndlr  
	  end  

	 /****** cucSfDmctg=Valid PMCD where PTyp='DMCTG' ******/  
	  select @row=count('x') from inserted where cucSfDmCtg <>'' and
		 Not Exists(Select 'x' From Param where PTyp='DMCTG' and PMCd=cucSfDmCtg)
	  if @row>0   
	  Begin  
	   select @errmsg='Design Category not Defined'  
	   goto ErrHndlr  
	  end  

	 /****** cucSfDmSalctg=Valid PSCD where PTyp='SALCTG' and PMCd=cucSfDmCtg ******/  
	  select @row=count('x') from inserted where cucSfDmSalCtg<>'' and
		 Not Exists(Select 'x' From Param where PTyp='SALCTG' and PMCd=cucSfDmCtg and PSCd=cucSfDmSalCtg)
	  if @row>0   
	  Begin  
	   select @errmsg='Sales Category not Defined '  
	   goto ErrHndlr  
	  end  

	 /****** cucSfDmtcTyp=Valid PMCd where PTyp='DMTCTYP' ******/  
/*	  select @row=count('x') from inserted 
		where Not Exists(Select 'x' From Param  where PTyp='DMTCTYP' and PmCd=cucSfDmTcTyp)
	  if @row>0   
	  Begin  
	   select @errmsg='Invalid DmTcTyp'  
	   goto ErrHndlr  
	  end  
*/
	 /******cucPrefGrMet=Valid GrCd From Grade where GrTyp='MET' and GrCmcd in (cucCmCd,'ZSELF') ******/  
	  select @row=count('x') from inserted ins 
		where  cucPrefGrMet<>'' and 
			/*(@Mode='A' or Not Exists(Select 'x' From Deleted del where ins.cucPrefGrMet=del.cucPrefGrMet )) and */
			 Not Exists(Select 'x' From Grade where GrTyp='MET' and GrCmCd =cucCmCd and GrCd=cucPrefGrMet)
	  if @row>0   
	  Begin  
	   select @errmsg='Preferred Metal Grade not defined for this Customer '  
	   goto ErrHndlr  
	  end  

	 /******cucPrefGrDia=Valid GrCd From Grade where GrTyp='DIA' and GrCmcd =cucCmCd ******/  
	  select @row=count('x') from inserted ins 
		where cucPrefGrDia<>'' and 
			/* (@Mode='A' or Not Exists(Select 'x' From Deleted del where ins.cucPrefGrDia=del.cucPrefGrDia )) and  */
			Not Exists(Select 'x' From Grade where GrTyp='DIA' and GrCmCd = cucCmCd and GrCd=cucPrefGrDia)
	  if @row>0   
	  Begin  
	    select @errmsg='Preferred Diamond Grade not defined for this Customer '  
	   goto ErrHndlr  
	  end  

	 /****** cucPrefGrCs=Valid GrCd From Grade where GrTyp='CS' and GrCmcd =cucCmCd******/  
	  select @row=count('x') from inserted ins 
		where cucPrefGrCS<>'' and 
		/*	(@Mode='A' or Not Exists(Select 'x' From Deleted del where ins.cucPrefGrCS=del.cucPrefGrCS )) and */
			 Not Exists(Select 'x' From Grade where GrTyp='CS' and GrCmCd =cucCmCd and GrCd=cucPrefGrCS)
	  if @row>0   
	  Begin  
	    select @errmsg='Preferred Color Stone Grade not defined for this Customer '  
	   goto ErrHndlr  
	  end  

		 /******cucPrefGrFin=Valid GrCd From Grade where GrTyp='FIN' and GrCmcd in (cucCmCd,'ZSELF') ******/  
		  select @row=count('x') from inserted ins 
			where cucPrefGrFin<>'' and 
			/*	(@Mode='A' or Not Exists(Select 'x' From Deleted del where ins.cucPrefGrFin=del.cucPrefGrFin )) */
				 Not Exists(Select 'x' From Grade where GrTyp='CS' and GrCmCd =cucCmCd and GrCd=cucPrefGrFin)

		  if @row>0   
		  Begin  
		    select @errmsg='Preferred Finish Grade not defined for this Customer '  
		   goto ErrHndlr  
		  end  


		/*****Previous Combination(cucCmbGrMet) Field Should be Entered to enter remaining Metal Combinations ******/
		select  @row= count('x')  From Inserted 
			where ((cucCmbGrMet1='' and (cucCmbGrMet2<>'' or cucCmbGrMet3<>''))
			Or (cucCmbGrMet2='' and cucCmbGrMet3<>''))
		if @row>0 
		Begin
			select @errmsg='Previous Combination  Fields cannot be left Blank'
			goto ErrHndlr
		end

		/*****Previous Combination(cucCmbGrDia) Field Should be Entered to enter remaining Diamond Combinations ******/
		select  @row= count('x')  From Inserted 
			where 
			(
			(cucCmbGrDia1='' and (cucCmbGrDia2<>'' or cucCmbGrDia3<>'' Or cucCmbGrDia4<>'' or cucCmbGrDia5<>'')) Or
			(cucCmbGrDia2='' and (cucCmbGrDia3<>'' or cucCmbGrDia4<>'' Or cucCmbGrDia5<>'')) Or
			(cucCmbGrDia3='' and (cucCmbGrDia4<>'' or cucCmbGrDia5<>'' )) Or
			(cucCmbGrDia4='' and cucCmbGrDia5<>''))
		if @row>0 
		Begin
			select @errmsg='Previous Diamond Combination  Fields cannot be left Blank'
			goto ErrHndlr
		end

		/***** Check Combination Metal Grade Code1,2,3 =
			Valid GrCd From Grade where GrTyp='MET' and GrCmcd in (cucCmCd,'ZSELF') 
			if Combination Metal Grade Code1,2,3 <>'' ******/ 
		select @wSr= 1
		while (@wSr<= 3)
		Begin
			select @row= count('x') from inserted ins where 
			(Case @wSr When 1  then cucCmbGrMet1
				    When 2 Then cucCmbGrMet2
				    When 3 Then cucCmbGrMet3 end) <>'' 
		/*	and
			(@Mode='A' Or 
				(@Mode='C' and 
					Not Exists(Select 'x' From Deleted del 
							where  (@wSr=1 and ins.cucCmbGrMet1=del.cucCmbGrMet1) Or 
							       (@wSr=2 and ins.cucCmbGrMet2=del.cucCmbGrMet2) Or
							       (@wSr=3 and ins.cucCmbGrMet3=del.cucCmbGrMet3) 
						   )
				 )
			)
		*/
			and 
			Not Exists(Select 'x' From Grade where GrTyp='MET' and GrCmCd = cucCmCd
				and GrCd=(Case @wSr When 1 then cucCmbGrMet1
					    When 2 Then cucCmbGrMet2
					    When 3 Then cucCmbGrMet3 end))

			If @row> 0
				break
			else 
			Begin
				select @wSr= @wSr + 1
				Continue
			End
		End 
		if @row> 0 
		begin
			select @errmsg= 'Combination Metal Grade '+ LTrim(Str(@wSr))+'  not Defined'
			goto ErrHndlr
		end  			


		/***** Check Combination Diamond Grade Code1,2,3,4,5 =
			Valid GrCd From Grade where GrTyp='DIA' and GrCmcd in (cucCmCd,'ZSELF') 
			if Combination Metal Grade Code1,2,3,4,5 <>'' ******/ 
		select @wSr= 1
		while (@wSr<= 5)
		Begin
			select @row= count('x') from inserted ins where 
			(Case @wSr When 1  then cucCmbGrDia1
				    When 2 Then cucCmbGrDia2
				    When 3 Then cucCmbGrDia3 
				    When 4 Then cucCmbGrDia4
				    When 5 Then cucCmbGrDia5
			end) <>'' 
		/*	and
			(@Mode='A' Or 
				(@Mode='C' and 
					Not Exists(Select 'x' From Deleted del 
							where  (@wSr=1 and ins.cucCmbGrDia1=del.cucCmbGrDia1) Or 
							       (@wSr=2 and ins.cucCmbGrDia2=del.cucCmbGrDia2) Or
							       (@wSr=3 and ins.cucCmbGrDia3=del.cucCmbGrDia3) Or
							       (@wSr=4 and ins.cucCmbGrDia4=del.cucCmbGrDia4) Or
							       (@wSr=5 and ins.cucCmbGrDia5=del.cucCmbGrDia5) 
						   )
				 )
			)
		*/
			and 
			Not Exists(Select 'x' From Grade where GrTyp='DIA' and GrCmCd =cucCmCd
				and GrCd=(Case @wSr When 1 then cucCmbGrDia1
						    When 2 Then cucCmbGrDia2
						    When 3 Then cucCmbGrDia3 
						    When 4 Then cucCmbGrDia4 
						    When 5 Then cucCmbGrDia5 
					 end))

			If @row> 0
				break
			else 
			Begin
				select @wSr= @wSr + 1
				Continue
			End
		End 
		if @row> 0 
		begin
			select @errmsg= 'Combination Diamond Grade '+ LTrim(Str(@wSr))+'  not Defined'
			goto ErrHndlr
		end  			

	 /****** cucSfDiaWtTo>=cucSfDiaWtFr ******/  
	  select @row=count('x') from inserted 
		where Cast(cucSfDiaWtTo as Decimal(10,4)) <>0 and cucSfDiaWtTo<cucSfDiaWtFr

	  if @row>0   
	  Begin  
	   select @errmsg='From Diamond Wt Should be >= To Diamond Wt '  
	   goto ErrHndlr  
	  end  
	/****** cucSfDsgMRPTo>=cucSfDsgMRPFr ******/  
	  select @row=count('x') from inserted 
		where Cast(cucSfDsgMRPTo  as Decimal(10,4))<>0 and  cucSfDsgMRPTo<cucSfDsgMRPFr
	  if @row>0   
	  Begin  
	   select @errmsg='From Retail Price Should be >= To Retail Price '  
	   goto ErrHndlr  
	  end  
	/****** cucSfDsgPrcTo>=cucSfDsgPrcFr ******/  
	  select @row=count('x') from inserted 
		where   Cast(cucSfDsgPrcTo as Decimal(10,4)) <>0 And cucSfDsgPrcTo <cucSfDsgPrcFr
	  if @row>0   
	  Begin  
	   select @errmsg='From Unit Price Should be >= To Unit Price '  
	   goto ErrHndlr  
	  end  


	 /****** cucSort=Valid cPMCD where cPTyp='SRTOD' ******/  
	  select @row=count('x') from inserted where cucSort<>'' 
		and Not Exists(Select 'x' From cParam where cPTyp='SRTOD' and cPMCd=cucSort)
	  if @row>0   
	  Begin  
	   select @errmsg='Sort Option not Defined'  
	   goto ErrHndlr  
	  end  

	 /****** cucMRPYN=Valid PMCD where PTyp='YN' ******/  
	  select @row=count('x') from inserted where 
		 Not Exists(Select 'x' From Param where PTyp='YN' and PMCd=cucMRPYN)
	  if @row>0   
	  Begin  
	   select @errmsg='Show Retail Price (Enter Y/N)'  
	   goto ErrHndlr  
	  end  

	 /****** cucSfPrefSfxOnly=Valid PMCD where PTyp='YN' ******/  
	  select @row=count('x') from inserted where 
		 Not Exists(Select 'x' From Param where PTyp='YN' and PMCd=cucSfPrefSfxOnly)
	  if @row>0   
	  Begin  
	   select @errmsg='Show Designs in Preferred Suffix Only (Enter Y/N)'  
	   goto ErrHndlr  
	  end  


	
	 /****** cucCustDmCdYN=Valid PMCD where PTyp='YN' ******/  
	  select @row=count('x') from inserted where
		 Not Exists(Select 'x' From Param where PTyp='YN' and PMCd=cucCustDmCdYN)
	  if @row>0   
	  Begin  
	   select @errmsg='Show Customer Design Code (Enter Y/N)'  
	   goto ErrHndlr  
	  end  

	 /****** cucMRPMultfctr >0 ******/  
	  select @row=count('x') from inserted where cucMRPMultfctr<=0
	  if @row>0   
	  Begin  
	   select @errmsg='Retail Price Multiplication Factor Should be >0'  
	   goto ErrHndlr  
	  end  
 End  

	if @mode = 'A' 
	Begin  
	  Update CrmCustMst 
		Set ccPrimeUsr= cucUsrCd from Inserted where ccCmCd= cucCmCd and ccPrimeUsr= '' 
	End 
	
	if @mode = 'D'   
	Begin  
		select @row= count('x') from deleted where cucCmCd='ZSELF' and cucUsrCd='ZSELF'
		if @row> 0   
		Begin  
			select @errmsg= 'Cannot Delete ZSELF Record'  
			goto ErrHndlr  
		end 
	End 
 
   return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  


GOGO


ALTER TRIGGER [CustAly_INUPDL] ON [CustAly] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
 	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustAly' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
	
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
			If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
			exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	
	/* ---- rewrite trigger after new Mwf
	*/

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		select @Row=Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.CaCtg= del.CaCtg and ins.CaCd= del.CaCd and ins.CaRmCd= del.CaRmCd 
				     and ins.CaDmCol= del. CaDmCol)
		If @Row > 0
		Begin 
			Select @ErrMsg='Cannot Change Category/Customer Code/Rm Code/Design Colour'
			GoTo ErrHndlr
		End
	End

	select @row=count('x') from inserted where CaCtg<> 'C'
	if @row>0 
	Begin
		select @errmsg='Customer Category Should Be ''C'' '
		goto ErrHndlr
	end
	select @row=count('x') from inserted where 
		not exists (select 'x' from CustMst where 
			CmCtg= CaCtg and CmCd= CaCd)
	if @row>0 
	Begin
		select @errmsg='Customer Code Not Defined'
		goto ErrHndlr
	end
	/* **** Manali 3.03 - 18/06/08 - 'L' added **** */
	select @row=count('x') from inserted where 
		not exists (select 'x' from RmMst where RmCtg in ('G','P','S','L') and 
			RmCd= CaRmCd)
	if @row>0 
	Begin
		select @errmsg='RMCode Not Defined For Ctg Gold, Platinum, Silver, Palladium'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where 
		not exists (select 'x' from Param where 
			PTyp='DMCOL' and PMCd=CaDmCol)
	if @row>0 
	Begin
		select @errmsg='Design Colour Not Defined'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where 
		not exists (select 'x' from RmMst where RmCtg = 'A' and 
			RmCd= CaAlyCd)
	if @row>0 
	Begin
		select @errmsg='Alloy Code Not Defined'
		goto ErrHndlr
	end
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end

GOGO

ALTER TRIGGER [CustDsg_INUPDL] ON [CustDsg] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 
 
	IF @@ROWCOUNT=0 RETURN 

	Set @wCurrPrtn = 'C'
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustDsg' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
	
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		if @mode in ('A','C')
		begin
			Select @row=count('x') From Inserted Where CdPrtKey<>@wCurrPrtn
			if @row> 0 
			begin
				select @errmsg= 'Cannot Edit Records of Previous Partition'
				goto ErrHndlr
			end

			Select @row=count('x') From Inserted Where CdPrtKey <> @wCurrPrtn 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
				goto ErrHndlr
			end
		end 
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */	

		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	
	/* ---- rewrite trigger after new mwf 
	 1. Dsgn Check for DmSz=''
	*/

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		select @Row=Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins 
				where ins.CdCtg= del.CdCtg and ins.CdCd= del.CdCd and ins.CdOurDmCd= del.CdOurDmCd)
		If @Row > 0
		Begin 
			Select @ErrMsg='Cannot Change Category/Customer Code/Design Code'
			GoTo ErrHndlr
		End
	End

	select @row=count('x') from inserted where CdCtg Not in ('C','CC')
	if @row>0 
	Begin
		select @errmsg='Customer Category Should Be ''C''/''CC'' '
		goto ErrHndlr
	end

	select @row=count('x') from inserted where not exists (select 'x' from CustMst where 
			CmCtg= CdCtg and CmCd= CdCd)
	if @row>0 
	Begin
		select @errmsg='Customer Code Not Defined'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where 
		not exists (select 'x' from DsgMst where 
				DmTcTyp= 'DM' and DmCd= CdOurDmCd and DmPrtKey=CdPrtKey)
	if @row>0 
	Begin
		select @errmsg='Design Code Not Defined'
		goto ErrHndlr
	end
	select @row=count('x') from inserted where CdCustDmCd='' 
	if @row>0 
	Begin
		select @errmsg='Customer Design Code Cannot Be Blank'
		goto ErrHndlr
	end

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end

GOGO

ALTER TRIGGER [CustInst_INUPDL] ON [CustInst] 
   FOR INSERT,UPDATE,DELETE  
	NOT FOR REPLICATION
AS  
BEGIN
	/* Trigger Version 3.02.0 (Speed Optimization) */  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)
	Declare @wEntTyp Varchar(8)
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustInst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'
		
	/*** Storing Tc Type In The Variable @wTcTyp ***/
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where CiPrtKey<>@wCurrPrtn
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.CiCtg =del.CiCtg  and
									ins.CiCd =Del.CiCd  and ins.CiDmCtg =del.CiDmCtg 
									and ins.CiPrtKey <>del.CiPrtKey) 
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where CiPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.CiPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

  	if @mode in ('A','C')
	Begin

		/* Current Partition */
		select @row= count('x') from inserted where CiPrtKey=@wCurrPrtn and not exists 
			(select 'x' from Param where Ptyp='CMCTG' and PMCd = CiCtg)
		if @row> 0
		begin
			select @errMsg= 'Customer Category Code Not Valid'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where CiPrtKey=@wCurrPrtn and
			     not exists (select 'x' from CustMst where CmCtg=CiCtg and CmCd= CiCd)
		if @row> 0
		begin
			select @errmsg= 'Customer Code Not Defined'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where CiPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where Ptyp='DMCTG' and PMCd = CiDmCtg)
		if @row> 0
		begin
			select @errmsg= 'Design Category Not Defined'
			goto ErrHndlr
		end
		
		select @row= count('x') from inserted where CiPrtKey=@wCurrPrtn and CiCustPrdInst = ''
		if @row> 0
		begin
			select @errmsg= 'Customer Production Instruction cannot be blank'
			goto ErrHndlr
		end
	End

/*	If @Mode = 'C'
	Begin

	End */

/**	if @mode in ('D')
	Begin
			
	End  **/
Return
ErrHndlr:
	Begin
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	End
END


GOGO

ALTER TRIGGER [CustMst_INUPDL] ON [CustMst] 
       FOR INSERT,UPDATE,DELETE
		NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 2.14.0 Next */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @SYS VARCHAR(5)	
	DECLARE @ReplAgt BIT

	IF @@ROWCOUNT=0		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustMst' )
		RETURN

	select @mode=case (Select count('x') from inserted) when 0 then 'D'
		     Else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
		     End	

	set @wSelfCd = 'ZSELF'	
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin  
			If   Exists( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  Or  
				Exists (Select 'x' From SysDb where SysId='CRM' and SysDb ='WEB') 
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

	/* *** Jay 2.14 *** */
	/* *** Can Not Add/ Delete/ Update If User Level >5 *** */
	If @mode in ('A','C') and 
		((Select count('x') from Param join inserted ins on PTyp= 'USR' and PMCd= ins.ModUsr and PSCd= '' and PNum> 5)> 0)
 	Begin  
		Select @ErrMsg= 'Cannot Insert /Update As User Does Not Have This Rights'
		GoTo ErrHndlr
	End

	If @mode in ('D') and 
		((Select count('x') from Param join deleted del on PTyp= 'USR' and PMCd= del.ModUsr and PSCd= '' and PNum> 5)> 0) 
 	Begin  
		Select @ErrMsg= 'Cannot Delete As User Does Not Have This Rights'
		GoTo ErrHndlr
	End
	/* *** Jay 2.14 *** */

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd)
		If @Row > 0
		Begin 
			Select @ErrMsg= 'Cannot Change Category/Code'
			GoTo ErrHndlr
		End

		/****** If CmCtg= 'T' then CmCurncyCd cannot be changed if CTB Voucher Exists ******/
		select @Row= Count('x') from deleted del where CmCtg= 'T' and 
			not exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg 
				and ins.CmCd= del.CmCd and ins.CmCurCd= del.CmCurCd) and 
			exists(Select 'x' from InvHd where InCmCd= CmCd and 
				(Select PValue from Param where PTyp= 'TC' and PMCd= InTc)= 'CTB')
		If @Row> 0
		begin 
			Select @ErrMsg= 'Cannot Change Currency Code As CTB Invoice Exists'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	begin
		/****** Emr 211 (CmCtg-CmName Comb shld be unique) ******/ 
/*		select @row= count('x') from inserted ins where 
			Exists (select 'x' from CustMst CM where ins.CmCd<> CM.CmCd and ins.CmCtg= CM.CmCtg and 
				ins.CmName= CM.CmName) 
*/

		select @row= count('x') from inserted ins where 
			(select count('x') from CustMst CM where ins.CmCtg= CM.CmCtg and 
				ins.CmName= CM.CmName)> 1 
		if @row> 0 
		Begin
			select @errmsg= 'CmCtg-CmName Should Be Unique' 
			goto ErrHndlr
		end

		/****** Valid Customer Category ******/
		select @row=count('x') from inserted where 
			not exists (select 'x' from Param where 
				    PTyp='CMCTG' and PMCd=CmCtg)
		if @row>0 
		Begin
			select @errmsg='Category Not Defined'
			goto ErrHndlr
		end

		/****** Contractor Code Can Be Defined Only If The Contractor Module Is To Be Used ******/
		select @row= count('x') from inserted where @mode = 'A' and CmCtg= 'T' and 
			not exists (select 'x' from Head where HCtbMod= 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Enter Contractor Code As ''Show Contractor Module'' Option Of Head File Is ''N'' '
			goto ErrHndlr
		end

		/****** CmCd <> '' ******/
		select @row= count('x') from inserted where CmCd= ''
		if @row> 0 
		Begin
			select @errmsg= 'Customer/Supplier Code Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmCd can be 'ZSELF' only if CmCtg= 'C' ******/
		/* CmCtg 'S' added Trading Module */
		select @row= count('x') from inserted where CmCd= 'ZSELF' and CmCtg not in ('C' , 'S')
		if @row> 0 
		Begin
			select @errmsg= ' ''ZSELF'' Can Only Belong To Catagory = ''C'' '
			goto ErrHndlr
		end

		/****** CmCd can be only HCoCd if CmCtg= 'Z' ******/ 
		select @row= count('x') from inserted where CmCtg= 'Z' and 
			not exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= CmCd)
			And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Company Code'
			goto ErrHndlr
		end

		/****** CmName <> '' ******/		
		select @row=count('x') from inserted where CmName= ''
		if @row>0 
		Begin
			select @errmsg='Customer/Supplier Name Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmName can be only HName if CmCtg= 'Z' ******/ 
		Select @row= Count('x') From Inserted Ins Where CmCtg= 'Z' And 
			Exists (Select 'x' From Deleted Del where Ins.CmCtg= del.CmCtg and Ins.CmCd= del.CmCd and 
				Ins.CmName<> del.CmName) And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Change the Company Name'
			goto ErrHndlr
		end
		
		/* Commented By Sachin in 2.14.0 Next to allow longer company names in Company Master */
		/*
		select @row= count('x') from inserted ins where CmCtg= 'Z' and 
			Not Exists (Select 'x' from deleted del where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmName= del.CmName) and 
			not exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= CmCd and HName= CmName)
			And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Company Name'
			goto ErrHndlr
		end
		*/

	/* ******************Geeta******Crm***2.12*****************/
		select @row= count('x') From Inserted 
		where CmCtg='CC' And (CmMrpMulBy<>0 Or CmMulBy<>0 Or CmFixPrc<>'' Or CmGldAs<>'' Or CmLabAs<>'' Or CmIWtEqOrd<>'' Or 
			CmIWtFrOrd<>'' Or CmIGldRtEqOrd<>'' Or CmDiaRtFA<>'' Or 
			CmCSRtFA<>'' Or CmPrdInst<>'' Or CmStmpInst<>'' Or CmPayTerms<>'' Or 
			CmDelTerms<>'' Or CmAdd1<>'' Or CmAdd2<>'' Or CmAdd3<>'' Or CmTel<>'' Or
			CmFax <>'' Or CmEMail<>'' Or CmPortofDisch<>'' Or 
			CmFinDest<>'' Or CmBuyer<>'' Or CmLkUpRmRt<>'' Or 
			CmLkUpLabRt<>'' Or CmLkUpMetLs<>'' Or CmRegnCd<>'' Or 
			CmHInsBy <>'' Or CmHRndOrdSalPrc<>'' Or 
			CmCurCd<>'' Or CmSalPer<>'' Or CmBuyAdd1<>'' Or
			CmBuyAdd2<>'' Or CmBuyAdd3<>'' Or 
			CmBkCd<>'' Or CmAgCd<>''  Or CmVessel<>'')
		if @row>0 
		Begin
			select @errmsg='Only Customer Code/Customer Name/Customer Designs Should Be Entered'
			goto ErrHndlr
		end
	/* ******************Geeta***********************/

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date: 09/12/2003					Ver: 2.0.6												 */
		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmValidYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end
/*  #########################################  Manoj  #########################################  */

		/* 4.1.2 ********************************************************* */
		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmInvShowGrsWtYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end

		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmInvShowDiaWtYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end

		/* 4.1.2 ********************************************************* */

		/******************Geeta****************Emr206*********************/
		select @row = count('x') from inserted where CmCd in ('ZVALUE','ZSELF') 
			and CmValidYN='N' 
		if @row>0
		Begin
			select @errmsg= 'ZSelf/ZValue Cannot Be InValid '
			goto ErrHndlr
		end
		/******************Geeta****************Emr206*********************/
		/****** If CmGldAs <> '' then 		Valid PMCd('GLDAS')  ******/

		/*** (Jen 2.14) ***/ 
		/* select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where PTyp= 'GLDAS' and PMCd= CmGldAs
			and not (',' + PDesc225 + ',' like '%,G,%' Or ',' + PDesc225 + ',' like '%,P,%' Or ',' + PDesc225 + ',' like '%,S,%') 
			)
		*/
		select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where PTyp= 'GLDAS' and PMCd= CmGldAs)
		/*** (Jen 2.14) ***/ 

		/*** (Bef 2.14) 
		select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='GLDAS' and PMCd= CmGldAs)
		(Bef 2.14) ***/

		if @row>0 
		Begin
			select @errmsg='Gold As Value Not Defined'
			goto ErrHndlr
		end

		/****** If CmLabAs <> '' then 		Valid PMCd('GLDAS')  ******/
		select @row= count('x') from inserted where CmLabAs <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='GLDAS' and PMCd= CmLabAs)
		if @row>0 
		Begin
			select @errmsg='Labour As Value Not Defined'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmGldAs <> ''  ******/
		/*** (Bef 2.14) 
		select @row= count('x') from inserted where CmCtg in ('C', 'T') and CmGldAs = ''
		if @row>0 
		Begin
			select @errmsg= 'Gold As Value Should Be Entered'
			goto ErrHndlr
		end
		(Bef 2.14) ***/

		/****** If CmCtg='C' then 		CmLabAs <> ''  ******/
		select @row= count('x') from inserted where CmCtg in ('C', 'T') and CmLabAs = ''
		if @row>0 
		Begin
			select @errmsg= 'Labour As Value Should Be Entered'
			goto ErrHndlr
		end

		/****** CmIWtEqOrd= '' or Valid PMCd ('YN') ******/
		select @row=count('x') from inserted where CmIWtEqOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmIWtEqOrd)
		if @row>0 
		Begin
			select @errmsg= 'Invoice Wts From Order (Enter Y/N)'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmIWtEqOrd <> ''  ******/
		select @row= count('x') from inserted where CmCtg = 'C' and CmIWtEqOrd = '' 
		if @row> 0 
		Begin
			select @errmsg= 'Invoice Wts From Order Should Be Entered' 
			goto ErrHndlr
		end

		/****** If CmIWtEqOrd= 'N' then 		Valid PMCd('IWTFRORD') or '' ******/
		select @row=count('x') from inserted where CmIWtEqOrd= 'N' and 
			CmIWtFrOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='IWTFRORD' and PMCd=CmIWtFrOrd)
		if @row>0 
		Begin
			select @errmsg='Wts From Order Not Defined'
			goto ErrHndlr
		end
		/****** If CmIWtEqOrd= 'Y' then 		Blank ******/
		select @row=count('x') from inserted where CmIWtEqOrd='Y' and 
			CmIWtFrOrd <> '' 
		if @row>0 
		Begin
			select @errmsg='Wts From Order Should Not Be Entered'
			goto ErrHndlr
		end

		/****** CmIGldRtEqOrd  = Blank or PMCd ('YN')  ******/
		select @row=count('x') from inserted where CmIGldRtEqOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmIGldRtEqOrd)
		if @row>0 
		Begin
			select @errmsg= 'Invoice Gold Rate From Order (Enter Y/N)'
			goto ErrHndlr
		end

		-- 4.4.0
		/****** CmSeekZSelfPDCM  = PMCd ('YN')  ******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmSeekZSelfPDCM)
		if @row>0 
		Begin
			select @errmsg= 'Seek ZSelf from PDCM (Enter Y/N)'
			goto ErrHndlr
		end

		/****** CmSeekZSelfRt  = PMCd ('YN')  ******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmSeekZSelfRt)
		if @row>0 
		Begin
			select @errmsg= 'Seek ZSelf from Rate Chart (Enter Y/N)'
			goto ErrHndlr
		end
		-- 4.4.0

		/****** If CmCtg='C' then 		CmIGldRtEqOrd <> ''  ******/
		select @row=count('x') from inserted where CmCtg = 'C' and CmIGldRtEqOrd = ''
		if @row>0 
		Begin
			select @errmsg= 'Invoice Gold Rate From Order Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmDiaRtFA  =  Blank or PMCd ('FA')  ******/
		/*** (Jen 2.14) ***/ 
		select @row= count('x') from inserted where CmDiaRtFA<> '' and CmDiaRtFA<> 'A' 
		/*** (Jen 2.14) ***/ 

