		/****** CmMrpMulby  > 0 ******/		
		select @row=count('x') from inserted where CmMrpMulby<= 0 and CmCtg in ('C', 'S')  
		if @row>0 
		Begin
			select @errmsg= 'MRP Multiplying Factor Should Be > 0'
			goto ErrHndlr
		end

		/****** If CmRegnCd <> '' then 		Valid PMCd('REGION')  ******/
		select @row= count('x') from inserted where CmRegnCd <> '' and 
