				    PTyp= 'REGION' and PMCd= CmRegnCd)
		if @row> 0 
		Begin
			select @errmsg= 'Region Code Not Defined'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmRegnCd <> ''  ******/
		select @row=count('x') from inserted where CmCtg in ('C', 'T') and CmRegnCd= ''
		if @row>0 
		Begin
			select @errmsg= 'Region Code Should Be Entered'
			goto ErrHndlr
		end

		/****** CmHRndOrdSalPrc = PMCd('RNDOPT') ******/	
		select @row= count('x') from inserted where CmCtg<>'CC' and 
				not exists (select 'x' from Param where PTyp= 'RNDOPT' and PMCd= CmHRndOrdSalPrc)
		if @row> 0 
		begin
			select @errmsg= 'Round Off Option For Order Sales Price Not Defined'
			goto ErrHndlr
		end

		/****** CmLkUpRmRt, CmLkUpLabRt, CmLkUpMetLs  =  Blank  (CmCtg= 'T')  ******/
		select @row= count('x') from inserted ins where CmCtg= 'T' 
			and (CmLkUpLabRt <> '' or CmLkUpRmRt<> '' or CmLkUpMetLs<> '') 
		if @row> 0 
		Begin
