			goto ErrHndlr
		end

		/****** CmLkUpLabRt  =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/
		select @row=count('x') from inserted ins where CmLkUpLabRt <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpLabRt and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
