			goto ErrHndlr
		end

		/****** CmLkUpMetLs  =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/
		select @row=count('x') from inserted ins where CmLkUpMetLs <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpMetLs and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
