		end
		/* ************* */

		/*** Check For Valid Bank Code ***/
		select @row= count('x') from inserted where CmBkCd<> '' and 
			Not Exists (Select 'x' from BnkAgMst where BkCtg = 'B' and BkCd = CmBkCd)
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Bank Code'
