		select @row= count('x') from deleted where exists (select 'x' from CustAly where CmCtg= CaCtg and CmCd= CaCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Alloy Exists'
			goto ErrHndlr
		end

		/**** Shilpa Emr 2.04 ****/
		select @row= count('x') from deleted where exists (select 'x' from CustRm where CmCtg= CrCtg and CmCd= CrCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Rm Exists'
			goto ErrHndlr
		end
		/**** Shilpa Emr 2.04 ****/

		select @row= count('x') from deleted del where CmCtg in ('C', 'P', 'S', 'T') 
			and exists (select 'x' from LabRt where LrCmCtg= CmCtg and LrCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In LabRt Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'C' 
			and exists (select 'x' from OrdMst where OmCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Customer Code In Use In OrdMst Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'T' 
			and exists (select 'x' from OrdMst where OmHCtCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Contractor Code In Use In OrdMst Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'C' 
			and exists (select 'x' from RmMst where RmCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In RmMst Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg in ('C', 'S', 'P', 'T') 
			and exists (select 'x' from RmRt where RrCmCtg= CmCtg and RrCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In RmRt Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'T' 
			and exists (select 'x' from OrdDsg where OdOmCtCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Contractor Code In Use In OrdDsg Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'T' 
			and exists (select 'x' from Bag where BOdCtCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Contractor Code In Use In Bag Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'C' 
			and exists (select 'x' from Txn where TTc= 'SA' and TSuppCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In Txn Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'S' 
			and exists (select 'x' from Txn where TTc<> 'SA' and TSuppCd= CmCd and 
					TTc in (SELECT PMCd FROM Param WHERE PTyp = 'TC' And 
						PValue in ('TZ', 'PR')   
						)
				   )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Supplier Code In Use In Txn Table'
			goto ErrHndlr
		end

/*		select @row= count('x') from deleted del where CmCtg= 'S' 
			and exists (select 'x' from Txn where TSuppCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In Txn Table'
			goto ErrHndlr
		end
*/
		select @row= count('x') from deleted del where CmCtg= 'C' 
			and exists (select 'x' from Fgd where FdPrdCmCd= CmCd or FdExpCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In Fgd Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'C' 
			and exists (select 'x' from InvHd where InCmCd= CmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Code In Use In InvHd Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg= 'T' 
			and exists (select 'x' from InvHd where InCmCd= CmCd and 
					(Select PValue from Param where PTyp= 'TC' and PMCd= InTc)= 'CTB')
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Contractor Code In Use In InvHd Table'
			goto ErrHndlr
		end
		/********Geeta***Crm**2.12*****************************/
		select @row= count('x') from deleted del where  CmCtg= 'C' and
				exists (select 'x' from CrmCustMst where  ccCmCd= CmCd)
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As Customer Code In Use In CrmCustMst Table'
				goto ErrHndlr
			end
		select @row= count('x') from deleted del where  CmCtg= 'CC' and
				exists (select 'x' from CustDsg where  CdCd= CmCd)
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As Catalogue Code In Use In CustDsg Table'
				goto ErrHndlr
			end

		select @row= count('x') from deleted del where  CmCtg= 'P' and
				exists (select 'x' from OrdMst where CmCd In (OmLkUpRmRt, OmLkUpLabRt, OmLkUpMetLs) )
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As PriceList Customer Code In Use In OrdMst Table'
				goto ErrHndlr
			end


		select @row= count('x') from deleted del where  CmCtg= 'C' and
				exists (select 'x' from MultiPrcQtMst where MqmCmCd= CmCd)
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As Customer Code In Use In MultiPrcQtMst Table'
				goto ErrHndlr
			end

		select @row= count('x') from deleted del where  CmCtg= 'P' and
				exists (select 'x' from MultiPrcQtMst where CmCd In (MqmLkUpRmRt, MqmLkUpLabRt, MqmLkUpMetLs) )
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As PriceList Customer Code In Use In MultiPrcQtMst Table'
				goto ErrHndlr
			end


		/********Geeta***Crm**2.12*****************************/
	End

	if @SYS= 'XEMR' 
	BEGIN
	 	if @mode= 'C'
 		Begin
			/****** If CmCurCd  cannot be changed if xTxn Voucher  and RmRt Rec Exists ******/
			select @Row= Count('x') from deleted del where 
				 not exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg 
					and ins.CmCd= del.CmCd and ins.CmCurCd= del.CmCurCd) and 
				(exists(select 'x' from RmRt where RrCmCtg= CmCtg and RrCmCd= CmCd)
					Or
				exists(Select 'x' from xTxn where xTCmCtg= CmCtg and xTCmCd= CmCd))
			If @Row> 0
			Begin 
				Select @ErrMsg= 'Cannot Change Currency Code As RmRt Rec Or xTxn Voucher Exists'
				GoTo ErrHndlr
			End 
		End

		if @mode in ('A','C')
		Begin
			/****** If CmCtg='C' then 		CmGldAs <> ''  ******/
			/*** (Bef 2.14) 
			select @row= count('x') from inserted where CmCtg in ('S') and CmGldAs = ''
			if @row>0 
			Begin
				select @errmsg= 'Gold As Value Should Be Entered'
				goto ErrHndlr
			end
			(Bef 2.14) ***/

			/****** If CmCtg='C' then 		CmLabAs <> ''  ******/
			select @row= count('x') from inserted where CmCtg in ('S') and CmLabAs = ''
			if @row>0 
			Begin
				select @errmsg= 'Labour As Value Should Be Entered'
				goto ErrHndlr
			end

			/****** CmMulby  > 0 ******/
			select @row=count('x') from inserted where CmMulby<= 0 and CmCtg in ('S')  
			if @row>0 
			Begin
				select @errmsg= 'Multiplying Factor Should Be > 0'
				goto ErrHndlr
			end

			/****** CmMrpMulby  > 0 ******/
			select @row=count('x') from inserted where CmMrpMulby<= 0 and CmCtg in ('S')  
			if @row>0 
			Begin
				select @errmsg= 'MRP Multiplying Factor Should Be > 0'
				goto ErrHndlr
			end


			/****** CmCurCd  =  Valid PMCd('CURNCY')  ******/ 
			select @row= count('x') from inserted where 
				not exists (select 'x' from Param where PTyp= 'CURNCY' and PMCd= CmCurCd)
			if @row> 0 
			begin
				select @errmsg= 'Currency Code Not Defined For Customer'
				goto ErrHndlr
			end
		End


		if @mode = 'D' 
		Begin
			/****** Check For Use In  xTxn ******/	
			/****** If In Use Do Not Allow Delete ******/
			select @row= count('x') from deleted del where  
				exists (select 'x' from xTxn where xTCmCtg= CmCtg and xTCmCd= CmCd)
			if @row> 0 
			Begin
				select @errmsg= 'Cannot Delete As Customer Code In Use In xTxn Table'
				goto ErrHndlr
			end
		End

	END



	return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
END

GOGO

ALTER TRIGGER [CustRm_INUPDL] ON [CustRm] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT 
	DECLARE @wCurrPrtn VarChar(1) 
 
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustRm' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	Set @wCurrPrtn = 'C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode in ('A','C')
	begin
		Select @row=count('x') From Inserted Where CrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Inserted Where CrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */	


	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	end	

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		select @Row=Count('x') from deleted del where
			 not exists (Select 'x' from inserted ins where ins.CrCtg= del.CrCtg and ins.CrCd= del.CrCd and ins.CrOurRmCd= del.CrOurRmCd and ins.CrFrLn = del.CrFrLn and ins.CrToLn = del.CrToLn)
		If @Row > 0
		Begin
			Select @ErrMsg='Cannot Change Category/Customer Code/Rm Code'
			GoTo ErrHndlr
		End
	End
	/******* Validate Customer Category *******/
	select @row=count('x') from inserted where CrCtg<> 'C'
	if @row>0
	Begin
		select @errmsg='Customer Category Should Be ''C'' '
		goto ErrHndlr
	end
	/****** Validate Customer code *******/
	select @row=count('x') from inserted where not exists (select 'x' from CustMst where
			CmCtg= CrCtg and CmCd= CrCd)
	if @row>0
	Begin
		select @errmsg='Customer Code Not Defined'
		goto ErrHndlr
	end

	/****** Validate Rm code Exists *******/
	select @row=count('x') from inserted where CrPrtKey=@wCurrPrtn and 
		not exists (select 'x' from RmMst where RmPrtKey=CrPrtKey and RmCd= CrOurRmCd and RmCtg = inserted.CrRmCtg)
	if @row>0
	Begin
		select @errmsg='Invalid Rm Code'
		goto ErrHndlr
	end
	/****** Check whether Customer Rm code Exists *******/
	select @row=count('x') from inserted where CrCustRmCd=''
	if @row>0
	Begin
		select @errmsg='Customer Rm Code Cannot Be Blank'
		goto ErrHndlr
	end
	/******  CrToLn   >=   CrFrLn  ******/
	select @row= count('x') from inserted where CrToLn< CrFrLn
 	if @row> 0
 	Begin
  		select @errmsg= 'From Value Should Be <= Than To Value'
  		goto ErrHndlr
 	end

	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for
		 the same CrCtg, CrCd, CrRmCtg, CrRmCd combination)  ******/
	select @row= count('x') from inserted ins where
		(Select count('x') from CustRm Cr where
 		Cr.CrCtg= ins.CrCtg and Cr.CrCd= ins.CrCd and Cr.CrRmCtg= ins.CrRmCtg
		and Cr.CrOurRmCd= ins.CrOurRmCd
   		and  (    (Cr.CrFrLn<= ins.CrFrLn and Cr.CrToLn>= ins.CrFrLn)
		     or   (Cr.CrFrLn<= ins.CrToLn and Cr.CrToLn>= ins.CrToLn)
       		     or   (ins.CrFrLn<= Cr.CrFrLn and ins.CrToLn>= Cr.CrToLn)
		 )
		 ) > 1
		if @row> 0
	 	Begin
	  		select @errmsg= 'Size Range Already Defined'
	  		goto ErrHndlr
	 	end
	/*select @row= count('x') from inserted where CrToLn= 0
 	if @row> 0
 	Begin
  		select @errmsg= 'To Value Cannot Be Zero'
  		goto ErrHndlr
 	end*/
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [DmYyMm_INUPDL] ON [DmYyMm] 
       FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
  	Declare @wHCd Varchar(8)
	

	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DmYyMm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
			select @ROW =Count('x')  From inserted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ DCoCd +',%') 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
			select @ROW =Count('x')  From Deleted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ DCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
	
 return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  

GOGO

ALTER TRIGGER [DsgAna_INUPDL] ON [DsgAna] 
	FOR INSERT,UPDATE,DELETE 
	NOT FOR REPLICATION
AS 
BEGIN 
	/* *** Trigger Version Emr 3.02 [Speed Optimization - Purge Partition] *** */
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  
	Declare @wCurrPrtn VarChar(1)
	
	Select @wCurrPrtn = 'C'

	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgAna' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	if @mode='C'  And @ReplAgt <> 1
 	Begin
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Inserted Where DaPrtKey<>@wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end

	if @mode='A'  And @ReplAgt <> 1
 	Begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Inserted Where DaPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	End

 	if @mode = 'D'  And @ReplAgt <> 1
 	Begin
  		select @Row=Count('x') from deleted del where del.DaPrtKey<>@wCurrPrtn
  		If @Row > 0
	  	begin
			Select @ErrMsg='Cannot Delete Records From Previous Partition'
			GoTo ErrHndlr
		end
	End
	
	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	end	
 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		Not Exists (Select 'x' from inserted ins where ins.DaIdNo=del.DaIdNo and ins.DaTcTyp= del.DaTcTyp 
					and ins.DaCd= del.DaCd And ins.DaSz= del.DaSz and ins.DaAnaSr= del.DaAnaSr)
  		If @Row> 0
	  	begin
			Select @ErrMsg= 'Cannot Change DsgAna Key'
			GoTo ErrHndlr
		end
	End

	/****** DaTcTyp = 'DM' ******/
	/* Partition Check Not Required */
/*	select @row= count('x') from inserted where DaTcTyp<> 'DM'
	if @row> 0
	begin
		select @errmsg= 'Analysis Fields Canbe Entered Only In Design Master'
		goto ErrHndlr
	end
*/
	/****** DaTcTyp, DaCd, DaSz combination should exist in the DsgMst ******/
	/* Check On Current Partition */
	select @row= count('x') from inserted Ins where 
		Not Exists (Select 'x' From Deleted Del Where Ins.DaDmIdNo=Del.DaDmIdNo and Ins.DaTcTyp=Del.DaTcTyp 
						and Ins.DaCd=Del.DaCd and Ins.DaSz=Del.DaSz and Ins.DaPrtKey<>Del.DaPrtKey) and
		not exists (select 'x' from DsgMst where
				DmIdNo=INs.DaDmIdNo and DmTcTyp= Ins.DaTcTyp and DmCd= Ins.DaCd and DmSz= Ins.DaSz and DmPrtKey=Ins.DaPrtKey)
	if @row> 0
	begin
		select @errmsg= 'This Type-Design-Size Combination Not Defined In Design Master'
		goto ErrHndlr
	end

	/******  DaAnaSr  =  PMCd ('DAANAFLD')  ******/
	/* Partition Check Not Required */
	select @row= count('x') from inserted where
		not exists (select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr)
	if @row> 0
	begin
		select @errmsg= 'Design Analysis Field Not Defined'
		goto ErrHndlr
	end

	/******  DaAnaCd  =  PMCd ('DAANACD')  ******/
	/* Partition Check Not Required */
	select @row= count('x') from inserted where
		(	exists (Select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr
			and PValue= 'N')
			And DaAnaCd<> ''
		)
		OR
		(	DaAnaCd<> ''
			And exists (Select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr
				and PValue= 'Y')
			And not exists (select 'x' from Param where PTyp= 'DAANACD' and PMCd= DaAnaSr and PSCd= DaAnaCd)
		)
		OR
		(	DaAnaCd= ''
			And exists (Select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr
				and PValue= 'Y' and PValue1= 'Y')
		)
		if @row> 0
		begin
			select @errmsg= 'Design Analysis Code Not Defined'
			goto ErrHndlr
		end

	/******  DaAnaDesc  ******/
	/* Partition Check Not Required */
	select @row= count('x') from inserted where
		(	exists (Select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr
			and PValue= 'Y')
			And DaAnaDesc<> ''
		)
		OR
		(	DaAnaDesc= ''
			And exists (Select 'x' from Param where PTyp= 'DAANAFLD' and PMCd= DaAnaSr
				and PValue= 'N' and PValue1= 'Y')
		)
		if @row> 0
		begin
			select @errmsg= 'Design Analysis Description Not Defined'
			goto ErrHndlr
		end

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end


GOGO

ALTER TRIGGER [DsgCT_INUPDL] ON [DsgCT] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	/* *** Trigger Version Emr 3.02 [Speed Optimization - Purge Partition] *** */
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	Declare @wCurrPrtn VarChar(1)
	
	Select @wCurrPrtn = 'C'
 
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgCT') 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	DECLARE @ReplAgt BIT  
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If @mode='C' And @ReplAgt <> 1
	Begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Inserted Where DctPrtKey='P' 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	If @mode='A'  And @ReplAgt <> 1
	Begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Inserted Where DctPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	End

	If @mode='D'  And @ReplAgt <> 1
	Begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Deleted Where DctPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	End

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		/* Current Partition */
  		select @Row=Count('x') from deleted del where del.DctPrtKey=@wCurrPrtn and
    		not exists (Select 'x' from inserted ins where ins.DctIdNo=del.DctIdNo and ins.DctTcTyp= del.DctTcTyp 
					and ins.DctDmCd= del.DctDmCd and ins.DctDmSz= del.DctDmSz and ins.DctSr= del.DctSr)
  		If @Row > 0
	  	begin
			Select @ErrMsg='Cannot Change Dsg Component Key'
			GoTo ErrHndlr
		end
	End

 	if @mode IN ('A','C')
	Begin

		/****** DctTcTyp <> 'DM' Not allowed *****  (new CT)*/
		/* bef 2.14Next
				select @row= count('x') from inserted where DctTcTyp = 'PM'
				if @row> 0
				Begin
					select @errmsg= 'TcTyp ''PM'' Can Not Be Entered In To This Table'
					goto ErrHndlr
				end
		bef 2.14Next*/
		/****** DctTcTyp <> 'DM' Not allowed ***** (new CT)	*/

		/****** DctTcTyp = 'DM' AND DctDmSz <> '' Not allowed ******/
		/* bef 2.14Next
				select @row= count('x') from inserted where DctTcTyp = 'DM' and DctDmSz <> ''
				if @row> 0
				Begin
					select @errmsg= 'Design Master With Size Records Can Not Enter In To This Table'
					goto ErrHndlr
				end	
		 bef 2.14Next */			

		/****** DctTcTyp, DctDmCd, DctDmSz combination should exist in the DsgMst ******/
		/* Check In Current Partition */
		select @row= count('x') from inserted ins where 
			Not Exists (Select 'x' From Deleted Del Where Ins.DctDmIdNo=Del.DctDmIdNo and Ins.DctTcTyp=Del.DctTcTyp 
						and Ins.DctDmCd=Del.DctDmCd and Ins.DctSz=Del.DctSz and Ins.DctPrtKey<>Del.DctPrtKey) and
			not exists (select 'x' from DsgMst where
					DmIdNo=ins.DctDmIdNo and DmTcTyp= ins.DctTcTyp and DmCd=ins.DctDmCd and DmSz= ins.DctDmSz and DmPrtKey=ins.DctPrtKey)
		if @row> 0
		Begin
			select @errmsg= 'DmTcTyp-Design-Size Combination Not Defined In Design Master'
			goto ErrHndlr
		end
	
		/****** DmTcTyp= 'PM', DctCd, DctSz Component combination should exist in the DsgMst ******/
		/* Check In Current Partition */
		select @row= count('x') from inserted ins where not exists (select 'x' from DsgMst Dm where
					Dm.DmTcTyp= 'PM' and Dm.DmCd= ins.DctCd and Dm.DmSz= ins.DctSz and Dm.DmPrtKey=DctPrtKey)
		if @row> 0
		Begin
			select @errmsg= 'Component Code-Size Combination Not Defined In Part Master'
			goto ErrHndlr
		end

		If (select hCompBagsYn from Head Where HCoCd= 'ZZZ')= 'N' 
		Begin
			/****** DctChr= '' if hCompBagsYn= 'n' ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted ins where DctChr<> '' or DctRmCd <> '' or DctDmCol <> '' or 
						DctRmWt <> '' or DctDc <> '' or DctPrdSeq <> '' or DctDesc <> ''
			if @row> 0
			Begin
				select @errmsg= 'Cannot Edit This Field When Module Is Not Available'
				goto ErrHndlr
			end
		End
		Else If (select hCompBagsYn from Head Where HCoCd= 'ZZZ')= 'Y' 
		Begin
			/****** DctChr valid PTYP='BCHR'  ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted ins where DctChr <> '' and 
				Not Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= DctChr and PSCd= '' and PValue = 'C')
			if @row> 0
			Begin
				select @errmsg= 'Invalid Component Character'
				goto ErrHndlr
			end
		
			/****** DctChr <> '' if hCompBagsYn= 'Y' ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted ins where DctChr= '' 
			if @row> 0
			Begin
				select @errmsg= 'Component Character Can Not Be Blank'
				goto ErrHndlr
			end

/* (BEF 2.14Next)
			select @Row= Count('x') from inserted ins 
			where 
    			(Select count('x') from DsgCt Dct where ins.DctTcTyp= Dct.DctTcTyp and ins.DctDmCd= Dct.DctDmCd 
					and ins.DctDmSz= Dct.DctDmSz and ins.DctChr= Dct.DctChr)> 1
  			If @Row > 0
	  		begin
				Select @ErrMsg='This Component Character Already Exists For This Design'
				GoTo ErrHndlr
			end
*/

			/******  DctRmCd=  valid RmCd from RmMst (RmCtgin ('G','P','S'), RmCd= DctRmCd, RmZ= 'N')  ******/
			/* Check On Current Partition */
			/* ***** Manali 3.03 -19/06/08 - 'L' included */
			SELECT @row= count('x') FROM Inserted Ins WHERE INs.DctPrtKey=@wCurrPrtn and
				(Ins.DctRmCd <> ISNULL((SELECT Del.DctRmCd FROM Deleted Del WHERE Ins.DctPrtKey=Del.DctPrtKey 
					and Ins.dctIdNo=Del.DctIdNo and Ins.DctTcTyp = Del.DctTcTyp
					AND Ins.DctDmCd = Del.DctDmCd AND Ins.DctDmSz= Del.DctDmSz AND Ins.DctChr= Del.DctChr), '')
				AND NOT EXISTS (SELECT 'x' FROM RmMst WHERE RmCtg in ('G','P','S', 'L') 
					AND RmCd= DctRmCd and RmZ= 'N' And RmValidYN = 'Y' And RmPrtKey=DctPrtKey))
				OR DctRmCd =''
			if @row> 0
			Begin
				select @errmsg= 'Raw Material Code Not Defined/InValid/Only (G,P,S,L) Metal Can Be Entered'
				goto ErrHndlr
			end
			
			/* *** Valid DctDmCol *** */ 
			/* Partition Check Not Required */
			select @row= count('x') from inserted where 
				not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd = DctDmCol)
				if @row> 0 
				begin
					select @errmsg= 'Design Colour Not Defined'
					goto ErrHndlr
				end
		
			/******  DctRmWt =>  0  ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted where DctRmWt < 0
			if @row> 0
			Begin
				select @errmsg= 'Component Part Weight Can Not Be < Zero'
				goto ErrHndlr
			end
		
			/****** DctDc valid PTYP='CTDC'  or Blank ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted ins where DctDc <> '' and  
				Not Exists (Select 'x' from Param where PTyp= 'CTDC' and PMCd= DctDc and PSCd= '')
			if @row> 0
			Begin
				select @errmsg= 'Invalid Component Code DC'
				goto ErrHndlr
			end
		
			/******  DctPrdSeq =  PMCd ('PRDSEQ')  ******/
			/* Partition Check Not Required */
			select @row= count('x') from inserted where DctPrdSeq <> '' and 
				not exists (select 'x' from vParam where 
					vPTyp= 'PRDSEQ' and vPMCd= DctPrdSeq) 
			if @row> 0 
			Begin
				select @errmsg= 'Production Sequence Not Defined'
				goto ErrHndlr
			end
		
			/* Partition Check Not Required */
			select @row= count('x') from inserted where DctPrdSeq = ''
			if @row> 0 
			Begin
				select @errmsg= 'Production Sequence Should Be Entered'
				goto ErrHndlr
			end
		End		

		/******  DctParts>  0  ******/
		/* Partition Check Not Required */
		select @row= count('x') from inserted where DctParts <= 0
		if @row> 0
		Begin
			select @errmsg= 'Component Part Qty Cannot Be < Zero'
			goto ErrHndlr
		end
	
		/****** Cannot have more than one record with DctMainPrtYN = 'Y'  for a Design Type, Code, Size combination  ******/
		/* Check On Current Db */
		select @row= count('x') from inserted ins where	
			(select count('x') from DsgCt Dct where ins.DctTcTyp = Dct.DctTcTyp  and 
			ins.DctDmCd= Dct.DctDmCd and ins.DctDmSz= Dct.DctDmSz and Dct.DctMainPrtYN = 'Y' and Dct.DctPrtKey=ins.DctPrtKey) > 1		
		if @row> 0
		Begin
			select @errmsg= 'Cannot Have More Than One Main Part'
			goto ErrHndlr
		end

		/****** DctMainPrtYN= 'Y/N'  ******/
		/* Partition Check Not Required */
		select @row= count('x') from inserted ins where
			Not Exists (Select 'x' from Param where PTyp= 'YN' and PMCd= DctMainPrtYN and PSCd= '')
		if @row> 0
		Begin
			select @errmsg= 'Invalid Main Part (Enter Y/N)'
			goto ErrHndlr
		end
	End

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [DsgLab_INUPDL] ON [DsgLab] 
	    FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
	/* *** Trigger Version Emr 3.02 [Speed Optimization - Purge Partition] *** */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
	Declare @wCurrPrtn VarChar(1)
	
	Select @wCurrPrtn = 'C'
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgLab' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
		/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	if @mode='C'
 	Begin
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
		Select @row=count('x') From Inserted Where DlPrtKey<>@wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
 	Begin
		Select @row=count('x') From Inserted Where DlPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	End

 	if @mode = 'D'
 	Begin
  		select @Row=Count('x') from deleted del where del.DlPrtKey='P'
  		If @Row > 0
	  	begin
			Select @ErrMsg='Cannot Delete Records From Previous Partition'
			GoTo ErrHndlr
		end
	End
	
	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
			If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
			exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End 	

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
  		select @Row=Count('x') from deleted del where
    		Not Exists (Select 'x' from inserted ins where ins.DlIdNo=del.DlIdNo 
				and ins.DlTcTyp=del.DlTcTyp and ins.DlCd= del.DlCd and ins.DlSz= del.DlSz and ins.DlSr= del.DlSr)
  		If @Row > 0
	  	begin
			Select @ErrMsg='Cannot Change DsgLab Key'
			GoTo ErrHndlr
		end
	End

	/****** DlTcTyp, DlCd, DlSz combination should exist in the DsgMst ******/
	/* Check On Current Partition */
	select @row= count('x') from Inserted Ins where 
			Not Exists (Select 'x' From Deleted Del Where Ins.DlDmIdNo=Del.DlDmIdNo and Ins.DlTcTyp=Del.DlTcTyp 
						and Ins.DlCd=Del.DlCd and Ins.DlSz=Del.DlSz and Ins.DlPrtKey<>Del.DlPrtKey) and
			not exists (select 'x' from DsgMst where 
				DmIdNo=Ins.DlDmIdNo and	DmTcTyp=Ins.DlTcTyp and DmCd=Ins.DlCd and DmSz=Ins.DlSz and DmPrtKey=Ins.DlPrtKey)
	if @row> 0
	Begin
		select @errmsg= 'This Type-Design-Size Combination Not Defined In Design Master'
		goto ErrHndlr
	end

	/******  DlMCd  =  PMCd ('LABMCD')  ******/
	/* Partition Check Not Required */
	select @row= count('x') from inserted where
		not exists (select 'x' from Param where PTyp= 'LABMCD' and PMCd= DlMcd)
	if @row> 0
	Begin
		select @errmsg= 'Labour Main Code Is Not Defined'
		goto ErrHndlr
	end

	/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
	/******  DlSCd  =  PSCd ('LABSCD', DlMCd)  ******/
	/* Partition Check Not Required */
	SELECT @row= count('x') FROM Inserted Ins WHERE
		(Ins.DlSCd <> ISNULL((SELECT Del.DlSCd FROM Deleted Del WHERE  Ins.DlTcTyp = Del.DlTcTyp And Ins.DlIdNo=Del.DlIdNo
			And Ins.DlCd = Del.DlCd And Ins.DlSz = Del.DlSz And Ins.DlSr = Del.DlSr), '')
			And NOT EXISTS (SELECT 'x' FROM Param WHERE PTyp= 'LABSCD' and PMCd= DlMCd AND PSCd= DlSCd And PValidYN = 'Y'))
		OR DlSCd = ''
	if @row> 0
	Begin
		select @errmsg= 'Labour Sub Code Not Defined /Invalid For This Category'
		goto ErrHndlr
	end
/* (Bef 2.06)
	select @row= count('x') from inserted where
		not exists (select 'x' from Param where
				PTyp= 'LABSCD' and PMCd= DlMCd and PSCd= DlSCd)
	if @row> 0
	Begin
		select @errmsg= 'Labour Sub Code Not Defined For This Category'
		goto ErrHndlr
	end
*/
/*  #########################################  Manoj  #########################################  */
	/******  DlQty > 0  ******/
	/* Partition Check Not Required */
	select @row= count('x') from inserted where DlQty <= 0
	if @row> 0
	Begin
		select @errmsg= 'Lab Quantity Should Be > Zero'
		goto ErrHndlr
	end

	/*
		******  If Lab Value is By Qty then DlQty > 0  ******
		select @row= count('x') from inserted where DlQty <= 0 and
			exists (select 'x' from Param where PTyp= 'LABSCD'
				and PMCd= DlMCd and PSCd= DlSCd and PValue= 'Q')
		if @row> 0
		Begin
			select @errmsg= 'Lab Quantity Should Be > Zero'
			goto ErrHndlr
		end
		******  If Lab Value is By Weight then DlQty = 0  ******
		select @row= count('x') from inserted where DlQty > 0 and
			exists (select 'x' from Param where PTyp= 'LABSCD'
				and PMCd= DlMCd and PSCd= DlSCd and PValue= 'W')
		if @row> 0
		Begin
			select @errmsg= 'Lab Quantity Should Be Zero'
			goto ErrHndlr
		end
	*/



return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [DsgLoad_INUPDL] ON [DsgLoad] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	/* *** Trigger Version 2.14.0 Next *** */
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  

	/*** (Jen 2.14 Next) ***/
	DECLARE @ws_P1 varchar(8), @ws_P2 varchar(8), @ws_P3 varchar(8), @ws_P4 varchar(8), @ws_P5 varchar(8)
	select @ws_P1 = '', @ws_P2 = '', @ws_P3 = '', @ws_P4 = '', @ws_P5 = ''
	/*** (Jen 2.14 Next) ***/
 
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgLoad' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	end 	

	/*** (Jen 2.14 Next) ***/
	select 	@ws_P1= max(case when PNum= 1 then PValue else '' end), 
		@ws_P2= max(case when PNum= 2 then PValue else '' end), 
		@ws_P3= max(case when PNum= 3 then PValue else '' end), 
		@ws_P4= max(case when PNum= 4 then PValue else '' end), 
		@ws_P5= max(case when PNum= 5 then PValue else '' end)
	From Param where PTyp= 'PRDSTG' 
	/*** (Jen 2.14 Next) ***/

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where
			not exists (Select 'x' from inserted ins where
				    ins.DldPrdCtg= del.DldPrdCtg and ins.DldDmCd= del.DldDmCd
				    and ins.DldWH= del.DldWH)
		If @Row> 0
		Begin
			Select @ErrMsg= 'Cannot Change Prd Ctg/Dsg Cd/W-H Setting Option'
			GoTo ErrHndlr
		End
	End
	if @mode in ('A','C')
	begin
		/****** Valid PrdCtg  ******/
		select @row=count('x') from inserted where
			not exists (select 'x' from Param where PTyp= 'PrdCtg' and PMCd= DldPrdCtg)
		if @row> 0
		Begin
			select @errmsg= 'Invalid Production Category'
			goto ErrHndlr
		End

		/****** If DldDmCd <> '' then 		Valid 'DldDmCd'  ******/
		select @row= count('x') from inserted where DldDmCd <> '' and
			not exists (select 'x' from DsgMst where DmTcTyp= 'DM' and DmSz= ''
				    and DmCd= DldDmCd and DmPrdCtg= DldPrdCtg)
		if @row> 0
		Begin
			select @errmsg= 'Invalid DsgCd Or DsgCd Does Not Belong To The Selected PrdCtg'
			goto ErrHndlr
		end
		/****** Valid WH Setting ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where PTyp= 'WH' and PMCd= DldWH)
		if @row> 0
		Begin
			select @errmsg= 'Invalid WH Setting'
			goto ErrHndlr
		End
		
		/****** If DldWH= 'W' then DldHSet= 0 ******/
		/* (Bef 2.14)
		select @row= count('x') from inserted where
			DldWH= 'W' and Str(DldHSet, 16, 1)<> Str(0, 16, 1)
		if @row> 0
		Begin
			select @errmsg= 'Hand Setting Load Should Be Zero'
			goto ErrHndlr
		End
		(Bef 2.14) */

		/****** If DldWH= 'H' then DldWSet= 0 ******/
		/* (Bef 2.14)
		select @row= count('x') from inserted where
			DldWH= 'H' and Str(DldWSet, 16, 1)<> Str(0, 16, 1)
		if @row> 0
		Begin
			select @errmsg= 'Wax Setting Load Should Be Zero'
			goto ErrHndlr
		End
		(Bef 2.14) */

		/****** DldP1 >= 0 ******/
		select @row= count('x') from inserted where Round(DldP1, 1)< 0
		if @row> 0
		Begin
			select @errmsg= @ws_P1+ ' Load Per Piece Cannot Be < 0'
			goto ErrHndlr
		End
		/****** DldP2 > 0 ******/
		select @row= count('x') from inserted where Round(DldP2, 1)< 0
		if @row> 0
		Begin
			select @errmsg= @ws_P2+ ' Load Per Piece Cannot Be < 0'
			goto ErrHndlr
		End
		/****** DldP3 > 0 ******/
		select @row= count('x') from inserted where Round(DldP3, 1)< 0
		if @row> 0
		Begin
			select @errmsg= @ws_P3+ ' Load Per Piece Cannot Be < 0'
			goto ErrHndlr
		End
		/****** DldP4 >= 0 ******/
		select @row= count('x') from inserted where Round(DldP4, 1)< 0
		if @row> 0
		Begin
			select @errmsg= @ws_P4+ ' Load Per Piece Cannot Be < 0'
			goto ErrHndlr
		End
		/****** DldP5 > 0 ******/
		select @row= count('x') from inserted where Round(DldP5, 1)< 0
		if @row> 0
		Begin
			select @errmsg= @ws_P5+ ' Load Per Piece Cannot Be < 0'
			goto ErrHndlr
		End
		/****** DldWSet & DldHSet cannot be zero simultaneously ******/
/*		select @row= count('x') from inserted where Round(DldWSet, 1)= 0 and Round(DldHSet, 1)= 0
		if @row> 0
		Begin
			select @errmsg= 'Both Wax And Hand Set Load Per Piece Cannot Be Zero Simultaneously'
			goto ErrHndlr
		End
*/
	End

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	End
END

GOGO

/****** Object:  Trigger dbo.DsgModAvl_INUPDL    Script Date: 02/06/2006 18:00:00 ******/
ALTER TRIGGER [DsgModAvl_INUPDL] ON [DsgModAvl]
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT
	IF @@ROWCOUNT= 0
		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgModAvl' )
		RETURN

	Select @mode=Case (Select Count('x') From Inserted) When 0 Then 'D'
			Else
			Case (Select Count('x') From Deleted) When 0 Then 'A' Else 'C' End
			End 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		If @mode in ('A','C','D') 
		Begin 
		If   Exists ( Select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		Exists ( Select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				Select @errmsg= 'Cannot Insert /Update /Delete ' 
				Goto ErrHndlr 
			End 
		End 
	End
 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.DmaTcTyp= del.DmaTcTyp and ins.DmaCd= del.DmaCd and ins.DmaSz= del.DmaSz and ins.DmaSr= del.DmaSr)
  		If @Row> 0
	  	begin 
			Select @ErrMsg= 'Cannot Change DsgModAvl Key'
			GoTo ErrHndlr
		end
	End

	/****** DmaTcTyp = 'DM' ******/	
	select @row= count('x') from inserted where DmaTcTyp<> 'DM'
	if @row> 0 
	begin
		select @errmsg= 'Model Availability Can be Entered Only In Design Master'
		goto ErrHndlr
	end

	/******  DmaAvlSz  =  PMCd ('DMSZ')  ******/
	select @row= count('x') from inserted where DmaAvlSz<>'' And
		not exists (select 'x' from Param where PTyp= 'DMSZ' and PMCd= DmaAvlSz)
	if @row> 0 
	begin
		select @errmsg= 'Invalid Design Size'
		goto ErrHndlr
	end

 	/******** Size can be entered only once in Available sizes List ********/ 
 	If @mode In ('A','C')
 	Begin
		Select @Row=Count('x') From Inserted Ins Where 
		(Select Count('x') From DsgModAvl Dma 
				Where Dma.DmaTcTyp=Ins.DmaTcTyp And Dma.DmaCd=Ins.DmaCd 
					And Dma.DmaSz=Ins.DmaSz And Dma.DmaAvlSz=Ins.DmaAvlSz)>1	
  		If @Row> 0
	  	begin 
			Select @ErrMsg= 'Size Already Exists in Available Sizes List of this Design'
			GoTo ErrHndlr
		end
	End

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end




GOGO


ALTER TRIGGER [DsgPrm_INUPDL] ON [DsgPrm] 
       FOR INSERT,UPDATE,DELETE   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
  	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgPrm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		if @mode in ('A','C','D')
		Begin 
			If   exists (select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
			exists (select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 	
	End
	
	If @mode in ('A')
	BEGIN
		Select DISTINCT  @Row= Count('x') from DsgPrm Dp1 
			Inner Join Inserted Ins 
						On Dp1.DpTyp=Ins.DpTyp and Dp1.DpCd=Ins.DpCd AND Dp1.DpDmCd='' 
		If @Row = 0	
		Begin
			Insert Into DsgPrm 
			Select DpTyp,DpCd,'',DpNo,DpDesc,DpDt,DpDmNo,DpPctNm,DpRem1,DpRem2,ModUsr,ModDt,ModTime 
				from Inserted
		END
	End
	
	If @mode in ('A','C')
	BEGIN
		select @Row= count('x') from Inserted where DpCd in ('','0')
		If @Row > 0	
		Begin
			Select @ErrMsg='Code Can Not Be Blank/ Zero'
			GoTo ErrHndlr
		END

		select @Row= count('x') from Inserted Ins where Ins.DpDmCd <> '' and
				not Exists (Select 'x' from DsgMst where DmTcTyp='DM' and DmCd= Ins.DpDmCd and DmSz='' and DmHld ='N')
		If @Row > 0	
		Begin
			Select @ErrMsg='Invalid Design Code/ On Hold'
			GoTo ErrHndlr
		END
		
		select @Row= count('x') from Inserted Ins where Ins.DpDmCd <> '' and ins.DpTyp in ('SER','SET','VER') and 
				(Select Count('x') from DsgPrm Dp where Dp.DpTyp=ins.DpTyp and Dp.DpDmCd=ins.DpDmCd)>1
		If @Row > 0	
		Begin
			Select @ErrMsg='Design Can Not Exist In Multiple ''SER''/''SET''/''VER'' '
			GoTo ErrHndlr
		END
		
	End
	
	If @mode in ('D') 
	BEGIN
		select @Row = count('x') from Deleted Del where Del.DpDmCd=''
			and exists (Select 'x' From DsgPrm DP where DP.DpTyp=Del.DpTyp and DP.DpCd= Del.DpCd and DP.DpDmCd<>'')
		If @Row > 0 	
		Begin 
			Select @ErrMsg='Can Not Delete As Child Record Exists'
			GoTo ErrHndlr
		END
	End
 return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  

GOGO

Alter TRIGGER [DsgRm_INUPDL] ON [DsgRm] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	/* Trigger Version 3.02.0 - Speed Optimization */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @ReplAgt BIT  
	Declare @wHCd Varchar(8)       
	DECLARE @errmsg varchar(255) 
	DECLARE @SelfCoCd varChar(3) 
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	/* Sachin 3.02 - Constant For Current Partition */
	select @wCurrPrtn = 'C'		
	Select @SelfCoCd ='ZZZ'
	Select @wHCd = 'ZSELF'

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgRm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='A'  And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end

	if @mode='C'  And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	If @Mode='D'  And @ReplAgt <> 1
	Begin 
			select @row= count('x') from deleted del where del.DrPrtKey<>@wCurrPrtn
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete Records From Previous Partition'
				goto ErrHndlr
			end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */	

	If  (@ReplAgt<>1)
	begin
	 	/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If exists( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End		
	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		/* Prt Key Not required as only inserted and deleted record is compared */
  		select @Row=Count('x') from deleted del where			
    		not exists (Select 'x' from inserted ins where ins.DrIdNo=del.DrIdNo and ins.DrTcTyp= del.DrTcTyp 
				and ins.DrCd= del.DrCd and ins.DrSz= del.DrSz and ins.DrSr= del.DrSr)
  		If @Row > 0
	  	begin
			Select @ErrMsg='Cannot Change DsgRm Key'
			GoTo ErrHndlr
		end
	End
	/****** DrTcTyp, DrCd, DrSz combination should exist in the DsgMst ******/
	/* ****** Sachin 3.02 - Currrent Partition	*/
	select @row= count('x') from inserted Ins where 
			not exists (select 'x' From Deleted Del Where Del.DrIdNo=Ins.DrIdNo and Del.DrTcTyp= Ins.DrTcTyp and Del.DrCd= Ins.DrCd 
					and Del.DrSz= Ins.DrSz and Del.DrPrtKey<>Ins.DrPrtKey) and  
			not exists (select 'x' from DsgMst where 
				DmIdNo=Ins.DrDmIdNo and DmTcTyp= Ins.DrTcTyp and DmCd= Ins.DrCd and DmSz= Ins.DrSz and DmPrtKey=Ins.DrPrtKey)
	if @row> 0
	Begin
		select @errmsg= 'This Type-Design-Size Combination Not Defined In Design Master'
		goto ErrHndlr
	end
	/******  DrWt  <>  0  ******/
	select @row= count('x') from inserted where Round(DrWt, 3) = 0
	if @row> 0
	Begin
		select @errmsg= 'Raw Material Weight Cannot Be Zero'
		goto ErrHndlr
	end
	/******  DrRmCtg  =  PMCd ('RMCTG')  ******/
	select @row= count('x') from inserted where
		not exists (select 'x' from Param where
		PTyp= 'RMCTG' and PMCd= DrRmCtg)
	if @row> 0
	Begin
		select @errmsg='Raw Material Category Not Defined'
		goto ErrHndlr
	end
	/******  DrRmSCtg  =  PSCd ('RMCTG', DrRmCtg)  ******/
	select @row=count('x') from inserted where
		not exists (select 'x' from Param where
				PTyp='RMSCTG' and PMCd=DrRmCtg
				and PSCd=DrRmSCtg)
	if @row>0
	Begin
		select @errmsg='Raw Material Sub Category Not Defined For This Category'
		goto ErrHndlr
	end
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
	/******  DrRmCd  =  valid RmCd from RmMst (RmCtg= DrRmCtg, RmSCtg= DrRmCtg, RmCd= DrRmCd, RmZ= 'N')  ******/
	/* ****** Sachin 3.02 - Current Partition - CHECK REQUIRED	*/
	SELECT @row= count('x') FROM Inserted Ins WHERE Ins.DrPrtKey=@wCurrPrtn and
		Not Exists (Select 'x' From Deleted Del Where Ins.DrPrtKey<>Del.DrPrtKey and Ins.DrDmIdNo=Del.DrDmIdNo 
			and Ins.DrTcTyp = Del.DrTcTyp And Ins.DrCd = Del.DrCd AND Ins.DrSz = Del.DrSz) and 
		(Ins.DrRmCd <> ISNULL((SELECT Del.DrRmCd FROM Deleted Del WHERE Ins.DrPrtKey=Del.DrPrtKey and Ins.DrIdNo=Del.DrIdNo 
			and Ins.DrTcTyp = Del.DrTcTyp And Ins.DrCd = Del.DrCd AND Ins.DrSz = Del.DrSz AND Ins.DrSr = Del.DrSr), '')
		AND NOT EXISTS (SELECT 'x' FROM RmMst WHERE	RmCtg= DrRmCtg and RmSCtg= DrRmSCtg
			And RmCd= DrRmCd and RmZ= 'N' And RmValidYN = 'Y' And RmPrtKey=DrPrtKey))
		OR DrRmCd =''
	if @row> 0
	Begin
		select @errmsg= 'Raw Material Code Not Defined/InValid'
		goto ErrHndlr
	end
/*	######################  Manoj #### Ver: 2.0.9 #### Date: 27/12/2004  ######################  */
	/* ****** Sachin 3.02 - Current Partition - CHECK REQUIRED	*/
	select @row= count('x') from inserted Ins where Ins.DrPrtKey=@wCurrPrtn and
		Not Exists (Select 'x' From Deleted Del Where Ins.DrDmIdNo=Del.DrDmIdNo and Ins.DrTcTyp=Del.DrTctyp and Ins.DrCd=Del.DrCd 
					and Ins.DrSz=Del.DrSz and Ins.DrPrtKEy<>Del.DrPrtKey) and
		not exists (select 'x' from RmMst where
				RmCtg= Ins.DrRmCtg and RmSCtg= INs.DrRmSCtg and RmCd= Ins.DrRmCd and RmPrtKey=Ins.DrPrtKey and RmZ= 'N')
	if @row> 0
	Begin
		select @errmsg= 'Raw Material Code Not Defined'
		goto ErrHndlr
	end
/*	##########################################  Manoj ##########################################  */

/* *** Bef 2.14Next *** */
	/* *** Jay 2.13(CT) ***  		(new CT) */
	/* Can Not Insert > 1, RmCtg  in (G,P,S) For DmTcTyp = 'PM'  when Module is 'Y'*/
	/*
	select @row= count('x') from inserted Ins where  DrTcTyp = 'PM' and 
		(select Count('x') from DsgRm Dr where ins.DrTcTyp = Dr.DrTcTyp  and ins.DrCd= Dr.DrCd and
		ins.DrSz= Dr.DrSz and DrRmCtg in ('G','P','S')) > 1
		and exists (select 'x' from Head Where hCompBagsYn ='Y' and HCoCd= 'ZZZ')
	if @row> 0
	Begin
		select @errmsg= 'Can Not Insert More Then One Metel For The Component'
		goto ErrHndlr
	end
	*/
	/* *** Jay 2.13(CT) ***  		(new CT) */
/* *** Bef 2.14Next *** */

	/******  DrSetSCd  =  PSCd ('LABSCD', 'SET')  ******/
	SELECT @row= count('x') FROM inserted Ins WHERE DrRmCtg in ('D', 'C') AND
		((Ins.DrSetSCd <> ISNULL((SELECT Del.DrSetSCd FROM Deleted Del WHERE 
			Ins.DrIdNo=Del.DrIdNo And Ins.DrTcTyp = Del.DrTcTyp And Ins.DrCd = Del.DrCd AND Ins.DrSz=Del.DrSz AND Ins.DrSr = Del.DrSr), '')
		AND NOT EXISTS (SELECT 'x' FROM Param WHERE PTyp= 'LABSCD' and PMCd= 'SET'
			AND PSCd= DrSetSCd And PValidYN = 'Y'))
		OR DrSetSCd = '')
	if @row> 0
	Begin
		select @errmsg= 'Setting Code Not Defined For This Rm Category'
		goto ErrHndlr
	end

    /****** Sachin 3.3.0 (30-06-08) - [28. Valid OrLn1/OrLn2 Check]   ******/      
    Select @row=Count('x') From Inserted Where @mode In ('A','C') and (update(DrLn1) Or Update(DrLn2) Or Update(DrRmCd)) And DrPrtKey=@wCurrPrtn And DrRmCtg In ('D','C') And
			Exists(Select 'x' From Head Where HCoCd=@SelfCoCd and HCd= @wHCd And hChkVldRmLnYN='Y') And
			Not Exists(Select 'x' From VldRmLn Where VrsRmCtg=DrRmCtg 
								And VrsRmId=(Select RmId From RmMst 
									Where RmCtg=DrRmCtg And RmCd=DrRmCd) 
												And VrsLn1=DrLn1 And VrsLn2=DrLn2)		 
    if @row>0       
    Begin      
	   select @errmsg='Ln Not Defined/Ln1 And Ln2 Combination Not Defined In RM Ln Master'      
	   goto ErrHndlr      
	end      

/* (Bef 2.06)
	select @row= count('x') from inserted where DrRmCtg in ('D', 'C') and
		not exists (select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= DrSetSCd)
	if @row> 0
	Begin
		select @errmsg= 'Setting Code Not Defined For This Rm Category'
		goto ErrHndlr
	end
*/
/*  #########################################  Manoj  #########################################  */
	/******  If  DrRmCtg = 'C' or 'D' then  DrSetSCd  =  PSCd ('LABSCD', 'SET')  	else 	DrSetSCd  =  Blank ******/
	select @row= count('x') from inserted where DrRmCtg not in ('D', 'C') and (DrSetSCd<> ''  Or DrSubShp <>'')
	if @row> 0
	Begin
		select @errmsg= 'Setting Code/ Sub Shape Should Not Be Defined For This Rm Category'
		goto ErrHndlr
	end
	/******  DrSubShp  =  Blank  or  PMCd ('SUBSHP')  ******/
	select @row= count('x') from inserted where DrSubShp<> '' and
		not exists (select 'x' from Param where
				PTyp= 'SUBSHP' and PMCd= DrSubShp)
	if @row> 0
	Begin
		select @errmsg= 'Sub Shape Not Defined'
		goto ErrHndlr
	end
	/******  DrAlyCd  =  Blank  or  valid RmCd from RmMst (RmCtg= 'A')  ******/
	/* ****** Sachin 3.02 - Current Partition	*/
	/* ****** Manali 3.03 - 18/06/08 - 'S' and 'L' added */
	select @row= count('x') from inserted where DrRmCtg in ('G', 'P', 'S', 'L') and
		DrAlyCd<> '' and not exists (select 'x' from RmMst where
						RmCtg= 'A' and RmCd= DrAlyCd and RmPrtKey=@wCurrPrtn)
	if @row> 0
	Begin
		select @errmsg= 'Alloy Code Not Defined'
		goto ErrHndlr
	end
	/******  If DrRmCtg<> 'G' or 'P' then 	DrAlyCd  =  Blank  ******/
	/* ****** Manali 3.03 - 18/06/08 - 'S' and 'L' added */
	select @row=count('x') from inserted where DrRmCtg not in ('G', 'P', 'S', 'L')
		and DrAlyCd<>''
	if @row>0
	Begin
		select @errmsg='Alloy Code Should Not Be Entered For This Raw Material Category'
		goto ErrHndlr
	end
	/******  DrMainMet  =  PMCd ('YN')  ******/
	select @row= count('x') from inserted where
		not exists (select 'x' from Param where
			PTyp= 'YN' and PMCd= DrMainMet)
	if @row> 0
	Begin
		select @errmsg= 'Raw Material Code Is The Main Metal (Y/N)'
		goto ErrHndlr
	end
	/****** Cannot have more than one record with DrMainMet = 'Y'  for a Design Type, Code, Size combination  ******/
	/* ****** Sachin 3.02 - Current Partition	*/
	select @row= count('x') from inserted ins where ins.DrPrtKey=@wCurrPrtn and
		(select count('x') from DsgRm Dr where ins.DrTcTyp = Dr.DrTcTyp  and ins.DrCd= Dr.DrCd and
					ins.DrSz= Dr.DrSz and ins.DrPrtKey=Dr.DrPrtKey and Dr.DrMainMet = 'Y') > 1
	if @row> 0
	Begin
		select @errmsg= 'Cannot Have More Than One Main Metal'
		goto ErrHndlr
	end
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [DsgTgt_INUPDL] ON [DsgTgt]
	    FOR INSERT,UPDATE,DELETE 
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  
 
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgTgt' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 


	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
	 	/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	end

 	/******** Key Cannot Be Changed ********/
 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where
			 not exists (Select 'x' from inserted ins where ins.DtTcTyp= del.DtTcTyp
					and ins.DtCd= del.DtCd and ins.DtSz= del.DtSz and ins.DtSr= del.DtSr)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Change  Type/Code/Sz/Sr'
			GoTo ErrHndlr
		end
	End
	if @mode in ('A','C')
	Begin
		/****** Dsg Code should exist in DsgMst table ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from DsgMst where DmTcTyp=DtTcTyp and DmCd= DtCd and DmSz= DtSz)
		if @row> 0
		begin
			select @errmsg= 'This Type-Code-Size Combination  Not Defined In Design Master'
			goto ErrHndlr
		end
		/******  DtSr  >  0  ******/
		select @row= count('x') from inserted where DtSr<= 0
		if @row> 0
		begin
			select @errmsg= 'Design Target Serial Should Be Greater Than Zero'
			goto ErrHndlr
		end
		/******  DtRmCtg  =  PMCd ('RMCTG')  ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= DtRmCtg)
		if @row> 0
		begin
			select @errmsg= 'Raw Material Category Not Defined'
			goto ErrHndlr
		end
		/******  DtRmSCtg  =  PSCd ('RMSCTG', DtRmCtg)  ******/
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where PTyp= 'RMSCTG'
			and PMCd= DtRmCtg and PSCd= DtRmSCtg)
		if @row> 0
		begin
			select @errmsg= 'Raw Material Sub Category Not Defined'
			goto ErrHndlr
		end
		
		/******  DtRmCd  =  RmCd from RmMst (RmCtg= DtRmCtg, RmSCtg= DtRmSCtg, RmZ= 'N')  ******/
		/* **** Manali 3.5.0 - 06/12/08 - Change of RmCd within RmCtgs allowed for Main Metals */
		select @row= count('x') from inserted where
			(DtRmCtg not In ('G', 'P', 'S', 'L') and
			not exists (select 'x' from RmMst where RmCtg= DtRmCtg and RmSCtg= DtRmSCtg and RmCd= DtRmCd and RmZ= 'N'))
		if @row> 0
		begin
			select @errmsg= 'Raw Material Code Not Defined'
			goto ErrHndlr
		end
		
		/* **** Manali 3.5.0 - 06/12/08 - Change of RmCd within RmCtgs allowed for Main Metals */
		select @row= count('x') from inserted where
			(DtRmCtg In ('G', 'P', 'S', 'L') and
			not exists (select 'x' from RmMst where RmCtg In ('G', 'P', 'S', 'L')  and RmCd= DtRmCd and RmZ= 'N'))
		if @row> 0
		begin
			select @errmsg= 'Raw Material Code Not Defined/ Rm Code only allowed for RmCtg (''G'', ''P'', ''S'', ''L'')'
			goto ErrHndlr
		end
	End
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO

ALTER TRIGGER [DtTbl_INUPDL] ON [DtTbl] 
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCd VARCHAR(8)
	
	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DtTbl' )
		RETURN
	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
				case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end

	set @wSelfCd = 'ZSELF'	

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/* Zubin 213 (Key Cannot Be Changed) */ 
 	if @mode = 'C'
 	Begin
  		select @Row= Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.DtTag= del.DtTag and ins.DtDt= del.DtDt and 
			ins.DtCurCd1= del.DtCurCd1 and ins.DtCurCd2= del.DtCurCd2 )
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Key Fields'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	Begin
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where PTyp='DTTAG' and PMCd= DtTag)
		if @row> 0
		begin
			select @errmsg= 'Date Tag Not Defined'
			goto ErrHndlr
		end
		select @row=count('x') from inserted where DtDt=''
		if @row>0
		begin
			select @errmsg='Date Cannot Be Blank'
			goto ErrHndlr
		end
		/* Zubin 213 ('CNV' added) */ 
		/* Manali 3.03 - 18/06/08 - 'LML' included */
		select @row= count('x') from inserted where DtVal= 0
			and DtTag in ('LMG', 'LMP', 'LMS', 'LML', 'USD', 'CNV')
		if @row> 0
		begin
			select @errmsg= 'Value Cannot Be Zero'
			goto ErrHndlr
		end
		select @row= count('x') from inserted where DtVal<> 0
			and DtTag = 'HOL'
		if @row> 0
		begin
			select @errmsg= 'Value Should Be Zero'
			goto ErrHndlr
		end
		/* Zubin 213 ('CNV' added) */ 
		/* Manali 3.03 - 18/06/08 - 'LML' included */
		select @row= count('x') from inserted where DtTag in ('LMG', 'LMP', 'LMS', 'LML', 'USD', 'CNV') and 
			DtHolYN<> ''
		if @row> 0
		begin
			select @errmsg= 'DtHolYN Field Should Be Blank'
			goto ErrHndlr
		end
		select @row= count('x') from inserted where DtTag= 'HOL' and
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= DtHolYN)
		if @row> 0
		begin
			select @errmsg= 'Date Should Be A Normal Day Or A Holiday'
			goto ErrHndlr
		end
		/* Zubin 213 ('CNV' - DtCurCd1 and DtCurCd2 shld be valid CurCd) */ 
		/* Manali 3.03 - 18/06/08 - 'LML' included */
		select @row= count('x') from inserted where 
			(DtTag = 'CNV' and 
				(
				Not Exists (Select 'x' from Param where PTyp= 'CURNCY' and PMCd= DtCurCd1 and PSCd= '') 
				OR 
				Not Exists (Select 'x' from Param where PTyp= 'CURNCY' and PMCd= DtCurCd2 and PSCd= '')
				)
			) OR 
			(DtTag In ('LMG', 'LMP', 'LMS', 'LML') and 
			Not Exists (Select 'x' from Param where PTyp= 'CURNCY' and PMCd= DtCurCd1 and PSCd= '')) 
		if @row> 0
		begin
			select @errmsg= 'Currency Code Not Defined' 
			goto ErrHndlr
		end 
		/* Zubin 213 ('CNV' - DtCurCd1 and DtCurCd2 cannot be same) */ 
		select @row= count('x') from inserted where DtTag = 'CNV' and DtCurCd1= DtCurCd2 
		if @row> 0
		begin
			select @errmsg= 'Currency Codes Cannot Be Same' 
			goto ErrHndlr
		end
		/* Zubin 213 ('LMG', 'LMP', 'LMS' - DtCurCd1/DtCurCd2 shld be '' 'USD', 'HOL' - DtCurCd2 shld be '') */ 
		/* Manali 3.03 - 18/06/08 - 'LML' included */
		select @row= count('x') from inserted where 
			(DtTag In ('LMG', 'LMP', 'LMS', 'LML') and DtCurCd2<> '') 
			OR 
			(DtTag In ('USD', 'HOL') and (DtCurCd1<> '' Or DtCurCd2<> '')) 
		if @row> 0
		begin
			select @errmsg= 'Currency Code Should Be Blank For This TAG' 
			goto ErrHndlr
		end
		/* Zubin 213 ('CNV' - At least one curr should be base the curr) */ 
/*		select @row= count('x') from inserted ins where DtTag= 'CNV' and 
			not exists (Select 'x' from Head where HCd= @wSelfCd and 
				ins.DtCurCd1= HBaseCurCd or ins.DtCurCd2= HBaseCurCd) 
		if @row> 0
		begin
			select @errmsg= 'At Least One Currency Code Should Be A Base Currency'
			goto ErrHndlr
		end 
*/
		/* Zubin 213 ('CNV' - for any combination a rec with 01/01/80 should exist ) */ 
		select @row= count('x') from inserted ins where ins.DtTag= 'CNV' and ins.DtDt<> '01/01/80' and 
			not exists (Select 'x' from DtTbl Dt where Dt.DtTag= 'CNV' and Dt.DtDt= '01/01/80' and 
				ins.DtCurCd1= Dt.DtCurCd1 and ins.DtCurCd2= Dt.DtCurCd2) 
		if @row> 0
		begin
			select @errmsg= 'Currency Combination Should Exist With ''01/01/80'' '
			goto ErrHndlr
		end
		/* Zubin 213 ('CNV' - CurrCd1-CurrCd2 combination should not exist as CurrCd2-CurrCd1) */ 
		select @row= count('x') from inserted ins where ins.DtTag= 'CNV' and ins.DtDt= '01/01/80' and 
			ins.DtCurCd1<> ins.DtCurCd2 and 
			(Select count('x') from DtTbl Dt where Dt.DtTag= 'CNV' and Dt.DtDt= '01/01/80' and 
				ins.DtCurCd1= Dt.DtCurCd2 and ins.DtCurCd2= Dt.DtCurCd1)> 0 
		if @row> 0
		begin
			select @errmsg= 'Conversion For This Currency Already Exists'
			goto ErrHndlr
		end
	End

	/* Zubin 213 */ 
	if @mode = 'D'
	Begin
		/* (Cannot delete '01/01/80' rec if conv rate exists in DtTbl [DtTag= 'CNV']) */ 
		select @row= count('x') from deleted del where del.DtTag= 'CNV' and del.DtDt= '01/01/80' and 
			Exists (Select 'x' from DtTbl Dt where Dt.DtTag= del.DtTag and Dt.DtDt<> '01/01/80' and 
				Dt.DtCurCd1= del.DtCurCd1 and Dt.DtCurCd2= del.DtCurCd2) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete ''01/01/80'' Record As Conversion Rate(s) Exist For This Currency'
			goto ErrHndlr
		end 
		/* Zubin 213 (Cannot delete '01/01/80' rec if a CurrCd is used in CustMst table [DtTag= 'CNV']) */ 
/*		select @row= count('x') from deleted where DtTag = 'CNV' and DtDt= '01/01/80' and 
			( 
				(
					Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd1) and 
					Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd2) and 
					( Exists (Select 'x' from CustMst where CmCurCd= DtCurCd1) or  
						Exists (Select 'x' from CustMst where CmCurCd= DtCurCd2) ) 
				 )
			 	OR
				( 	( Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd1) 
						and Exists (Select 'x' from CustMst where CmCurCd= DtCurCd1) 
					 )
					Or  
					( Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd2) 
						and Exists (Select 'x' from CustMst where CmCurCd= DtCurCd2) 
					 ) 
				 )
			 )
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete ''01/01/80'' Record As Currency Is Used In CustMst'
			goto ErrHndlr
		end 
*/		/* Zubin 213 (Cannot delete '01/01/80' rec if a CurrCd is used in RmRt table [DtTag= 'CNV']) */ 
/*		select @row= count('x') from deleted where DtTag = 'CNV' and DtDt= '01/01/80' and 
			( 
				(
					Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd1) and 
					Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd2) and 
					( Exists (Select 'x' from RmRt where RrCmCurCd= DtCurCd1) Or 
						Exists (Select 'x' from RmRt where RrCmCurCd= DtCurCd2) ) 
				 )
			 	OR
				( 	( Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= DtCurCd1) 
