  On OrCoCd=OdcoCd and OrTc=OdTc and OrYy=OdYy and OrChr=OdChr and OrNo=OdNo and OrSr=OdSr    
   Join DsgMst On DmTctyp='DM' and DmCd=OdDmCd and DmSz=''  
   Join RmRt On RrTcTyp='WTT' and RrCtg='G' and RrCmCtg='C'     
     and round(qOrPrdWt,3) between round(RrFrLn,3) and round(RrToLn,3)    
     And RrCmCd In (OdOmCmCd,'ZSELF') And RrDmCtg in (DmCtg,'') And RrDmCd In (OdDmCd,'')    
    Left Outer Join Param On  PTyp='IWTFRORD' and PMCd=OdIWtFrOrd    
    Order By (Case when RrCmCd=OdOmCmCd Then 1 Else 2 End),    
    (Case when RrDmCtg=DmCtg and RrDmCd=OdDmCd Then 1 Else 2 End),    
  (Case when RrDmCtg=DmCtg and RrDmCd='' Then 1 Else 2 End)     
  
    Select @Row=Count('x')    
    From Inserted ins    
    Join (Select TdCoCd,TdBYy,TdBChr,TdBNo,    
   sum(TdRmWt* (case when TdFrRmLoc= 'W' and TdFrRmDC= 'C' then -1     
     when TdFrRmLoc= 'W' and TdFrRmDC= 'D' then 1     
      when TdToRmLoc= 'W' and TdToRmDC= 'C' then -1     
      when  TdToRmLoc='W' and TdToRmDC= 'D' then 1 else 0 end))    
      qTdRmWt      
   From Txnd     
   Where TdRmCtg='G'    
   Group By TdCoCd,TdBYy,TdBChr,TdBNo) TdRm    
  On TdCoCd=FdCoCd and TdBYy=FdBYy and TdBChr=FdBChr and TdBNo=FdBNo     
    Where FdQty>0 and convert(decimal(10,3),(qTdRmWt/FdQty)) not between convert(decimal(10,3),@RrMinTol)   
  and convert(decimal(10,3),@RrMaxTol) and IsNull(@RrMinTol,-1)>-1 and IsNull(@RrMaxTol,-1)>-1     
    If @Row > 0    
    Begin     
  Select @ErrMsg= 'Cannt Move the bag to Fg, Gold Wt Not Within the Tolerance Range, Only Authorised Users Can Enter This Bags Into Fg'    
  GoTo ErrHndlr    
    End  
  End   
  */ 
  End    

  /*** Geeta 3.2.1 [10-06-2008] - Changed Tolerance for speed issues at Shrenuj and Other places ****/      
    
  /******************** Geeta ***** Emr2.06 *****************************************************/      
  /**** If @mode= 'A'  then  Valid Bag, BCls='N', BLoc<> 'PFG', BPtQty=0, BRjQty=0, BRjPtQty=0 ****/    
  if @mode= 'A'    
  Begin    
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
/*     
   select @Row= Count('x') from inserted    
    where not exists(select 'x' from Bag where FdCoCd= BCoCd     
     and FdBYy= BYy  and FdBChr= BChr and FdBNo= BNo and BCls= 'N'     
     and BPtQty= 0 and BRjQty= 0 and BRjPtQty= 0 and BLoc<> 'PFG')    
   If @Row > 0    
   begin     
    Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Already In Fg/ Bag Rej Or Part Qty <> 0'    
    GoTo ErrHndlr    
   end    
*/     
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
    
   /*** Cannot move to 'PFG' Loc if Bag Not Acknowledged ***/    
   /* Current Partition */    
   select @Row= Count('x') from inserted    
    where FdPRtKey=@wCurrPrtn and exists(select 'x' from Txnd     
     where TdPRtKey=FdPrtKey and TdBIdNo=FdBIdNo and TdCoCd= FdCoCd     
     and TdBYy= FdBYy and TdBChr= FdBChr and TdBNo= FdBNo     
     and TdSrNo= 0 and TdYyKey= FdBYyKey and TdAck= 'N')    
   If @Row > 0    
   begin     
    Select @ErrMsg= 'Bag Not Acknowledged In Previous Transaction'    
    GoTo ErrHndlr    
   end    
      
   /***** If BNo<> 0 then Production Order Number should be valid For The Bag *******/    
   /* Current Partition */    
   select @Row= Count('x') from inserted    
    where FdPrtKey=@wCurrPrtn and FdBNo<> 0 and     
     not exists(select 'x' from Bag     
      where FdPrtKey=BPrtKey and FdCoCd= BCoCd     
       and FdPrdOdTc= BOdTc and FdPrdOdYy= BOdYy and FdPrdOdChr= BOdChr     
       and FdPrdOdNo= BOdNo and FdPrdOdSr= BOdSr)    
   If @Row > 0    
   begin     
    Select @ErrMsg= 'Invalid Production Order Number'    
    GoTo ErrHndlr    
   end    
    
   /********* URMI 2.04-3 BAG QUANTITY shld not be 0 when brought to FG */    
   /* Current Partition */    
   Select @Row=Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and FdBNo <> 0 and    
    exists(select 'x' from Bag where FdPrtKey=BPrtKey and FdBIdNo=BIdNo and FdCoCd= BCoCd and FdBYy= BYy    
    and FdBChr= BChr and FdBNo= BNo and BQty= 0)    
   If @Row>0    
   begin    
      Select @ErrMsg= 'Bag with 0 Quantity Cannot be copied to FG'    
      GoTo ErrHndlr    
   end    
   /********* URMI 2.04-3 BAG QUANTITY shld not be 0 when brought to FG */    
  End    
    
  if @mode In ('A','C') /* Manali added mode **/
  Begin    
    /***** FdDespQty >= 0 *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdDespQty)))
    Begin
      Select @Row= Count('x') From Inserted Ins Where FdPrtKey=@wCurrPrtn and FdDespQty< 0    
      If @Row> 0    
      begin    
         Select @ErrMsg= 'Finished Goods Despatch Qty cannot Be Less Than Zero'    
         GoTo ErrHndlr    
      end    
    End
      
    /***** FdCTBDespQty >= 0 *****/    
    If @mode='A' or (@mode='C' and (Update(FdCTBDespQty)))
    Begin
      Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and  Round(FdCTBDespQty, 1)< 0    
      If @Row> 0    
      begin    
         Select @ErrMsg= 'Finished Goods Contractor Despatch Qty cannot Be Less Than Zero'    
         GoTo ErrHndlr    
      end    
    End
          
    /***** If FdCTBDespQty > 0 then match 'FWB' voucher should not exist for this 'FB' voucher *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdCTBDespQty) or Update(FdYy) or Update(FdKey)))
    Begin
      Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and Round(FdCTBDespQty, 1)> 0 and     
       exists(select 'x' from Fgd M where M.FdPrtKey=ins.FdPrtKey and M.FdCoCd= ins.FdCoCd and M.FdRefYy= ins.FdYy     
       and M.FdRefKey= ins.FdKey     
       and (Select PValue from Param where PTyp= 'TC' and PMCd= M.FdTc)= 'FWB')     
      If @Row> 0    
      begin    
         Select @ErrMsg= 'CTB Despatch Qty Should Be Zero As Bag Is Under Production'    
         GoTo ErrHndlr    
      end    
          
      /***** If 'FWB' rec exists for Bag then 'CTB' rec should not exist for the Bag *****/    
      /* Current Partition */    
      Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and     
       exists(select 'x' from Fgd M where M.FdPrtKey=Ins.FdPrtKey and M.FdCoCd= ins.FdCoCd and M.FdRefYy= ins.FdYy     
        and M.FdRefKey= ins.FdKey and (Select PValue from Param     
        where PTyp= 'TC' and PMCd= M.FdTc)= 'FWB')     
       and exists(select 'x' from InvFgd where IfPrtKey=FdPrtKey and IfBIdNo=FdBIdNo and IfCoCd= FdCoCd and IfFdBYy= FdBYy     
        and IfFdBChr= FdBChr and IfFdBNo= FdBNo and (Select PValue     
        from Param where PTyp= 'TC' and PMCd= IfTc)= 'CTB')     
       /* and Round(FdDespQty, 1)> 0 */    
      If @Row> 0    
      begin    
         Select @ErrMsg= 'Bag Cannot Be Sent Back To Production As CTB Bill Exists For The Bag'    
         GoTo ErrHndlr    
      end    
    End
        
       /**** If BNo <> 0 then FdDmCd, FdSfx, FdPrdCmCd should match with Bag *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdDmCd) or Update(FdSfx) or Update(FdDmSz) or Update(FdPrdCmCd)))
    Begin
      select @Row= Count('x') from inserted     
        join Bag on FdPrtKey=BPrtKey and FdBIdNo=BIdNo and FdCoCd= BCoCd and FdBYy= BYy and FdBChr= BChr and FdBNo= BNo     
        join OrdMst on OmPrtKey=BPrtKey and OmIdNo=BOmIdNo and OmCoCd= BCoCd and OmTc=BOdTc and OmYy= BOdYy and OmChr= BOdChr and OmNo= BOdNo     
       where FdPrtKey=@wCurrPrtn and (FdDmCd<> BOdDmCd or FdSfx<> BOdSfx or FdDmSz<> BOdDmSz or FdPrdCmCd<> OmCmCd)    
        and FdBNo<>0    
      If @Row> 0    
      begin     
       Select @ErrMsg= 'Design/Customer Code Fields Do Not Match With Bag'    
       GoTo ErrHndlr    
      end     
    End
          
    /***** Exp Ord, Exp Cust Should Be Entered *******/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                         or Update(FdExpOdSr) or Update(FdExpCmCd)))
    Begin
      select @Row= Count('x') from inserted where FdPrtKey=@wCurrPrtn and    
        (FdExpOdTc= '' or FdExpOdYy= '' or FdExpOdChr= '' or FdExpOdNo= 0 or FdExpOdSr= 0 or     
        FdExpCmCd= '')    
      If @Row > 0    
      begin     
       Select @ErrMsg= 'Export Order And Export Customer Should Be Entered'    
       GoTo ErrHndlr    
      end    
    End
          
    /**** If BNo<> 0 then Exp Order= Prd Ord and Exp Cust= Prd Cust *****/    
  /* (commented for ver 2.01)       
    select @Row= Count('x') from inserted     
     where (FdExpOdTc<> FdPrdOdTc or FdExpOdYy<> FdPrdOdYy or FdExpOdChr<> FdPrdOdChr or FdExpOdNo<> FdPrdOdNo     
      or FdExpOdSr<> FdPrdOdSr or FdExpCmCd<> FdPrdCmCd)    
      and FdBNo<> 0    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Export Ord/ Cust Should Be Equal To The Prd Ord/ Cust'    
     GoTo ErrHndlr    
    end    
  */  /******************Geeta*****Emr206*************OdHld= 'N' check is removed *************/    
    /******if OdHld= 'N' or 'Y'  Bag is Allowed to move to Fg*****************/     
    /**** Exp Ord Should Be Valid OrdDsg wTcTyp= 'SO', with same FdDmCd *******/    
    If @mode='A' or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                         or Update(FdExpOdSr) or Update(FdDmCd)))
    Begin
      Select @row= Count('x') from inserted where FdPrtKey=@wCurrPrtn and    
        (    
        (not exists(select 'x'  from param where PTyp='TC'    
         and PMcd=FdExpOdTc and PScd='' and PValue='SO'))    
        OR    
        (not exists(select 'x' from OrdDsg where FdPrtKey=OdPrtKey and FdCoCd=OdCoCd and     
         FdExpOdTc=OdTc and FdExpOdYy=OdYy and FdExpOdChr=OdChr and     
         FdExpOdNo=OdNo and FdExpOdSr=OdSr and FdDmCd= OdDmCd ))     
        )    
        and (FdExpOdTc<>'' or FdExpOdYy<>'' or FdExpOdChr<>'' or     
         FdExpOdNo<>0 or FdExpOdSr<>0)    
      If @Row> 0    
      begin     
       Select @ErrMsg= 'Exp Ord No does not exist / Dsg Cd MisMatch/ Exp.Tc<> ''SO'' '    
       GoTo ErrHndlr    
      end    
    End
          
       /**** FdExpCmCd should Match With Exp Ord *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                         or Update(FdExpOdSr) or Update(FdExpCmCd)))
    Begin
      select @Row= Count('x') from inserted     
        join OrdMst on OmPrtKey=FdPrtKey and OmCoCd= FdCoCd and OmTc= FdExpOdTc and OmYy= FdExpOdYy and OmChr= FdExpOdChr and OmNo= FdExpOdNo     
       where FdPrtKey=@wCurrPrtn and FdExpCmCd<> OmCmCd     
      If @Row> 0    
      begin     
       Select @ErrMsg= 'Export Customer Code Does Not Match With Exp Ord'    
       GoTo ErrHndlr    
      end    
    End
          
       /**** RM Content In The Prd Order Should Exist In The Exp order *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                         or Update(FdExpOdSr) or Update(FdPrdOdTc) or Update(FdPrdOdYy) or Update(FdPrdOdChr) or Update(FdPrdOdNo)
                         or Update(FdPrdOdSr)))
    Begin
      select @Row= Count('x') from inserted join OrdRm Pr on OrPrtKey=FdPrtKey and OrCoCd= FdCoCd and     
       OrTc= FdExpOdTc and OrYy= FdExpOdYy and OrChr= FdExpOdChr and     
       OrNo= FdExpOdNo and OrSr= FdExpOdSr     
       where FdPrtKey=@wCurrPrtn and not exists(Select 'x' from OrdRm Ex Where OrPrtKey=FdPrtKey and OrCoCd= FdCoCd and     
        OrTc= FdPrdOdTc and OrYy= FdPrdOdYy and OrChr= FdPrdOdChr and     
        OrNo= FdPrdOdNo and OrSr= FdPrdOdSr and Ex.OrRmCd= Pr.OrRmCd)     
      If @Row> 0    
      begin     
       Select @ErrMsg= 'Rm In Export Ord Not Matching With Rm In Prd Ord'    
       GoTo ErrHndlr    
      end    
      
      
    -- Manoj 2.10.0    
             /**** RM Content In The Prd Order Should Exist In The Exp order *****/    
    /*    
      select @Row= Count('x') from inserted join OrdRm Pr on OrCoCd= FdCoCd and     
       OrTc= FdExpOdTc and OrYy= FdExpOdYy and OrChr= FdExpOdChr and     
       OrNo= FdExpOdNo and OrSr= FdExpOdSr     
       where not exists(Select 'x' from OrdRm Ex Where OrCoCd= FdCoCd and     
        OrTc= FdPrdOdTc and OrYy= FdPrdOdYy and OrChr= FdPrdOdChr and     
        OrNo= FdPrdOdNo and OrSr= FdPrdOdSr and Ex.OrRmCd= Pr.OrRmCd)     
    */    
      /* Current Partition */    
      Select @Row= Count('x') From Inserted Where FdPrtKEy=@wCurrPrtn and (FdPrdOdTc <> FdExpOdTc Or     
        FdPrdOdYy <> FdExpOdYy Or FdPrdOdChr <> FdExpOdChr Or     
        FdPrdOdNo <> FdExpOdNo Or FdPrdOdSr <> FdExpOdSr) And     
       Exists    
       (Select 1 From     
        (Select OrCoCd, OrTc, OrYy, OrChr, OrNo, OrSr, OrRmCd from OrdRm     
        Where OrPrtKey=FdPRtKey and OrCoCd = FdCoCd And OrTc = FdPrdOdTc And OrYy = FdPrdOdYy And     
         OrChr = FdPrdOdChr And OrNo = FdPrdOdNo And OrSr = FdPrdOdSr) PR    
       FULL OUTER JOIN     
        (Select OrCoCd, OrTc, OrYy, OrChr, OrNo, OrSr, OrRmCd from OrdRm     
        Where OrPrtKey=FdPrtKey and OrCoCd = FdCoCd And OrTc = FdExpOdTc And OrYy = FdExpOdYy And     
         OrChr = FdExpOdChr And OrNo = FdExpOdNo And OrSr = FdExpOdSr) ER    
       ON PR.OrRmCd = ER.OrRmCd    
       WHERE ((PR.OrRmCd is Null) Or (ER.OrRmCd is Null))    
       )    
      If @Row> 0    
      begin     
       Select @ErrMsg= 'Rm In Export Order Not Matching With Rm In Production Order'    
       GoTo ErrHndlr    
      end    
    End      
  -- Manoj 2.10.0     
      
      
      
           /**** RM Content In The Bag Should Exist In The Exp order *****/    
    /*** Ver 2.01 (correct code but is time consuming) ***/    
  /*  select @Row= Count('x') from inserted join Txnd on TdCoCd= FdCoCd     
      and TdBYy= FdBYy and TdBChr= FdBChr and TdBNo= FdBNo     
      and TdSrNo<> 0 and TdRmCd <> '' where TdRmCd     
      not in(Select OrRmCd from OrdRm where OrCoCd= FdCoCd     
      and OrTc= FdExpOdTc and OrYy= FdExpOdYy and OrChr= FdExpOdChr     
      and OrNo= FdExpOdNo and OrSr= FdExpOdSr)     
      group by TdCoCd, TdBYy, TdBChr, TdBNo, TdRmCd     
      having  Round(sum((case (case when TdFrRmLoc='W' then TdFrRmDc     
         when TdToRmLoc='W' then TdToRmDc     
         else '' end)     
        when 'C' then -1 when 'D' then +1     
        else 0 end)* TdRmQty), 3) > 0 or     
       Round(sum((case (case when TdFrRmLoc='W' then TdFrRmDc     
         when TdToRmLoc='W' then TdToRmDc end)     
         when 'C' then -1 when 'D' then +1     
         else 0 end)* TdRmWt), 3) > 0      
    If @Row> 0    
    begin     
     Select @ErrMsg= 'Rm In Export Ord Not Matching With Rm In Bag'    
     GoTo ErrHndlr    
    end    
  */    
      
    /**** FdPlChr  '' or  Valid PMcd('PlChr')  ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdPlChr)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
        Not Exists (Select 'x' From Param where PTyp= 'PlChr'    
          and PMCd= FdPlChr and PSCd= '')    
        and FdPlChr<>''    
        If @Row>0    
      begin    
       Select @ErrMsg='Invalid Pl Chr'    
         GoTo ErrHndlr    
      end    
    End
          
    /**** FdPlYy  ''  or  Valid PMcd('Yy') ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdPlYy)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
        Not Exists (Select 'x' From Param where PTyp= 'YY'    
          and PMCd= FdPlYy and PScd= '')    
        and FdPlYy<>''    
        If @Row>0    
      begin    
       Select @ErrMsg='Invalid Pl Yy'    
         GoTo ErrHndlr    
      end    
    End
          
    /**** FdPlChr...FdPlNo Either all empty or all filled ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdPlChr) or Update(FdPlYy) or Update(FdPlNo)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
        (( (FdPlChr<> '' or FdPlYy<> '') and FdPlNo=0)    
              or ( (FdPlChr= '' or FdPlYy= '') and FdPlNo<>0))        
      If @Row>0    
      begin    
       Select @ErrMsg='Invalid Pl Chr/Yy/No'    
         GoTo ErrHndlr    
      end    
    End
          
    /***** FdInTc  '' or Pvalue1('TcTyp',Pvalue('Tc',FdInTc) = 'In') *******/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdInTc)))
    Begin
      select @row=count('x') from inserted join Param p1 on     
       p1.PTyp= 'TC'and p1.PMcd= FdInTc and p1.PScd= ''     
       where FdPRtKey=@wCurrPrtn and IsNull((select p2.PValue1 from Param p2 where p2.PTyp='TCTYP'     
          and p2.PMcd= p1.PValue and p2.PSCd= ''    
                     ), '') not in('In')    
        and FdInTc<> ''    
      If @Row> 0     
      begin    
       Select @ErrMsg='Invoice Tc of only ''In'' Type permitted'    
       GoTo ErrHndlr    
      end    
    End
          
    /***** FdInYy '' or PMcd('Yy') *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdInYy)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
        Not Exists (Select 'x' From Param where PTyp= 'YY'     
          and PMCd= FdInYy and PScd= '')    
        and FdInYy<> ''    
        If @Row> 0     
      begin    
       Select @ErrMsg= 'Invalid Invoice Yy'    
         GoTo ErrHndlr    
      end    
    End
          
    /***** FdInChr  '' or PMcd('Chr', InTc) *****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdInTc) or Update(FdInChr)))
    Begin
      Select @Row= Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
        Not Exists (Select 'x' From vParam where vPCoCd=FdCoCd and     
         vPTyp='Chr' and vPMCd = FdInTc and vPScd=FdInChr)    
        and FdInChr<> ''    
        If @Row> 0    
      begin    
       Select @ErrMsg= 'Invalid Invoice Chr'    
         GoTo ErrHndlr    
      end    
    End
          
    /***** FdInTc...FdInNo Either all empty or all filled****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdInTc) or Update(FdInChr) or Update(FdInYy) or Update(FdInNo)))
    Begin
      Select @Row= Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and     
        (( (FdInTc<> '' or FdInYy<> '' or FdInChr<> '') and FdInNo= 0)    
              or ( (FdInTc= '' or FdInYy= '' or FdInChr= '') and FdInNo<> 0))    
        If @Row> 0    
      begin    
       Select @ErrMsg='Invalid Invoice Tc/Yy/Chr/No'    
         GoTo ErrHndlr    
      end    
    End
          
    /**** FdDespQty <= FdQty ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdDespQty) or Update(FdQty)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and FdDespQty > FdQty    
        If @Row>0    
      begin    
       Select @ErrMsg= 'Desp Qty should be<= Quantity'    
         GoTo ErrHndlr    
      end    
    End
          
    /**** FdCTBDespQty  <=  FdQty ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdCTBDespQty) or Update(FdQty)))
    Begin
      Select @Row= Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and FdCTBDespQty > FdQty    
        If @Row> 0    
      begin    
       Select @ErrMsg= 'Contractor Desp Qty should be<= Quantity'    
         GoTo ErrHndlr    
      end    
    End
          
    /**** FdRefKey= FdKey and FdRefYy= FdYy ****/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdRefYy) or Update(FdYy) or Update(FdRefKey) or Update(FdKey)))
    Begin
      Select @Row=Count('x') From Inserted Where FdPrtKEy=@wCurrPrtn and (FdRefYy<> FdYy  or FdRefKey<> FdKey)    
        If @Row>0    
      begin    
       Select @ErrMsg= 'Reference Yy/Key Should Be Equal To Yy/Key'                                                                
         GoTo ErrHndlr    
      end    
    End
            
    /******* FdBYyKey = BLstYyKey ******/     
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdBYyKey)))
    Begin
      Select @Row=Count('x') From Inserted join Bag on BPrtKey=FdPrtKey and BCoCd= FdCoCd and BYy= FdBYy and BChr= FdBChr and BNo= FdBNo     
       Where FdBYyKey<> BLstYyKey     
        If @Row>0    
      begin    
       Select @ErrMsg= 'FdBYyKey Should Be Equal To The YyKey Of The Last Transaction Of The Bag'    
         GoTo ErrHndlr    
      end    
    End
          
    /******  FdSubLoc  =  vPMCd ('FGSUBLOC')  ******/    
    /* Current Partition */    
    If @mode='A' or (@mode='C' and (Update(FdSubLoc)))
    Begin
      select @row= count('x') from inserted where FdPrtKey=@wCurrPrtn and    
            not exists (select 'x' from vParam where vPCoCd= FdCoCd and     
         vPTyp= 'FGSUBLOC' and vPMCd= FdSubLoc)    
      if @row> 0      
      begin    
       select @errmsg= 'Finished Goods Sub Location Not Defined'    
       goto ErrHndlr    
      end    
    End
  End /* Manali Added mode */
      
  /*******urmi***********************/    
  if @mode= 'C'    
  Begin    
   /*###*/    
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
   /******* Cannot Change If Fwb Transaction Has Taken Place For The Bag After The FB Movement ******/     
/*   select @Row= Count('x') from Deleted del where      
        exists(Select 'x' from Fgd Fgd1 where Fgd1.FdCoCd= del.FdCoCd and     
        Fgd1.FdBYy= del.FdBYy and Fgd1.FdBChr= del.FdBChr and     
        Fgd1.FdBNo= del.FdBNo and     
        ( (Fgd1.FdYy > del.FdYy)     
    or     
    (Fgd1.FdYy = del.FdYy and Fgd1.FdKey> del.FdKey)    
               ) )      
   If @Row> 0    
   begin        
    Select @ErrMsg= 'Cannot Change As Not The Last Transaction Of The Bag'    
    GoTo ErrHndlr    
   end    
*/     
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
    
   /*###%%%*/    
   /******* Cannot Change If FG Movement has happened For The Bag ******/    
   /* Current Partition */    
    If Update(FdGrWt) or Update(FdExpCmCd) or Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or 
        Update(FdExpOdNo) or Update(FdExpOdSr) or Update(FdDesc) or Update(FdPlYy) or Update(FdPlChr) or Update(FdPlNo) or 
        Update(FdInTc) or Update(FdInYy) or Update(FdInChr) or Update(FdInNo) or Update(FdInExpNo) or
        Update(FdSubLoc)
    Begin    
       select @Row= Count('x') from Deleted del where del.FdPrtKey=@wCurrPrtn and    
        not exists(Select 'x' from inserted ins where ins.FdPrtKey=del.FdPrtKey and ins.FdIdNo=del.FdIdNo     
         and ins.FdTc= del.FdTc and ins.FdYy= del.FdYy and ins.FdChr= del.FdChr     
         and ins.FdNo= del.FdNo and ins.FdSr= del.FdSr     
         and ins.FdGrWt= del.FdGrWt and ins.FdExpCmCd= del.FdExpCmCd     
         and ins.FdExpOdTc= del.FdExpOdTc and ins.FdExpOdYy= del.FdExpOdYy     
         and ins.FdExpOdChr= del.FdExpOdChr and ins.FdExpOdNo= del.FdExpOdNo     
         and ins.FdExpOdSr= del.FdExpOdSr and ins.FdDesc= del.FdDesc     
         and ins.FdPlYy= del.FdPlYy and ins.FdPlChr= del.FdPlChr     
         and ins.FdPlNo= del.FdPlNo and ins.FdInTc= del.FdInTc     
         and ins.FdInYy= del.FdInYy and ins.FdInChr= del.FdInChr     
         and ins.FdInNo= del.FdInNo and ins.FdInExpNo= del.FdInExpNo     
         and ins.FdSubLoc= del.FdSubLoc)     
        and exists(Select 'x' from Fmd Fmd1 where Fmd1.FmdPrtKey=del.FdPrtKey and Fmd1.FmdCoCd= del.FdCoCd     
         and Fmd1.FmdBYy= del.FdBYy and Fmd1.FmdBChr= del.FdBChr     
         and Fmd1.FmdBNo= del.FdBNo and     
         ((Fmd1.FmdFdYy> del.FdYy)    
          or    
          (Fmd1.FmdFdYy= del.FdYy and Fmd1.FmdFdKey>= del.FdKey)    
         ))    
       If @Row> 0    
       begin        
        Select @ErrMsg= 'Cannot Change As Fg Movement Has Happened For The Bag'    
        GoTo ErrHndlr    
       end    
    End       
   
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
/*   select @Row= Count('x') from Deleted del where     
         not exists(select 'x' from Bag where FdCoCd= BCoCd     
         and FdBYy= BYy and FdBChr= BChr and FdBNo= BNo     
    and (BCls= 'N' or exists(Select 'x' from inserted ins     
      where ins.FdCoCd= del.FdCoCd and     
      ins.FdTc= del.FdTc and     
      ins.FdYy= del.FdYy and     
      ins.FdChr= del.FdChr and     
      ins.FdNo= del.FdNo and     
      ins.FdSr= del.FdSr and    
      Round(ins.FdCTBDespQty, 1)<> Round(del.FdCTBDespQty, 1)))     
         and BLoc= 'PFG')     
   If @Row> 0    
   begin        
    Select @ErrMsg= 'Cannot Change As Bag Is Closed Or Bag Not In PFG'    
    GoTo ErrHndlr    
   end    
*/    
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
  End    
  /******** urmi 2.04  **********************/    
    
 End    
    
    
 if @mode in ('A', 'C') and @wTcTyp= 'FR'    
 Begin    
  /**** If @mode='A' BagNo, PrdOrd = Blank ****/    
  if @mode='A'    
  Begin    
   /* Current Partition */    
   select @Row= Count('x') from inserted    
    where FdPrtKey=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0 or     
    FdPrdOdTc<> '' or FdPrdOdYy<> '' or FdPrdOdChr<> '' or FdPrdOdNo<> 0 or FdPrdOdSr<> 0)     
   If @Row > 0    
   begin     
    Select @ErrMsg= 'Bag No/ Prd Ord Should Not Be Entered'    
    GoTo ErrHndlr    
   end    
    
  End    
    
  /***** FdDespQty >= 0 *****/    
  /* Current Partition */     
  If @mode='A'  or (@mode='C' and (Update(FdDespQty)))
  Begin    
    Select @Row=Count('x') From Inserted Ins Where FdPrtKey=@wCurrPrtn and FdDespQty< 0    
    If @Row>0    
    begin    
       Select @ErrMsg= 'Finished Goods Despatch Qty cannot Be Less Than Zero'    
       GoTo ErrHndlr    
    end    
  End    
  
  /***** FdCTBDespQty = 0 *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdCTBDespQty)))
  Begin    
    Select @Row= Count('x') From Inserted Ins Where FdPrtKEy=@wCurrPrtn and Round(FdCTBDespQty, 1)<> 0    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Finished Goods Contractor Despatch Qty Should Be 0'    
       GoTo ErrHndlr    
    end    
  End
      
  /**** FdDmCd  Valid DmCd from DsgMst(DmCtg= 'Dm') DmSz='' ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdDmCd)))
  Begin    
    select @Row= Count('x') from inserted where FdPrtKEy=@wCurrPrtn and    
      not exists (Select 'x' from DsgMst where DmPrtKey=@wCurrPrtn and DmTcTyp='DM'     
       and DmCd=FdDmCd and DmSz='')    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Invalid Design Code'    
     GoTo ErrHndlr    
    end    
  End
      
  /**** valid CmCd from CustMst(CmCtg='C') ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdExpCmCd)))
  Begin    
    select @Row= Count('x') from inserted where FdPRtKey=@wCurrPrtn and    
      not exists(select 'x' from CustMst where CmCtg='C'     
       and CmCd= FdExpCmCd)    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Invalid Export Customer Code'    
     GoTo ErrHndlr    
    end    
  End
      
  /**** FdDmSz  Valid PMCd(PTyp= 'DMSZ') ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdDmSz)))
  Begin    
    select @Row= Count('x') from inserted where FdPrtKey=@wCurrPrtn and FdDmSz<> '' and     
      not exists(select 'x' from Param where PTyp= 'DMSZ' and PMCd= FdDmSz)    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Invalid Design Size'    
     GoTo ErrHndlr    
    end    
  End
      
  /***** Exp Ord, Exp Cust Should Be Entered *******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                    or Update(FdExpOdSr) or Update(FdExpCmCd)))
  Begin    
    select @Row= Count('x') from inserted where FdPRtKEy=@wCurrPrtn and    
      (FdExpOdTc= '' or FdExpOdYy= '' or FdExpOdChr= '' or FdExpOdNo= 0 or FdExpOdSr= 0 or     
      FdExpCmCd= '')    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Export Order And Export Customer Should Be Entered'    
     GoTo ErrHndlr    
    end    
  End
      
  /**** Exp Ord Should Be Valid OrdDsg wTcTyp= 'SO', with same FdDmCd *******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                    or Update(FdExpOdSr) or Update(FdExpCmCd) or Update(FdDmCd)))
  Begin    
    Select @row=Count('x') from inserted where FdPRtKey=@wCurrPrtn and    
      (    
      (not exists(select 'x'  from param where PTyp='TC'    
       and PMcd=FdExpOdTc and PScd='' and PValue='SO'))    
      OR    
      (not exists(select 'x' from OrdDsg where FdPRtKey=OdPrtKey and FdCoCd=OdCoCd and     
       FdExpOdTc=OdTc and FdExpOdYy=OdYy and FdExpOdChr=OdChr and     
       FdExpOdNo=OdNo and FdExpOdSr=OdSr and FdDmCd= OdDmCd))    
      )    
      and (FdExpOdTc<>'' or FdExpOdYy<>'' or FdExpOdChr<>'' or     
       FdExpOdNo<>0 or FdExpOdSr<>0)    
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Export Order No does not exist/ Design Cd MisMatch/ Exp.Tc<> ''SO'' '    
     GoTo ErrHndlr    
    end    
  End    
  
     /**** FdExpCmCd should Match With Exp Ord *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or Update(FdExpOdNo)
                    or Update(FdExpOdSr) or Update(FdExpCmCd) ))
  Begin    
    select @Row= Count('x') from inserted     
      join OrdMst on OmPrtKey=FdPrtKey and OmCoCd= FdCoCd and OmTc= FdExpOdTc and OmYy= FdExpOdYy and OmChr= FdExpOdChr and OmNo= FdExpOdNo     
     where FdPrtKey=@wCurrPrtn and FdExpCmCd<> OmCmCd     
    If @Row > 0    
    begin     
     Select @ErrMsg= 'Export Customer Code Does Not Match With Exp Ord'    
     GoTo ErrHndlr    
    end    
  End
      
  /**** FdPlChr  '' or Valid PMcd('PlChr') ****/    
  /* Current Partition */        
  If @mode='A'  or (@mode='C' and (Update(FdPlChr)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and     
      Not Exists (Select 'x' From Param where PTyp= 'PlChr'    
        and PMCd= FdPlChr and PSCd= '')    
      and FdPlChr<>''    
      If @Row>0    
    begin    
     Select @ErrMsg='Invalid Pl Chr'    
       GoTo ErrHndlr    
    end    
  End
      
  /**** FdPlYy  '' of Valid PMcd('Yy') ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdPlYy)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
      Not Exists (Select 'x' From Param where PTyp= 'YY'    
        and PMCd= FdPlYy and PScd= '')    
      and FdPlYy<>''    
      If @Row>0    
    begin    
     Select @ErrMsg='Invalid Pl Yy'    
       GoTo ErrHndlr    
    end    
  End  

  /**** FdPlChr...FdPlNo Either all empty or all filled ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdPlChr) or Update(FdPlYy) or Update(FdPlNo)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
      (( (FdPlChr<> '' or FdPlYy<> '') and FdPlNo=0)    
            or ( (FdPlChr= '' or FdPlYy= '') and FdPlNo<>0))    
      If @Row>0    
    begin     
     Select @ErrMsg='Invalid Pl Chr/Yy/No'    
       GoTo ErrHndlr    
    end    
  End
      
  /***** FdInTc '' or Pvalue1('TcTyp',Pvalue('Tc',FdInTc) = 'In') *******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdInTc)))
  Begin    
    select @row=count('x') from inserted join Param p1 on     
     p1.PTyp= 'TC'and p1.PMcd= FdInTc and p1.PScd= ''     
     where FdPrtKey=@wCurrPrtn and IsNull((select p2.PValue1 from Param p2 where p2.PTyp='TCTYP'     
        and p2.PMcd= p1.PValue and p2.PSCd= ''    
                   ), '') not in('In')    
      and FdInTc<> ''    
    If @Row>0     
    begin    
     Select @ErrMsg='Invoice Tc of only ''In'' Type permitted'    
     GoTo ErrHndlr    
    end    
  End
      
  /***** FdInYy  '' or PMcd('Yy') *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdInYy)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
      Not Exists (Select 'x' From Param where PTyp= 'YY'    
        and PMCd= FdInYy and PScd= '')    
      and FdInYy<> ''    
      If @Row>0    
    begin    
     Select @ErrMsg='Invalid Invoice Yy'    
       GoTo ErrHndlr    
    end    
  End
      
  /***** FdInChr  '' or PMcd('Chr', InTc) *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdInTc) or Update(FdInChr)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
      Not Exists (Select 'x' From vParam where vPCoCd = FdCoCd and     
       vPTyp='Chr' and vPMCd = FdInTc and vPScd=FdInChr)    
      and FdInChr<>''    
      If @Row>0    
    begin    
     Select @ErrMsg='Invalid Invoice Chr'    
       GoTo ErrHndlr    
    end    
  End
      
  /***** FdInTc...FdInNo Either all empty or all filled****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdInTc) or Update(FdInYy) or Update(FdInChr) or Update(FdInNo)))
  Begin    
    Select @Row= Count('x') From Inserted Where FdPrtKey=@wCurrPrtn and    
      (( (FdInTc<> '' or FdInYy<> '' or FdInChr<> '') and FdInNo= 0)    
            or ( (FdInTc= '' or FdInYy= '' or FdInChr= '') and FdInNo<> 0))    
      If @Row> 0    
    begin    
     Select @ErrMsg='Invalid Invoice Tc/Yy/Chr/No'    
       GoTo ErrHndlr    
    end    
  End
      
  /**** FdDespQty <= FdQty****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdDespQty) or Update(FdQty)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPrtKEy=@wCurrPRtn and FdDespQty > FdQty    
      If @Row>0    
    begin    
     Select @ErrMsg= 'Desp Qty should be<= Quantity'    
       GoTo ErrHndlr    
    end    
  End   
  
  /**** FdRefKey= FdKey and FdRefYy= FdYy ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdYy) or Update(FdRefKey) or Update(FdKey)))
  Begin    
    Select @Row=Count('x') From Inserted Where FdPRtKey=@wCurrPRtn and (FdRefYy<> FdYy  or FdRefKey<> FdKey)     
      If @Row>0    
    begin    
     Select @ErrMsg= 'Reference Yy/Key Should Be Equal To Yy/Key'    
       GoTo ErrHndlr    
    end    
  End
        
  /******  FdSubLoc  =  ''  ******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdSubLoc)))
  Begin    
    select @row= count('x') from inserted where FdPrtKey=@wCurrPrtn and FdSubLoc<>''    
    if @row> 0      
    begin    
     select @errmsg= 'Finished Goods Sub Location Should Be Blank'    
     goto ErrHndlr    
    end    
  End
    
 End    
    
 if @mode in ('A', 'C') and @wTcTyp= 'FWB'    
 Begin    
  /**** If @mode='A' then Valid Bag, BCls='N', BLoc= 'PFG' ****/    
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
/*  if @mode='A'    
  Begin    
   select @Row= Count('x') from inserted    
    where not exists(select 'x' from Bag where FdCoCd= BCoCd     
     and FdBYy= BYy and FdBChr= BChr and FdBNo= BNo     
     and BCls= 'N' and BLoc= 'PFG')    
   If @Row > 0    
   begin     
    Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Not In Fg'    
    GoTo ErrHndlr    
   end    
  End    
*/    
/* Zubin 212 (Shifted To Nor For Repl Trigger) */     
    
  /***** FdDespQty = 0 *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdDespQty)))
  Begin    
    Select @Row= Count('x') From Inserted Ins Where FdPRtKey=@wCurrPrtn and FdDespQty<> 0    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Finished Goods Despatch Qty Should Be 0'    
       GoTo ErrHndlr    
    end    
  End
      
  /***** FdCTBDespQty = 0 *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdCTBDespQty)))
  Begin    
    Select @Row= Count('x') From Inserted Ins Where FdPRtKey=@wCurrPrtn and Round(FdCTBDespQty, 1)<> 0    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Finished Goods Contractor Despatch Qty Should Be 0'    
       GoTo ErrHndlr    
    end    
  End
      
  /**** FdRefKey= FdKey and FdRefYy= FdYy of Base Vch ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey)))
  Begin    
    Select @Row=Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and    
     Not Exists(Select 'x' from Fgd B where B.FdPRtKEy=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd     
      and B.FdYy= Ins.FdRefYy and B.FdKey= Ins.FdRefKey     
      and B.FdBM= 'B' and B.FdBNo<> 0)    
      If @Row>0    
    begin    
     Select @ErrMsg= 'Reference Yy/Key Should Be Equal To Yy/Key Of Base Voucher'    
       GoTo ErrHndlr    
    end    
  End
      
         /**** BagNo, FdDmCd, FdSfx, PrdOrd, FdPrdCmCd, Exp Dets should match with Base Vch *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey) Or Update(FdBYy) Or Update(FdBChr) Or 
                    Update(FdBNo) Or Update(FdDmCd) or Update(FdSfx) or Update(FdDmSz) or Update(FdQty) or
                    Update(FdGrWt) or Update(FdPrdOdTc) or Update(FdPrdOdYy) or Update(FdPrdOdChr) or 
                    Update(FdPrdOdNo) or Update(FdPrdOdSr) Or Update(FdPrdCmCd) or
                    Update(FdExpCmCd) or Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or 
                    Update(FdExpOdNo) or Update(FdExpOdSr) or Update(FdPlYy) or Update(FdPlChr) or Update(FdPlNo) or 
                    Update(FdInTc) or Update(FdInYy) or Update(FdInChr) or Update(FdInNo) or Update(FdInExpNo))) 
  Begin    
    Select @Row=Count('x') From Inserted Ins Where Ins.FdPrtKEy=@wCurrPrtn and    
     Not Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd     
      and B.FdYy= Ins.FdRefYy and B.FdKey= Ins.FdRefKey and B.FdBYy= Ins.FdBYy and B.FdBChr= Ins.FdBChr     
      and B.FdBNo= Ins.FdBNo and B.FdDmCd= Ins.FdDmCd and B.FdSfx= Ins.FdSfx     
      and B.FdDmSz= Ins.FdDmSz and B.FdQty= Ins.FdQty and B.FdGrWt= Ins.FdGrWt     
      and B.FdPrdOdTc= Ins.FdPrdOdTc and B.FdPrdOdYy= Ins.FdPrdOdYy     
      and B.FdPrdOdChr= Ins.FdPrdOdChr and B.FdPrdOdNo= Ins.FdPrdOdNo     
      and B.FdPrdOdSr= Ins.FdPrdOdSr and B.FdPrdCmCd= Ins.FdPrdCmCd     
      and B.FdExpCmCd= Ins.FdExpCmCd and B.FdExpOdTc= Ins.FdExpOdTc     
      and B.FdExpOdYy= Ins.FdExpOdYy and B.FdExpOdChr= Ins.FdExpOdChr     
      and B.FdExpOdNo= Ins.FdExpOdNo and B.FdExpOdSr= Ins.FdExpOdSr     
      and B.FdPlYy= Ins.FdPlYy and B.FdPlChr= Ins.FdPlChr and B.FdPlNo= Ins.FdPlNo    
      and B.FdInTc= Ins.FdInTc and B.FdInYy= Ins.FdInYy and B.FdInChr= Ins.FdInChr     
      and B.FdInNo= Ins.FdInNo and B.FdInExpNo= Ins.FdInExpNo)    
      If @Row> 0    
    begin    
     Select @ErrMsg= 'Bag/ Design/ Suffix/ DsgSz/ PrdOrd/ PrdCust/ Exp Dets Should Match With Base Voucher'    
       GoTo ErrHndlr    
    end    
  End
      
  /******* FdBYyKey = BLstYyKey ******/     
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdBYyKey)))
  Begin
    Select @Row= Count('x') From Inserted join Bag on BPrtKey=FdPrtKey and BIdNo=FdBIdNo and BCoCd= FdCoCd and BYy= FdBYy and BChr= FdBChr and BNo= FdBNo     
     Where FdPrtKey=@wCurrPrtn and FdBYyKey<> BLstYyKey     
      If @Row> 0    
    begin    
     Select @ErrMsg= 'FdBYyKey Should Be Equal To The YyKey Of The Last Transaction Of The Bag'    
       GoTo ErrHndlr    
    end    
  End
      
  /******  FdSubLoc  =  ''  ******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdSubLoc)))
  Begin
    select @row= count('x') from inserted where FdPrtKey=@wCurrPrtn and FdSubLoc<>''    
    if @row> 0      
    begin    
     select @errmsg= 'Finished Goods Sub Location Should Be Blank'    
     goto ErrHndlr    
    end    
  End
      
  /*** ###@@@ ***/    
  /***** If FdCTBDespQty of Base > 0 then match 'FWB' rec should not exist for the Bag *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey)))
  Begin
    Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and    
     Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd     
      and B.FdYy= Ins.FdRefYy and B.FdKey= Ins.FdRefKey     
      and B.FdBM= 'B' and B.FdBNo<> 0 and /* Round(FdCTBDespQty, 1)> 0 and */    
      exists(select 'x' from InvFgd where IfPrtKey=B.FdPrtKey and IfBIdNo=B.FdBIdNo and IfCoCd= B.FdCoCd     
       and IfFdBYy= B.FdBYy and IfFdBChr= B.FdBChr and IfFdBNo= B.FdBNo     
       and (Select PValue from Param where PTyp= 'TC' and PMCd= IfTc)= 'CTB')     
      )    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Bag Cannot Be Sent Back To Production As CTB Bill Exists For The Bag'    
       GoTo ErrHndlr    
    end    
        
  /***** FdDespQty of Base <= FdQty of Base *****/    
  /* Current Partition */    
    Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and    
     Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd     
      and B.FdYy= Ins.FdRefYy and B.FdKey= Ins.FdRefKey     
      and B.FdBM= 'B' and B.FdBNo<> 0     
      and B.FdQty< IsNull((Select sum(M.FdQty)     
       from Fgd M where M.FdPrtKey=B.FdPrtKey and M.FdCoCd= B.FdCoCd     
       and M.FdRefYy= B.FdYy and M.FdRefKey= B.FdKey     
       and M.FdBM= 'M'), 0)     
      )    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Desp Qty Should Be<= Quantity'    
       GoTo ErrHndlr    
    end    
  End  
 End    
    
 if @mode in ('A', 'C') and @wTcTyp= 'FWR'    
 Begin    
  /***** Bag= Blank *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdBYy) or Update(FdBChr) or Update(FdBNo)))
  Begin
    Select @Row=Count('x') From Inserted Ins Where FdPrtKey=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0)    
    If @Row>0    
    begin    
       Select @ErrMsg= 'Bag Number Should Not Be Entered'    
       GoTo ErrHndlr    
    end    
  End
       
  /***** FdDespQty = 0 *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdDespQty)))
  Begin
    Select @Row=Count('x') From Inserted Ins Where FdPRtKey=@wCurrPrtn and Round(FdDespQty, 1)<> 0    
    If @Row>0    
    begin    
       Select @ErrMsg= 'Finished Goods Despatch Qty Should Be 0'    
       GoTo ErrHndlr    
    end    
  End
      
  /***** FdCTBDespQty = 0 *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdCTBDespQty)))
  Begin
    Select @Row= Count('x') From Inserted Ins Where FdPRtKey=@wCurrPrtn and Round(FdCTBDespQty, 1)<> 0    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Finished Goods Contractor Despatch Qty Should Be 0'    
       GoTo ErrHndlr    
    end    
  End
       
  /**** FdRefKey= FdKey and FdRefYy= FdYy of Base Vch ****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey)))
  Begin
    Select @Row=Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and    
     Not Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd and B.FdYy= Ins.FdRefYy     
      and B.FdKey= Ins.FdRefKey and B.FdBM= 'B' and B.FdBNo= 0)    
      If @Row> 0    
    begin    
     Select @ErrMsg= 'Reference Yy/Key Should Be Equal To Yy/Key Of Base Voucher'    
       GoTo ErrHndlr    
    end    
  End
       
     /**** BagNo, FdDmCd, FdSfx, PrdOrd, FdPrdCmCd, Exp Dets should match with Base Vch *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey) Or Update(FdBYy) Or Update(FdBChr) Or 
                    Update(FdBNo) Or Update(FdDmCd) or Update(FdSfx) or Update(FdDmSz) or Update(FdQty) or
                    Update(FdGrWt) or Update(FdPrdOdTc) or Update(FdPrdOdYy) or Update(FdPrdOdChr) or 
                    Update(FdPrdOdNo) or Update(FdPrdOdSr) Or Update(FdPrdCmCd) or
                    Update(FdExpCmCd) or Update(FdExpOdTc) or Update(FdExpOdYy) or Update(FdExpOdChr) or 
                    Update(FdExpOdNo) or Update(FdExpOdSr) or Update(FdPlYy) or Update(FdPlChr) or Update(FdPlNo) or 
                    Update(FdInTc) or Update(FdInYy) or Update(FdInChr) or Update(FdInNo) or Update(FdInExpNo))) 
  Begin
    Select @Row=Count('x') From Inserted Ins Where Ins.FdPrtKey=@wCurrPrtn and    
     Not Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKey and B.FdCoCd= Ins.FdCoCd and B.FdYy= Ins.FdRefYy     
      and B.FdKey= Ins.FdRefKey and B.FdBYy= Ins.FdBYy and B.FdBChr= Ins.FdBChr     
      and B.FdBNo= Ins.FdBNo and B.FdDmCd= Ins.FdDmCd and B.FdSfx= Ins.FdSfx     
      and B.FdDmSz= Ins.FdDmSz and B.FdQty= Ins.FdQty and B.FdGrWt= Ins.FdGrWt     
      and B.FdPrdOdTc= Ins.FdPrdOdTc and B.FdPrdOdYy= Ins.FdPrdOdYy     
      and B.FdPrdOdChr= Ins.FdPrdOdChr and B.FdPrdOdNo= Ins.FdPrdOdNo     
      and B.FdPrdOdSr= Ins.FdPrdOdSr and B.FdPrdCmCd= Ins.FdPrdCmCd     
      and B.FdExpCmCd= Ins.FdExpCmCd and B.FdExpOdTc= Ins.FdExpOdTc     
      and B.FdExpOdYy= Ins.FdExpOdYy and B.FdExpOdChr= Ins.FdExpOdChr     
      and B.FdExpOdNo= Ins.FdExpOdNo and B.FdExpOdSr= Ins.FdExpOdSr     
      and B.FdPlYy= Ins.FdPlYy and B.FdPlChr= Ins.FdPlChr and B.FdPlNo= Ins.FdPlNo    
      and B.FdInTc= Ins.FdInTc and B.FdInYy= Ins.FdInYy and B.FdInChr= Ins.FdInChr     
      and B.FdInNo= Ins.FdInNo and B.FdInExpNo= Ins.FdInExpNo)    
      If @Row>0    
    begin    
     Select @ErrMsg= 'Bag/ Design/ Suffix/ DsgSz/ PrdOrd/ PrdCust/ Exp Dets Should Match With Base Voucher'    
       GoTo ErrHndlr    
    end    
  End
         
  /******  FdSubLoc  =  ''  ******/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdSubLoc)))
  Begin
    select @row= count('x') from inserted where FdPrtKey=@wCurrPrtn and FdSubLoc<> ''    
    if @row> 0      
    begin    
     select @errmsg= 'Finished Goods Sub Location Should Be Blank'    
     goto ErrHndlr    
    end    
  End
      
  /*** ###@@@ ***/    
  /***** FdDespQty of Base <= FdQty of Base *****/    
  /* Current Partition */    
  If @mode='A'  or (@mode='C' and (Update(FdRefYy) or Update(FdRefKey)))
  Begin
    Select @Row= Count('x') From Inserted Ins Where Ins.FdPrtKEy=@wCurrPrtn and    
     Exists(Select 'x' from Fgd B where B.FdPrtKey=Ins.FdPrtKEy and B.FdCoCd= Ins.FdCoCd     
      and B.FdYy= Ins.FdRefYy and B.FdKey= Ins.FdRefKey     
      and B.FdBM= 'B' and B.FdBNo= 0     
      and B.FdQty< IsNull((Select sum(M.FdQty)     
       from Fgd M where M.FdPrtKey=B.FdPrtKey and M.FdCoCd= B.FdCoCd     
       and M.FdRefYy= B.FdYy and M.FdRefKey= B.FdKey     
       and M.FdBM= 'M'), 0)     
      )    
    If @Row> 0    
    begin    
       Select @ErrMsg= 'Desp Qty Should Be<= Quantity'    
       GoTo ErrHndlr    
    end    
  End
  
 End    
    
    
    
