Alter TRIGGER [FgRm_INUPDL] ON [FgRm] 
       FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
	/* Trigger Version 3.3.0 - Speed Optimization */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3) 
	Declare @wEntTyp Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 
	
	IF @@ROWCOUNT= 0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'FgRm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	Select @wCurrPrtn='C'

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp= max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FrTc and PSCd=''
	end

	if @mode in ('D')
	Begin
		select @wTcTyp= max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FrTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
			/* Current Partition */
			select @ROW =Count('x')  From inserted where  FrPrtKey=@wCurrPrtn and
			Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FrCoCd +',%')) 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW=Count('x') From Deleted Where FrPrtKey=@wCurrPrtn and 
		Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FrCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 
	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FrTc and PSCd= '' Where FrPrtKey=@wCurrPrtn 
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Current Partition */		
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd= FrTc and PSCd='' Where FrPrtKey=@wCurrPrtn 
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END

	/*** Storing Entry Type In The Variable @wEntTyp ***/
	/* Current Partition */			
	Select @wEntTyp= PValue1 From Param Where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''
	If @Mode = 'C'
	Begin
		/******* If Mode = 'C' then Cannot change Key Values********/
		/* Current Partition */		
		select @Row=Count('x') from Deleted Del where Del.FrPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.FrPrtKey=Del.FrPrtKey 
					and Ins.FrIdNo=Del.FrIdNo and Ins.FrCoCd=Del.FrCoCd 
					and Ins.FrTc=Del.FrTc and Ins.FrYy= Del.FrYy
					and Ins.FrChr= Del.FrChr and Ins.FrNo=Del.FrNo
					and Ins.FrSr=Del.FrSr and Ins.FrSrNo= Del.FrSrNo)
		If @Row > 0
		begin		  
			Select @ErrMsg='Cannot Change FgRm Key values'
			GoTo ErrHndlr
		end
	End

	/* Zubin 212 Lot No. Shld be blank when HLotNoYN= 'N' in head */ 
	/* Manali 3.03 - 16/07/08 - Lot No. open for Acc ('X') also */
	If @wTcTyp in ('FB', 'FWB') 
	Begin
		/* Current Partition */		
		Select @Row= Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and FrLotNo<> '' and 
			Not Exists (Select 'x' From Head where HCoCd= Ins.FrCoCd and HCd= 'ZSELF' and 
				HLotNoYN= 'Y') 
	  	If @Row> 0 
		begin
			Select @ErrMsg= 'Lot No. Should Be Blank As ''Implement Lot No. For D/C/X/G/P/S/L/M'' Option Is ''N'' In Head Master (Tab 5)' 
		  	GoTo ErrHndlr
		end 

		/* Zubin 212 Lot No. For 'D' and 'C' only */ 
		/* Current Partition */	
		/* Manali 3.03 - 16/07/08 - Lot No. open for Acc ('X') also */	
		select @Row= Count('x') from inserted ins where FrLotNo <> '' and FrPrtKey=@wCurrPrtn and
			Not Exists (select 'x' from RmMst where RmZ= 'N' and RmCd= FrRmCd and RmPrtKey=FrPrtKey and RmCtg IN ('D', 'C', 'X','G','P','S','L','M'))
	  	If @Row> 0
		begin
			Select @ErrMsg= 'Lot No. Should Be Entered For Diamonds, Color Stones and Accessories Only' 
			GoTo ErrHndlr
		end
	End

	If @Mode = 'C' and @wTcTyp in ('FB', 'FR')
	Begin
		/**** Cannot edit any field if FdDespQty <> 0 ****/
		/* Zubin 212 (FrLotNo added) */
		/* Current Partition */		
		select @Row= Count('x') from deleted Del
			join Fgd on FdPrtKey=Del.FrPrtKey and FdIdNo=Del.FrFdIdNo and FdCoCd=Del.FrCoCd And FdTc=Del.FrTc 
					And FdYy=Del.FrYy And  FdChr=Del.FrChr And FdNo=Del.FrNo And FdSr=Del.FrSr 
			where FdPrtKey=@wCurrPrtn and FdDespQty<>0 and 
				(not exists(Select 'x' from Inserted Ins where
				Del.FrPrtKey=Ins.FrPrtKey and Del.FrCoCd=Ins.FrCoCd and Del.FrSrno=Ins.FrSrNo and Del.FrFrRmLoc=Ins.FrFrRmLoc
				and Del.FrFrRmDc=Ins.FrFrRmDc and Del.FrRmCd=Ins.FrRmCd and Del.FrLotNo=Ins.FrLotNo 
				and Del.FrRmSz=Ins.FrRmSz and Del.FrRmSz2=Ins.FrRmSz2 and Del.FrRmSz3=Ins.FrRmSz3 and Del.FrRmStkRt=Ins.FrRmStkRt
				and Del.FrRmQty=Ins.FrRmQty and Del.FrRmWt=Ins.FrRmWt 
				and Del.FrToRmLoc=Ins.FrToRmLoc and Del.FrToRmDc=Ins.FrToRmDc))
		If @Row > 0
		begin	
			Select @ErrMsg= 'Cannot Edit as Desp Qty<>0'
			GoTo ErrHndlr
		end
	End

	If @Mode = 'C' and @wTcTyp in ('FWB', 'FWR')
	Begin
		/**** Cannot edit any field ****/
		/* Zubin 212 (FrLotNo added) */
		/* Current Partition */		
		select @Row= Count('x') from deleted Del
			join Fgd on FdPrtKey=Del.FrPrtKey and FdIdNo=Del.FrFdIdNo and FdCoCd= Del.FrCoCd And FdTc= Del.FrTc And 
				    FdYy= Del.FrYy And  FdChr= Del.FrChr And
				    FdNo= Del.FrNo And FdSr= Del.FrSr 
			where Del.FrPrtKEy=@wCurrPrtn and not exists(Select 'x' from Inserted Ins where Del.FrPrtKey=Ins.FrPrtKey and 
				Del.FrCoCd=Ins.FrCoCd and Del.FrSrNo= Ins.FrSrNo and Del.FrFrRmLoc= Ins.FrFrRmLoc
				and Del.FrFrRmDc= Ins.FrFrRmDc and Del.FrRmCd= Ins.FrRmCd and Del.FrLotNo= Ins.FrLotNo
				and Del.FrRmSz= Ins.FrRmSz and Del.FrRmSz2= Ins.FrRmSz2 and Del.FrRmSz3= Ins.FrRmSz3 and Del.FrRmStkRt= Ins.FrRmStkRt
				and Del.FrRmQty= Ins.FrRmQty and Del.FrRmWt= Ins.FrRmWt 
				and Del.FrToRmLoc= Ins.FrToRmLoc and Del.FrToRmDc= Ins.FrToRmDc) 
		If @Row > 0
		begin	
			Select @ErrMsg= 'Cannot Edit Any Value'
			GoTo ErrHndlr
		end
	End


	If @Mode in ('A','C')
	Begin
		/******* Valid FrTc,FrYy,FrChr, FrNo, FrSr ********/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and
  			Not Exists (Select 'x' From Fgd Where FdPrtKey=Ins.FrPrtKey and FdIdNo=FrFdIdNo and FdCoCd= Ins.FrCoCd And 
				    FdTc= Ins.FrTc And FdYy= Ins.FrYy And  FdChr= Ins.FrChr And FdNo= Ins.FrNo And FdSr= Ins.FrSr)
  		If @Row>0
	 	begin
			Select @ErrMsg='FgRm Voucher No. Does Not Exist'
			GoTo ErrHndlr
	  	end

		/***** FrSrNo <> 0 *****/
		/* Current Partition */		
		Select @Row= Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and FrSrNo= 0
		If @Row>0
		begin
	  		Select @ErrMsg='Rm. SrNo Cannot be 0'
		  	GoTo ErrHndlr
		end

		/*********** FrRmCd  Valid RmCd, RmZ='N' *********/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From RmMst where 
				RmCd= FrRmCd and RmPrtKey=FrPrtKey and RmZ= 'N')
  	  	If @Row>0
		begin
			Select @ErrMsg='Invalid Rm Code'
		  	GoTo ErrHndlr
		end

		/********** FrFrRmDc  Valid 'Dc' *************/
		/* Current Partition */		
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and  (Not Exists (Select 'x' From Param where PTyp= 'DC'
				and PMCd = Ins.FrFrRmDc and PScd= '')
				or Not Exists (Select 'x' From Param where PTyp= 'DC'
				and PMCd = Ins.FrToRmDc and PScd= ''))
	  	If @Row>0
		begin
			Select @ErrMsg='Invalid From/ To Rm DC'
		  	GoTo ErrHndlr
		end

		/******* FrToRmDc should be Opp of  FrFrRmDc *******/
		/* Current Partition */
	  	Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and ((FrToRmDc= FrFrRmDc And FrFrRmDc<> '')  Or
				(FrFrRmDc<> '' and FrToRmDc= ''))
	  	If @Row>0
		begin
			Select @ErrMsg='Invalid To Rm Dc'
			GoTo ErrHndlr
		end
	End


	If @Mode in ('A','C') and @wTcTyp in ('FB')
	Begin

		/****** If TcTyp= 'FB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
	  	If @Row> 0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'W' ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKEy=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'W' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end

		/* urmi 2.05 zero wt and qty Not Allowed in FG */
		/****** If TcTyp= 'FB' Then FrRmWT or FrRmQty Should be NonZero ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FrPrtKey=@wCurrPrtn and (FrRmWt=0 AND FrRmQty = 0)
  	  	If @Row>0
		begin
			Select @ErrMsg='Either Wt and Qty should be non zero for the RM'
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FB' Then RM Wt/ Qty Can Be Issued From Locations Of Type 'W' Only ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'W' and ((LocCd= FrFrRmLoc and FrFrRmDc= 'C') 	or
	   					 (LocCd= FrToRmLoc and FrToRmDc= 'C')	
				       		)
   					  )
  	  	If @Row>0
		begin
			Select @ErrMsg= 'RM Wt/ Qty Can Be Issued From Locations Of Type ''W'' Only'
		  	GoTo ErrHndlr
		end

		/***** If FdBagNo<>0 
			FrRmCd to exist in FdPrdOrder****/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPRtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And FdNo=Ins.FrNo And FdSr=Ins.FrSr
			Where Ins.FrPrtKEy=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(Not Exists (select 'x' from OrdRm where OrPrtKey=FdPrtKey and
				    OrCoCd= FdCoCd And OrTc= FdPrdOdTc And
				    OrYy= FdPrdOdYy And OrChr= FdPrdOdChr And
				    OrNo= FdPrdOdNo And OrSr= FdPrdOdSr And 
				    OrRmCd= FrRmCd))
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Prd. Order'
			GoTo ErrHndlr
		end

		/***** FrRmCd to exist in FdExpOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And 
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And
				    FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where not exists(select 'x' from OrdRm where OrPrtKey=FdPrtKey and
				    OrCoCd= FdCoCd And OrTc= FdExpOdTc And
				    OrYy= FdExpOdYy And  OrChr= FdExpOdChr And
				    OrNo= FdExpOdNo And OrSr= FdExpOdSr And 
				    OrRmCd= FrRmCd)
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Exp Order'
			GoTo ErrHndlr
		end

/* ### Correct This Part Of The Trigger ***/ 
		/***** If FdBagNo <> 0
			RmQty >= 0, RmWt >= 0 for the given RmCd, Sz, StkRt 
			BGrWt >= 0    *****/
/*
		select @Row= Count('x') from inserted Ins 
			join Fgd on FdTc= Ins.FrTc And 
				    FdYy= Ins.FrYy And FdChr= Ins.FrChr And 
				    FdNo= Ins.FrNo And FdSr= Ins.FrSr 
			where (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(   (not exists(select 'x' from Bag where 
				    BYy= FdBYy and BChr= FdBChr and BNo= FdBNo
				    and BGrWt>= 0))
				or
				    (not exists(select 'x' from BagRm where
				    BrBYy= FdBYy and BrBChr= FdBChr and BrBNo= FdBNo
				    and BrRmCd= FrRmCd and BrRmSz= FrRmSz

				    and BrRmStkrt= FrRmStkRt and BrRmQty>= 0
				    and BrRmWt>= 0))
				)
		If @Row > 0
		begin	
			Select @ErrMsg= 'Rm Qty<0 / Rm Wt<0 / Bag Gr. Wt<0'
			GoTo ErrHndlr
		end
*/
/* ### Correct This Part Of The Trigger ***/ 

	End


	If @Mode in ('A','C') and @wTcTyp in ('FR')
	Begin

		/********** If TcTyp= 'FR' Then FrFrRmLoc Valid Loc, LocTyp<>'P', 'W' ************/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = Ins.FrCoCd and 
				LocTyp not in ('P', 'W') and LocCd = Ins.FrFrRmLoc)
  	  	If @Row>0
		BEGIN
			Select @ErrMsg='Invalid From Rm Loc'
		  	GoTo ErrHndlr
		END

		/****** If TcTyp= 'FR' then FrToRmLoc  Valid Loc, LocTyp<>'P', 'W'  ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = Ins.FrCoCd and 
				LocTyp not in ('P', 'W') and LocCd = Ins.FrToRmLoc)
  	  	If @Row>0
		BEGIN
			Select @ErrMsg='Invalid To Rm Loc'
		  	GoTo ErrHndlr
		END

		/****** If TcTyp= 'FR' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/***** FrRmCd to exist in FdExpOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtKey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And
				    FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where Ins.FrPrtKEy=@wCurrPrtn and not exists(select 'x' from OrdRm where 
				    OrPrtKey=FdPrtKey and OrCoCd= FdCoCd And OrTc= FdExpOdTc And
				    OrYy= FdExpOdYy And  OrChr= FdExpOdChr And
				    OrNo= FdExpOdNo And OrSr= FdExpOdSr And 
				    OrRmCd= FrRmCd)
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Exp Order'
			GoTo ErrHndlr
		end
	End

	
	/*** (Jen 2.13) ***/
	If @Mode in ('A','C') and @wTcTyp in ('FWB')
	Begin
		/****** If TcTyp= 'FWB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'F' ******/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'F' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
	  	If @Row> 0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then FrFrRmLoc or FrToRmLoc Should Have LocTyp= 'W' ******/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd 
				and LocTyp= 'W' and (LocCd= FrFrRmLoc or LocCd = FrToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then FrRmWT or FrRmQty Should be NonZero ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FrPrtKey=@wCurrPrtn and (FrRmWt=0 AND FrRmQty = 0)
  	  	If @Row>0
		begin
			Select @ErrMsg='Either Wt and Qty should be non zero for the RM'
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then RM Wt/ Qty Can Be Issued From Locations Of Type 'F' Only ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins 
			Where Ins.FrPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd = FrCoCd and 
				LocTyp= 'F' and ((LocCd= FrFrRmLoc and FrFrRmDc= 'C') 	or
	   					 (LocCd= FrToRmLoc and FrToRmDc= 'C'))))
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'RM Wt/ Qty Can Be Issued From Locations Of Type ''F'' Only'
		  	GoTo ErrHndlr
		end

		/****** If FdBagNo<> 0 FrRmCd to exist in FdPrdOrder ******/
		/* Current Partition */
		select @Row= Count('x') from inserted Ins
			join Fgd on FdPrtKey=Ins.FrPrtkey and FdIdNo=Ins.FrFdIdNo and FdCoCd=Ins.FrCoCd And FdTc=Ins.FrTc And
				    FdYy=Ins.FrYy And  FdChr=Ins.FrChr And FdNo=Ins.FrNo And FdSr=Ins.FrSr
			where FrPrtKey=@wCurrPrtn and (FdBYy<> '' or FdBChr<> '' or FdBNo<> 0) and 
				(not exists(select 'x' from OrdRm where 
				    OrPrtKey=FdPrtKey And OrCoCd= FdCoCd And OrTc= FdPrdOdTc And
				    OrYy= FdPrdOdYy And OrChr= FdPrdOdChr And
				    OrNo= FdPrdOdNo And OrSr= FdPrdOdSr And 
				    OrRmCd= FrRmCd))
		If @Row> 0
		begin	
			Select @ErrMsg= 'Rm Code Does Not Exist in Prd. Order'
			GoTo ErrHndlr
		end
	End
	/*** (Jen 2.13) ***/


	If @Mode = 'D'
	Begin
		/**** Cannot delete if FdDespQty <> 0****/
		/* Current Partition */
		Select @Row= Count('x') From deleted Del
			Where Del.FrPrtKey=@wCurrPrtn 
				and (exists(select 'x' from Fgd where FdPrtKey=FrPrtKey and FdIdNo=FrFdIdNo and FdCoCd=FrCoCd And 
								FdTc=FrTc And FdYy=FrYy And  FdChr=FrChr And FdNo=FrNo And FdSr=FrSr and FdDespQty<>0))
		If @Row > 0

		begin	
			Select @ErrMsg= 'Cannot Delete as Desp Qty <> 0'
			GoTo ErrHndlr
		end

/* ###
		**** Cannot delete if Transaction Has Taken Place For The Bag After The Backward Movement ****
		select @Row= Count('x') from deleted Del 
			where @wTcTyp= 'FWB' and not exists(select 'x' from Fgd join Bag on BYy= FdBYy and BChr= FdBChr and 
								BNo= FdBNo where FdTc=FrTc And FdYy=FrYy And  FdChr=FrChr And 
								FdNo=FrNo And FdSr=FrSr and FdBYyKey= BLstYyKey) 
		If @Row > 0

		begin	
			Select @ErrMsg= 'Cannot Delete as Transaction Has Taken Place For The Bag After The Backward Movement'
			GoTo ErrHndlr
		end
### */
	End

	/*** UPDATES ***/

	/*** Update SYyMm from FrFrRmLoc ***/
	/* Zubin 212 (FrLotNo added in SYyMm inserts/updates) */ 
	if @mode in ('C','D')
	Begin
		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty- (select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt= SRmCrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty= SRmDrQty-(select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt= SRmDrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrFrRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd= SRmCd 
			and Del.FrLotNo= SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm) 
		from Deleted Join Fg on FgPrtKey=Deleted.FrPrtKey and FgCoCd= Deleted.FrCoCd and FgTc= Deleted.FrTc and FgYy= Deleted.FrYy 
			and FgChr= Deleted.FrChr and FgNo= Deleted.FrNo 
			where Deleted.FrPrtKey=SPrtKey and Deleted.FrCoCd= SCoCd and Deleted.FrRmCd= SRmCd and Deleted.FrLotNo= SLotNo 
			and Deleted.FrRmSz= SRmSz and Deleted.FrRmSz2= SRmSz2 and Deleted.FrRmSz3= SRmSz3 and Deleted.FrRmStkRt= SRmStkRt 
			and Deleted.FrFrRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Deleted.FrFrRmDc='D'  or Deleted.FrFrRmDc='C')
	End


	if @mode in ('A','C')
	Begin
		/* Current Partition */
		insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmSz2,SRmSz3,SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt) 
			select distinct FrPrtKey,FrCoCd,FrRmCd,FrLotNo,FrRmSz,FrRmSz2,FrRmSz3,FrRmStkRt,FrFrRmLoc,convert(int,convert(varchar(6),Fgdt,112)),0,0,0,0
			from inserted join Fg on FgPRtKey=FrPrtKey and FgCoCd=FrCoCd and FgTc=FrTc and FgYy=FrYy and FgChr=FrChr and FgNo=FrNo
			where not exists(select 'x' from  SYyMm where SPrtKey=FrPrtKey and SCoCd= FrCoCd and SRmCd=FrRmCd and SLotNo=FrLotNo 
			and SRmSZ=FrRmSz and SRmSZ2=FrRmSz2 and SRmSZ3=FrRmSz3 and SRmStkRt=FrRmStkRt and SLoc=FrFrRmLoc and
			SYyMm= convert(int,convert(varchar(6),Fgdt,112)))

		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd= SRmCd 
			and Ins.FrLotNo= SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt=SRmCrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty=SRmDrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt=SRmDrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrFrRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrFrRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm)
		from Inserted Join Fg on FgPrtKey=Inserted.FrPrtKey and FgCoCd= Inserted.FrCoCd and FgTc= Inserted.FrTc and FgYy= Inserted.FrYy 
			and FgChr= Inserted.FrChr and FgNo= Inserted.FrNo 
			where Inserted.FrPrtKey=SPrtKey and Inserted.FrCoCd= SCoCd and Inserted.FrRmCd= SRmCd and Inserted.FrLotNo= SLotNo 
			and Inserted.FrRmSz= SRmSz and Inserted.FrRmSz2= SRmSz2 and Inserted.FrRmSz3= SRmSz3 and Inserted.FrRmStkRt= SRmStkRt and Inserted.FrFrRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Inserted.FrFrRmDc='D'  or Inserted.FrFrRmDc='C')
	End

	/*** Update SYyMm from FrToRmLoc ***/
	if @mode in ('C','D')
	Begin
		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty- (select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt= SRmCrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'C' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty= SRmDrQty-(select isnull(sum(Del.FrRmQty), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc= 'D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt= SRmDrWt-(select isnull(sum(Del.FrRmWt), 0) from Deleted Del 
			Join Fg on FgPrtKey=Del.FrPrtKey and FgCoCd= Del.FrCoCd and FgTc= Del.FrTc and FgYy= Del.FrYy and FgChr= Del.FrChr 
			and FgNo= Del.FrNo where Del.FrToRmDc='D' and Del.FrPrtKey=SPrtKey and Del.FrCoCd= SCoCd and Del.FrRmCd=SRmCd 
			and Del.FrLotNo=SLotNo and Del.FrRmSz=SRmSz and Del.FrRmSz2=SRmSz2 and Del.FrRmSz3=SRmSz3 and Del.FrRmStkRt=SRmStkRt and Del.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm) 
		from Deleted Join Fg on FgPrtKey=Deleted.FrPrtKey and FgCoCd= Deleted.FrCoCd and FgTc= Deleted.FrTc and 
			FgYy= Deleted.FrYy and FgChr= Deleted.FrChr and FgNo= Deleted.FrNo 
			Where Deleted.FrPrtKey=SPrtKey and Deleted.FrCoCd= SCoCd and Deleted.FrRmCd= SRmCd and Deleted.FrLotNo= SLotNo 
			and Deleted.FrRmSz= SRmSz and Deleted.FrRmSz2= SRmSz2 and Deleted.FrRmSz3= SRmSz3 and Deleted.FrRmStkRt= SRmStkRt and Deleted.FrToRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and (Deleted.FrToRmDc='D'  or Deleted.FrToRmDc='C')
	End

	if @mode in ('A','C')
	Begin
		/* Current Partition */
		insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmSz2,SRmSz3,SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt) 
			select distinct FrPrtKey,FrCoCd,FrRmCd,FrLotNo,FrRmSz,FrRmSz2,FrRmSz3,FrRmStkRt,FrToRmLoc,convert(int,convert(varchar(6),Fgdt,112)),0,0,0,0
			from inserted join Fg on FgPrtKey=FrPrtKey and FgCoCd= FrCoCd and FgTc=FrTc and FgYy=FrYy and FgChr=FrChr and FgNo=FrNo
			where not exists(select 'x' from  SYyMm where SPrtKey=FrPrtKey and SCoCd= FrCoCd and SRmCd=FrRmCd and 
			SLotNo=FrLotNo and SRmSZ= FrRmSz and SRmSZ2= FrRmSz2 and SRmSZ3= FrRmSz3 and SRmStkRt=FrRmStkRt and SLoc=FrToRmLoc and
			SYyMm= convert(int,convert(varchar(6),Fgdt,112)))

		/* Current Partition */
		update SYyMm set
		SRmCrQty= SRmCrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmCrWt=SRmCrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'C' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrQty=SRmDrQty+(select isnull(sum(Ins.FrRmQty), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'D' and Ins.FrPrtKey=SPrtKey and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm),
		SRmDrWt=SRmDrWt+(select isnull(sum(Ins.FrRmWt), 0) from Inserted Ins 
			Join Fg on FgPrtKey=Ins.FrPrtKey and FgCoCd= Ins.FrCoCd and FgTc= Ins.FrTc and FgYy= Ins.FrYy and FgChr= Ins.FrChr 
			and FgNo= Ins.FrNo where Ins.FrToRmDc= 'D' and Ins.FrPRtKey=SPrtKEy and Ins.FrCoCd= SCoCd and Ins.FrRmCd=SRmCd 
			and Ins.FrLotNo=SLotNo and Ins.FrRmSz=SRmSz and Ins.FrRmSz2=SRmSz2 and Ins.FrRmSz3=SRmSz3 and Ins.FrRmStkRt=SRmStkRt and Ins.FrToRmLoc=SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))= SYyMm)
		from Inserted Join Fg on FgPrtKey=Inserted.FrPrtKey and FgCoCd= Inserted.FrCoCd and FgTc= Inserted.FrTc and FgYy= Inserted.FrYy 
			and FgChr= Inserted.FrChr and FgNo= Inserted.FrNo 
			where Inserted.FrPrtKey=SPrtKey and Inserted.FrCoCd= SCoCd and Inserted.FrRmCd= SRmCd and Inserted.FrLotNo= SLotNo 
			and Inserted.FrRmSz= SRmSz and Inserted.FrRmSz2= SRmSz2 and Inserted.FrRmSz3= SRmSz3 and Inserted.FrRmStkRt= SRmStkRt and Inserted.FrToRmLoc= SLoc 
			and convert(int,convert(varchar(6),Fgdt,112))=SYyMm
			and  (Inserted.FrToRmDc='D'  or Inserted.FrToRmDc='C')
	End
Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
END

GOGO

ALTER TRIGGER [Fm_INUPDL] ON [Fm] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)
	Declare @wEntTyp Varchar(8)
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 

	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Fm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FmPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		/* Current Partition */
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where FmPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 

		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where FmPrtKEy=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	/******** Only One TcTyp records can be Inserted at a time ********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FmTc and PScd= '' Where FmPrtKEy=@wCurrPrtn
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
	  	GoTo ErrHndlr
	END
	
	/******** Only One TcTyp records can be Deleted at a time *********/
	/* Current Partition */
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp= 'TC' and PMcd= FmTc and PSCd= '' Where FmPrtKEy=@wCurrPrtn
	If @Row> 1
	BEGIN
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
		GoTo ErrHndlr
	END
	
	/*** Storing Tc Type In The Variable @wTcTyp ***/
	/* Current Partition */
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FmTc and PSCd= ''
	end
	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FmTc and PSCd= ''
	end

	if @wTcTyp<> 'FM'
	Begin
		Select @ErrMsg= 'Transactions Type Should Be ''FM'' '
		GoTo ErrHndlr
	End

	/*** Storing Entry Type In The Variable @wEntTyp ***/
	select @wEntTyp= PValue1 from Param  where PTyp= 'TCTYP' and PMCd= @wTcTyp and PSCd= ''
	if @mode in ('A','C')
	Begin

		/*****4.1.2********/	
			Select @Row=Count('x') From Inserted ins where 
				(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=FmCoCd)='Y' and
				(@Mode='A' or (@Mode='C' and  ins.FmDt<>IsNull((Select FmDt From Deleted del where 
										ins.FmPrtKey=del.FmPrtKey and ins.FmIdNo=del.FmIdNo 
										and ins.FmCoCd= del.FmCoCd and ins.FmTc=ins.FmTc and  ins.FmYy= del.FmYy 
											and ins.FmChr= del.FmChr and ins.FmNo= del.FmNo),ins.FmDt))) and  
								 exists(Select 'x' From DtTbl Where DtTag='HOL' and FmDt=DtDt and DtHolYN='Y')
			If @Row> 0
			begin  
				select @errmsg= 'Cannot Add Voucher on Holidays.'  
				goto ErrHndlr  
			end  
				
		/********** EntTyp Should Be 'FmMvm' (Check In Param) ********/
		/* Current Partition */
		select @row=count('x') from inserted join Param p1 on
			p1.PTyp= 'TC' and p1.PMCd= FmTc and p1.PSCd= ''
			where FmPrtKey=@wCurrPrtn and IsNull((select p2.PValue1 from Param p2 where p2.PTyp='TCTYP'
						and p2.PMcd= p1.PValue and p2.PSCd= ''
		        		   ), '') <> 'FGMVM'
		if @row> 0
		Begin
			Select @ErrMsg= 'Transactions Of Only ''FmMvm'' Type Permitted'
			GoTo ErrHndlr
		end

		/******  FmCoCd = HCoCd   *******/
		/* Current Partition */
		select @row= count('x') from inserted where FmPrtKey=@wCurrPrtn and not exists (select 'x' from Head where HCoCd= FmCoCd and HCd= @wHCd)
		if @row> 0
		begin
			select @errMsg= 'Company Code Not Valid'
			goto ErrHndlr
		end

		/******  FmYy  =  PMCd ('YY')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FmPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='YY' and PMCd= FmYy)
		if @row> 0
		begin
			select @errmsg= 'Voucher Year Not Defined'
			goto ErrHndlr
		end
	
		/******  FmChr  =  PSCd ('CHR', FmTc)  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FmPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= FmCoCd and
					vPTyp= 'CHR' and vPMCd= FmTc and vPSCd= FmChr)
		if @row> 0
		begin
			select @errmsg= 'Voucher Character Not Defined'
			goto ErrHndlr
		end

		/******  FmNo  <>  0  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FmPrtKey=@wCurrPrtn and FmNo<= 0
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Cannot Be Zero'
			goto ErrHndlr
		end

		/****** Voucher Date Cannot Be Blank ******/
		/* Current Partition */
		select @Row= Count('x') from Inserted where FmPrtKey=@wCurrPrtn and FmDt in('01/01/1980', '01/01/1900')
		If @Row > 0
		begin
			Select @ErrMsg= 'Date Cannot Be Blank'
			GoTo ErrHndlr
		end
	End

	If @Mode = 'C'
	Begin
		/*******Cannot Change Key values ********/
		/* Current Partition */
		select @Row=Count('x') from Deleted Del where Del.FmPrtKey=@wCurrPRtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.FmPrtKey=@wCurrPrtn and
					Ins.FmCoCd= Del.FmCoCd and Ins.FmTc= Del.FmTc
					and Ins.FmYy=Del.FmYy and Ins.FmChr= Del.FmChr
					and Ins.FmNo=Del.FmNo)
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Change Voucher No'
			GoTo ErrHndlr
		end

		/******* Cannot Change Date if Fmd records exist *******/
		/* Current Partition */
		select @row= count('x') from deleted Del where del.FmPrtKEy=@wCurrPRtn and
		 	Not Exists (Select 'x' from Inserted Ins where Ins.FmPrtKey=Del.FmPrtKey and
				Ins.FmCoCd= Del.FmCoCd and Ins.FmTc= Del.FmTc
				and Ins.FmYy= Del.FmYy and Ins.FmChr= Del.FmChr
				and Ins.FmNo= Del.FmNo and Ins.FmDt= Del.FmDt)
			and
			Exists (Select 'x' from Fmd where Del.FmPRtKEy=FmdPrtKey and Del.FmCoCd= FmdCoCd and
				Del.FmTc= FmdTc and Del.FmYy= FmdYy and
				Del.FmChr= FmdChr and Del.FmNo= FmdNo)
		if @row> 0
		begin
			select @errmsg= 'Cannot Change Date As Child Records Exist'
			goto ErrHndlr
		end
	End
	if @mode in ('D')
	Begin
		/****** Cannot Delete If Child Exists ******/
		/* Current Partition */
		select @row= count('x') from deleted, Fmd where FmPrtKey=@wCurrPrtn and FmPrtKey=FmdPrtKey and FmCoCd= FmdCoCd and FmTc= FmdTc
				and FmYy= FmdYy and FmChr= FmdChr and FmNo= FmdNo
		if @row> 0
		begin
			select @errmsg='Cannot Delete As Child Records Exist'
			goto ErrHndlr
		end
	End
Return
ErrHndlr:
	Begin
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	End
END

GOGO

ALTER TRIGGER [Fmd_INUPDL] ON [Fmd] 
       FOR INSERT,UPDATE,DELETE  
	NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)	
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Fmd' )  
	RETURN  
	  
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
		else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
		end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	begin
		select @wTcTyp= max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FmdTc and PSCd=''
	end
	if @mode in ('D')
	begin
		select @wTcTyp= max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FmdTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FmdPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FmdPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FmdPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where FmdPrtKey=@wCurrPrtn and 
		Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmdCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where FmdPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmdCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('C')
		Begin 
			/* Current Partition */
			Select @Row= Count('x') from Deleted where FmdPrtKey=@wCurrPrtn and
			     	not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
			     	and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     	and BLoc = 'PFG')
			If @Row> 0
			Begin
				Select @ErrMsg= 'Cannot Change As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
			End
		End
	
		if @mode= 'A'
		Begin
			/**** If @mode= 'A' then Valid Bag, BCls= 'N', BLoc= 'PFG' ****/
			/* Current Partition */
			select @Row= Count('x') from inserted
				where FmdPRtKEy=@wCurrPrtn and not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
					and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
					and BLoc = 'PFG'
					and FmdFdYy = (Select max(FdYy) from Fgd where FdPRtKey=FmdPrtKey and FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo)
					and FmdFdKey = (Select max(FdKey) from Fgd where FdPrtKey=FmdPrtKey and FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo
						and FdYy = FmdFdYy))
			If @Row> 0
			begin
				Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Not In FG'
				GoTo ErrHndlr
			end
		End
	
		/*** Update the current FgSubLoc(BFgSubLoc) of the bag based on the value
		FmdToFgSubLoc of the Fmd table record which is inserted ***/
		/* Current Partition */
		update Bag set
		BFgSubLoc= IsNull((select ins1.FmdToFgSubLoc from inserted ins1 where
			    	Ins1.FmdPrtKey=Ins.FmdPrtKey and ins1.FmdCoCd= ins.FmdCoCd and ins1.FmdBYy= ins.FmdBYy
				and ins1.FmdBChr= ins.FmdBChr and ins1.FmdBNo= ins.FmdBNo
				and ins1.FmdYy= (Select max(ins2.FmdYy) from inserted ins2
							where ins2.FmdPrtKey=ins1.FmdPrtKey and ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo)
				and ins1.FmdKey= (Select max(ins2.FmdKey) from inserted ins2
							where ins2.FmdPrtKey=ins1.FmdPrtKey and ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo
							and ins2.FmdYy= ins1.FmdYy)
				), '')
		From inserted ins where BPrtKey=ins.FmdPrtKey and BCoCd= ins.FmdCoCd and BYy= ins.FmdBYy
			and BChr= ins.FmdBChr and BNo= ins.FmdBNo
	
	
		if @mode in ('D') and @wTcTyp in ('FM')
		Begin
			/* Current Partition */
			select @Row= Count('x') from Deleted where FmdPrtKey=@wCurrPRtn and FmdBNo<> 0 and
				     not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
				     and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
				     and BLoc= 'PFG')
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Delete As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
				end
	
			/* Current Partition */
			update Bag set
			BFgSubLoc= IsNull((select del1.FmdFrFgSubLoc from deleted del1 where
				    	del1.FmdPrtKey=del.FmdPrtKey and del1.FmdCoCd= del.FmdCoCd and del1.FmdBYy= del.FmdBYy
					and del1.FmdBChr= del.FmdBChr and del1.FmdBNo= del.FmdBNo
					and del1.FmdYy= (Select min(del2.FmdYy) from deleted del2
								where del2.FmdPrtKey=del1.FmdPrtKey and del2.FmdCoCd= del1.FmdCoCd
								and del2.FmdBYy= del1.FmdBYy
								and del2.FmdBChr= del1.FmdBChr
								and del2.FmdBNo= del1.FmdBNo)
					and del1.FmdKey= (Select min(del2.FmdKey) from deleted del2
								where del2.FmdPrtKey=del1.FmdPrtKey and del2.FmdCoCd= del1.FmdCoCd
								and del2.FmdBYy= del1.FmdBYy
								and del2.FmdBChr= del1.FmdBChr
								and del2.FmdBNo= del1.FmdBNo
								and del2.FmdYy= del1.FmdYy)
					), '')
			From deleted del where del.FmdPrtKey=@wCurrPrtn and BPrtKey=del.FmdPrtKey and BCoCd= del.FmdCoCd and BYy= del.FmdBYy
				and BChr= del.FmdBChr and BNo= del.FmdBNo
	
		End 

	End


	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FmdTc and PSCd= '' Where FmdPRtKEy=@wCurrPrtn 
	If @Row> 1
	begin
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
	  	GoTo ErrHndlr
	end

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp= 'TC' and PMcd= FmdTc and PSCd='' Where FmdPrtKey=@wCurrPrtn 
	If @Row> 1
	begin
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
		GoTo ErrHndlr
	end

	if @mode in ('A', 'C')
	Begin
		/******* Valid FmdTc,FmdYy,FmdChr, FmdNo combination ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and
  			Not Exists (Select 'x' From Fm Where FmPrtKey=Ins.FmdPrtKey and FmCoCd=Ins.FmdCoCd
				And FmTc= Ins.FmdTc And FmYy= Ins.FmdYy
				And FmChr= Ins.FmdChr And FmNo= Ins.FmdNo)
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'Voucher No. Does Not Exist'
       			GoTo ErrHndlr
  		end

		/***** FdSr <> 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKey=@wCurrPrtn and FmdSr<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Sr. Cannot be 0'
		  	GoTo ErrHndlr
		end

		/***** FdKey > 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKEy=@wCurrPrtn and FmdKey<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Key Cannot be <= 0'
		  	GoTo ErrHndlr
		end

		/***** FdBNo > 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKEy=@wCurrPrtn and FmdBNo<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Bag No. Cannot be <= 0'
		  	GoTo ErrHndlr
		end

		/* Emr 211 (FmdCoCd, FmdYy, FmdKey Key comb shld be unique) */
		/* Current Partition */
		select @row= count('x') from inserted ins where ins.FmdPrtKey=@wCurrPrtn and
			(Select count('x') from Fmd Fd where Fd.FmdPrtKey=ins.FmdPrtKey and Fd.FmdCoCd= ins.FmdCoCd and Fd.FmdYy= ins.FmdYy and
				Fd.FmdKey= ins.FmdKey)> 1
	  	if @row> 0
  		begin
   			select @errmsg= 'FmdCoCd-FmdYy-FmdKey Key Combination Should Be Unique'
	   		goto ErrHndlr
  		end
	/* **** Zubin 211 **** */

		/* Flute Bags cannot be Moved in FG */
		/* *** Jay 2.13(CT) *** */
		/* Current Partition */
		select @Row= count('x') from Inserted where FmdPrtKey=@wCurrPrtn and
			Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= FmdBChr and PSCd= '' and PValue<> 'P')
		If @Row> 0
	   	begin
			Select @ErrMsg= 'Only Primary Bags Can Be Moved To FG Sub-Location'
			GoTo ErrHndlr
		end
		/* **** Zubin 211 **** */

		/*** FmdToFgSubLoc  =  vPMCd('FGSUBLOC') ***/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and
  			Not Exists (Select vPMCd From vParam Where vPCoCd= FmdCoCd and
					vPTyp= 'FGSUBLOC' And vPMCd = FmdToFgSubLoc)
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'To Fg Sub Location Not Defined'
       			GoTo ErrHndlr
  		end

		/*** FmdFrFgSubLoc  =  FmdToFgSubLoc ***/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and Ins.FmdFrFgSubLoc = Ins.FmdToFgSubLoc
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'To Fg Sub Location and From Fg Sub Loc cannot be same '
       			GoTo ErrHndlr
  		end
		If @Mode= 'C'
		BEGIN
			/******* If Mode = 'C' then Cannot change Key Values,Bag No ********/
			/* Current Partition */
			select @Row= Count('x') from Deleted Del where Del.FmdPrtKey=@wCurrPrtn and
				 Not Exists (Select 'x' from Inserted Ins where Ins.FmdPrtKey=Del.FmdPrtKey and Ins.FmdCoCd=Del.FmdCoCd
				 and Ins.FmdTc=Del.FmdTc and Ins.Fmdyy=Del.FmdYy and Ins.FmdChr= Del.FmdChr
				 and Ins.FmdNo=Del.FmdNo and Ins.FmdSr=Del.FmdSr and Ins.FmdBYy= Del.FmdBYy
				 and Ins.FmdBChr=Del.FmdBChr and Ins.FmdBNo=Del.FmdBNo and Ins.FmdFrFgSubLoc= Del.FmdFrFgSubLoc
				 and Ins.FmdKey= Del.FmdKey and Ins.FmdFdYy = Del.FmdFdYy and
				 Ins.FmdFdKey = Del.FmdFdKey)
			If @Row > 0
			Begin
				Select @ErrMsg= 'Cannot Change Voucher No./Bag No/Key'
				GoTo ErrHndlr
			End

			/******* Cannot Change If Fwb Transaction Has Taken Place For The Bag After The Movement ******/
			/* Current Partition */
			select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and
			     exists(Select 'x' from Fgd Fgd1 where Fgd1.FdPrtKey=del.FmdPrtKey and Fgd1.FdCoCd= del.FmdCoCd and
				     Fgd1.FdBYy= del.FmdBYy and Fgd1.FdBChr= del.FmdBChr and
				     Fgd1.FdBNo= del.FmdBNo and
				     ((Fgd1.FdYy > del.FmdFdYy)
					or
					(Fgd1.FdYy = del.FmdFdYy and Fgd1.FdKey> del.FmdFdKey))
				)
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Not The Last FG Movement Of The Bag'
				GoTo ErrHndlr
			end

			/******* Cannot Change If this Fg Movement is not the last FG Movement For The Bag ******/
			/* Current Partition */
			select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPRtn and
				exists(Select 'x' from Fmd Fmd1 where Fmd1.FmdPrtKey=del.FmdPrtKey and Fmd1.FmdCoCd= del.FmdCoCd and
				Fmd1.FmdBYy= del.FmdBYy and Fmd1.FmdBChr= del.FmdBChr and
				Fmd1.FmdBNo= del.FmdBNo and
				(	(Fmd1.FmdYy> del.FmdYy)
					or
					(Fmd1.FmdYy= del.FmdYy and Fmd1.FmdKey> del.FmdKey)
				)	)
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Not The Last Fg Movement Of The Bag'
				GoTo ErrHndlr
			end
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
		/*
			select @Row= Count('x') from Deleted where
			     	not exists(select 'x' from Bag where FmdCoCd= BCoCd
			     	and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     	and BLoc = 'PFG')
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
			end
		*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
		END
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
/*		if @mode= 'A'
		Begin
*/			/**** If @mode= 'A' then Valid Bag, BCls= 'N', BLoc= 'PFG' ****/
/*			select @Row= Count('x') from inserted
				where not exists(select 'x' from Bag where FmdCoCd= BCoCd
					and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
					and BLoc = 'PFG'
					and FmdFdYy = (Select max(FdYy) from Fgd where FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo)
					and FmdFdKey = (Select max(FdKey) from Fgd where FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo
						and FdYy = FmdFdYy))
			If @Row> 0
			begin
				Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Not In FG'
				GoTo ErrHndlr
			end
		End
*/
		/*** Update the current FgSubLoc(BFgSubLoc) of the bag based on the value
		FmdToFgSubLoc of the Fmd table record which is inserted ***/
/*		update Bag set
		BFgSubLoc= IsNull((select ins1.FmdToFgSubLoc from inserted ins1 where
			    	ins1.FmdCoCd= ins.FmdCoCd and ins1.FmdBYy= ins.FmdBYy
				and ins1.FmdBChr= ins.FmdBChr and ins1.FmdBNo= ins.FmdBNo
				and ins1.FmdYy= (Select max(ins2.FmdYy) from inserted ins2
							where ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo)
				and ins1.FmdKey= (Select max(ins2.FmdKey) from inserted ins2
							where ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo
							and ins2.FmdYy= ins1.FmdYy)
				), '')
		From inserted ins where BCoCd= ins.FmdCoCd and BYy= ins.FmdBYy
			and BChr= ins.FmdBChr and BNo= ins.FmdBNo
*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
	End
	/*** UPDATES ***/
	/*** Bag forward update, BFgSubLoc= FmdToFgSubLoc
	     If delete then Reverse FmdToFgLoc to max record in Fmd ****/
	if @mode in ('D') and @wTcTyp in ('FM')
	Begin
		/******* Cannot Delete If Fmd Transaction Has Taken Place For The Bag After
			 The Movement ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and del.FmdBNo<> 0 and
			exists(Select 'x' from Fmd Fmd1 where Fmd1.FmdPrtKey=del.FmdPrtKey and Fmd1.FmdCoCd= del.FmdCoCd and
					Fmd1.FmdBYy= del.FmdBYy and Fmd1.FmdBChr= del.FmdBChr and
					Fmd1.FmdBNo= del.FmdBNo and
					(	(Fmd1.FmdYy> del.FmdYy)
						or
						(Fmd1.FmdYy= del.FmdYy and Fmd1.FmdKey> del.FmdKey)
					)
				)
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Not The Last Fg Movement Of The Bag'
			GoTo ErrHndlr
		end

		/******* Cannot Delete If Fwb Transaction Has Taken Place For The Bag After
			 The Movement ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and del.FmdBNo<> 0 and
			     exists(Select 'x' from Fgd Fgd1 where Fgd1.FdPrtKey=del.FmdPrtKey and Fgd1.FdCoCd= del.FmdCoCd and
				     Fgd1.FdBYy= del.FmdBYy and Fgd1.FdBChr= del.FmdBChr and
				     Fgd1.FdBNo= del.FmdBNo and
				     (	(Fgd1.FdYy> del.FmdFdYy)
						or
					(Fgd1.FdYy= del.FmdFdYy and Fgd1.FdKey> del.FmdFdKey)
				     )
				)
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
/*		select @Row= Count('x') from Deleted where FmdBNo<> 0 and
			     not exists(select 'x' from Bag where FmdCoCd= BCoCd
			     and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     and BLoc= 'PFG')
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Bag Is Closed Or Bag Not In PFG'
			GoTo ErrHndlr
			end
*/
/*		update Bag set
		BFgSubLoc= IsNull((select del1.FmdFrFgSubLoc from deleted del1 where
			    	del1.FmdCoCd= del.FmdCoCd and del1.FmdBYy= del.FmdBYy
				and del1.FmdBChr= del.FmdBChr and del1.FmdBNo= del.FmdBNo
				and del1.FmdYy= (Select min(del2.FmdYy) from deleted del2
							where del2.FmdCoCd= del1.FmdCoCd
							and del2.FmdBYy= del1.FmdBYy
							and del2.FmdBChr= del1.FmdBChr
							and del2.FmdBNo= del1.FmdBNo)
				and del1.FmdKey= (Select min(del2.FmdKey) from deleted del2
							where del2.FmdCoCd= del1.FmdCoCd
							and del2.FmdBYy= del1.FmdBYy
							and del2.FmdBChr= del1.FmdBChr
							and del2.FmdBNo= del1.FmdBNo
							and del2.FmdYy= del1.FmdYy)
				), '')
		From deleted del where BCoCd= del.FmdCoCd and BYy= del.FmdBYy
			and BChr= del.FmdBChr and BNo= del.FmdBNo
*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
	End
Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
END

GOGO

ALTER TRIGGER [Head_INUPDL] ON [Head]
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	/* *** Trigger Version 3.11.0 *** */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ReplAgt BIT
	
	set @wSelfCoCd= 'ZZZ'
	set @wSelfCd = 'ZSELF'	

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Head')
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	If @mode in ('A' , 'C')
	Begin
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN and HDTPrdPtr= ins.HDTPrdPtr added) */ 
		/*** introduced hLooseInv (Jen 2.12 Patch 3)***/
		/*** introduced HConsolidatedInv, HAutomateReturns (Jen 2.13)***/
		/****** Sachin 2.13.0 - introduced HQWModYN And HModAvlYN ******/ 
		/****** Sachin 2.14.0 - introduced HImpComLoc ******/ 
		/* Zubin 213 (HMultiCurYn added) */ 
		/* *** JAY 2.13(CT) *** (hCompBagsYn ADDED)*/
		/* *** Jay 2.14(LclInv) *** [HLclInvYn]*/
		/* *** Jay 3.01 *** [FgTag Module] */
		/*** (Jen 3.1.0_1 added HInInvGrsWtEqActual) ***/
		/*** Jay 3.1.0_1 [HValidDsgSetCd] ***/ 
		/****** Jen (3.1.2) added hBestUse ******/
		/****** Manali 3.03 added HPdModYN */
		/****** Sachin 3.3.0 (30-06-08) - [hChkVldRmLnYN added for 28. Valid RmSz Master] */
		/*** Jay 3.3(FG) [hFgIOYn] ***/
		/***** Manali 3.4.1 - 22/10/08 - Design Catalogue Module [added HDsgCatYN] *****/
		/* **** Manali 3.5.0 -  hCustomizeRmCtgExp, HMaxDsgViewRec added */
		/* **** Manali 3.6.0 - HOrdExcelRepYn added */
		/* **** Manali 3.9.1 - RfId Module ****/
		/* **** Manali 3.10.0 - Multi Price Quotation Module */
        /* 4.1.4 */
		Update Head 
		Set hCmFixPrc= ins.hCmFixPrc, hCmGldAs= ins.hCmGldAs, hCmLabAs=ins.hCmLabAs, 
			hCmIWtEqOrd = ins.hCmIWtEqOrd, hCmIWtFrOrd= ins.hCmIWtFrOrd, 
			hCmIGldRtEqOrd= ins.hCmIGldRtEqOrd, hCmDiaRtFA= ins.hCmDiaRtFA, 
			hCmCsRtFA= ins.hCmCsRtFA, HPtrYn= ins.HPtrYn, 
			hPPCYN= ins.hPPCYN, HPDCSfx= ins.HPDCSfx,
			HRndOrdSalPrc= ins.HRndOrdSalPrc, HShowPrdRmDets= ins.HShowPrdRmDets, 
			HCtbMod= ins.HCtbMod, hFluteBagYN= ins.hFluteBagYN, 
			HDTPrdPtr= ins.HDTPrdPtr, HSlvModYN = ins.HSlvModYN, HPdModYN = ins.HPdModYN,
			hLooseInv= ins.hLooseInv, hConsolidatedInv= ins.hConsolidatedInv, 
			HAutomateReturns= ins.HAutomateReturns, HQWModYN = Ins.HQWModYN, 
			HModAvlYN = Ins.HModAvlYN, HMultiCurYn= Ins.HMultiCurYn, hCompBagsYn= Ins.hCompBagsYn,
			HImpComLoc = Ins.HImpComLoc, HInRepMetLsRmCd= Ins.HInRepMetLsRmCd, HLclInvYn= Ins.HLclInvYn,
			HFgTagMod = Ins.HFgTagMod, HCustomiseOrd= Ins.HCustomiseOrd, HAutoCustmMtch= Ins.HAutoCustmMtch, 
			HInInvGrsWtEqActual= Ins.HInInvGrsWtEqActual, HValidDsgSetCd = Ins.HValidDsgSetCd, 
			hBestUse= Ins.hBestUse, hChkVldRmLnYN= Ins.hChkVldRmLnYN , HExcelImpInOrdYN=Ins.HExcelImpInOrdYN,
			HTravelExlYN=Ins.HTravelExlYN,hFgIOYn= Ins.hFgIOYn, HDsgCatYN= Ins.HDsgCatYN, 
			hCustomizeRmCtgExp=Ins.hCustomizeRmCtgExp, HMaxDsgViewRec=ins.HMaxDsgViewRec, HOrdExcelRepYn=Ins.HOrdExcelRepYn,
			HRfIdMod=ins.HRfIdMod, HMultiPrcQtMod=ins.HMultiPrcQtMod, hRtfrRtChrtYN=ins.hRtfrRtChrtYN,
