				  else 0 end), 
			InTot= InFOB- IsNull((Select sum(del.IdiFOB) from deleted del where del.IdCoCd= InCoCd and del.IdTc= InTc and del.IdYy= InYy 
				and del.IdChr= InChr and del.IdNo= InNo), 0) + 
				(case InTotAs when 'FOB' then 0 when 'CIF' then InComm+ InFrt+ InIns 
					        when 'C&F' then InComm+ InFrt when 'C&I' then InComm+ InIns else 0 end), 
			InTotRs= (case when @wTcTyp= 'IN' 
				  then Round(Round(((InFOB- IsNull((Select sum(del.IdiFOB) 
