					from deleted del left outer join inserted ins on ins.IdCoCd= del.IdCoCd 
						and ins.IdTc= del.IdTc and ins.IdYy= del.IdYy and ins.IdChr= del.IdChr 
						and ins.IdNo= del.IdNo and ins.IdSr= del.IdSr 
					where del.IdCoCd= InCoCd and del.IdTc= InTc 
					and del.IdYy= InYy and del.IdChr= InChr and del.IdNo= InNo), 0)) 
					* (case when InRsMulDiv= 'M' then inCnvRt else 1 end) 
					/ (case when InRsMulDiv= 'D' then inCnvRt else 1 end) ) 
				  else 0 end), 
			InTot= InFOB+ IsNull((Select sum(IsNull(ins.IdiFOB, 0))- sum(del.IdiFOB) from deleted del 
