			  @wInLclCstRs= convert (decimal (16, 2), (Case when @wTcTyp= 'IN' and InLclInvYn = 'Y' then 
								  ((@wInFOB * (1 + (InCmOctroiPer/100 ))+InLclOthrValRs)* (InHCstPer /100 )) else 0 end)),
			  InLclOctroiRs= @wInLclOctroiRs, 
