		 If @mode='D' or (@mode='C' and (update(IdQty)))
     Begin  
			  update OrdDsg set
			  OdExpQty= OdExpQty- IsNull((Select sum(del.IdQty) from deleted del where 
				   @wTcTyp= 'IN' and del.IdPrtKey=OdPrtKey and  del.IdCoCd= OdCoCd and del.IdExpOdTc= OdTc 
				  and del.IdExpOdYy= OdYy and del.IdExpOdChr= OdChr 
				  and del.IdExpOdNo= OdNo and del.IdExpOdSr= OdSr), 0)
			  from deleted where IdPrtKey=@wCurrPrtn and @wTcTyp= 'IN' and OdCoCd= IdCoCd and OdTc= IdExpOdTc 
				  and OdYy= IdExpOdYy and OdChr= IdExpOdChr and OdNo= IdExpOdNo 
				  and OdSr= IdExpOdSr
  	
			  /*** 2.12 (Jen) ***/
