			InFOB= InFOB+ IsNull((Select sum(ins.IdiFOB)- sum(IsNull(del.IdiFOB, 0)) from inserted ins 
				left outer join deleted del on del.IdCoCd= ins.IdCoCd 
					and del.IdTc= ins.IdTc and del.IdYy= ins.IdYy and del.IdChr= ins.IdChr 
					and del.IdNo= ins.IdNo and del.IdSr= ins.IdSr 
				where ins.IdCoCd= InCoCd and ins.IdTc= InTc and ins.IdYy= InYy 
				and ins.IdChr= InChr and ins.IdNo= InNo), 0), 
			InFOBRs= (case when @wTcTyp= 'IN' 
				  then convert (decimal (16, 0), (InFOB+ IsNull((Select sum(ins.IdiFOB)- sum(IsNull(del.IdiFOB, 0)) 
					from inserted ins 
					left outer join deleted del on del.IdCoCd= ins.IdCoCd 
						and del.IdTc= ins.IdTc and del.IdYy= ins.IdYy and del.IdChr= ins.IdChr 
						and del.IdNo= ins.IdNo and del.IdSr= ins.IdSr 
					where ins.IdCoCd= InCoCd 
					and ins.IdTc= InTc and ins.IdYy= InYy and ins.IdChr= InChr 
					and ins.IdNo= InNo), 0))* (case when InRsMulDiv= 'M' then inCnvRt else 1 end)
								/ (case when InRsMulDiv= 'D' then inCnvRt else 1 end))
				  else 0 end), 
			InTot= InFOB+ IsNull((Select sum(ins.IdiFOB)- sum(IsNull(del.IdiFOB, 0)) from inserted ins 
