					and del.IdTc= ins.IdTc and del.IdYy= ins.IdYy and del.IdChr= ins.IdChr 
					and del.IdNo= ins.IdNo and del.IdSr= ins.IdSr 
				where ins.IdCoCd= InCoCd and ins.IdTc= InTc and ins.IdYy= InYy 
				and ins.IdChr= InChr and ins.IdNo= InNo), 0) + 
				(case InTotAs when 'FOB' then 0 when 'CIF' then InComm+ InFrt+ InIns 
				        when 'C&F' then InComm+ InFrt when 'C&I' then InComm+ InIns else 0 end), 
			InTotRs= (case when @wTcTyp= 'IN' 
				  then convert(decimal (16, 0), ((InFOB+ IsNull((Select sum(ins.IdiFOB)- sum(IsNull(del.IdiFOB, 0)) 
					from inserted ins 
