	   		Rt.RrSCtg= Rr.RrSCtg and Rt.RrSTWGrp= Rr.RrSTWGrp and 
			Rt.RrCd= Rr.RrCd and Rt.RrDmCtg= Rr.RrDmCtg and Rt.RrDmCd=Rr.RrDmCd and 
			Rt.RrLsCtg= Rr.RrLsCtg and Rt.RrLabMCd= Rr.RrLabMCd
	   		and  ( (Rt.RrFrLn<= Rr.RrFrLn and
	      			Rt.RrToLn>= Rr.RrFrLn)
			    or  	(Rt.RrFrLn<= Rr.RrToLn and
			      	Rt.RrToLn>= Rr.RrToLn)
	    		    or  	(Rr.RrFrLn<= Rt.RrFrLn and
				Rr.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1 ) ) 
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRt '
	  		goto ErrHndlr
	 	end    
	 	
		/************** Deletion not allowed if rec exists in RmRtHist  RrTcTyp='RM'**************/
		select @row=count('x') from deleted  del where RrTcTyp='BS'  and  
		exists(select * from RmRtHist Rh where Rh.RhTcTyp='RM' and 
			Rh.RhCmCtg= del.RrCmCtg and Rh.RhCmCd=del.RrCmCd and Rh.RhCtg=del.RrCtg and 
			Rh.RhSCtg= del.RrSCtg  and  Rh.RhDmCtg=del.RrDmCtg and Rh.RhLabMCd=del.RrLabMCd and 
			Rh.RhLsCtg=del.RrLsCtg and Rh.RhRngSz=del.RrRngSz and Rh.RhSTWGrp=del.RrSTWGrp 
			and Rh.RhXWtPer=del.RrXWtPer and ((RhFrLn>RhToLn) or
	  		(Select count('x') from RmRtHist Rth where Rth.RhTcTyp= Rh.RhTcTyp and Rth.RhYyyymm= Rh.RhYyyyMm and
	   		Rth.RhCmCtg= Rh.RhCmCtg and Rth.RhCmCd= Rh.RhCmCd and 
			Rth.RhCmCurCd= Rh.RhCmCurCd and Rth.RhCtg= Rh.RhCtg and
	   		Rth.RhSCtg= Rh.RhSCtg and Rth.RhSTWGrp= Rh.RhSTWGrp and 
			Rth.RhCd= Rh.RhCd and Rth.RhDmCtg= Rh.RhDmCtg and 
			Rth.RhLsCtg= Rh.RhLsCtg and Rth.RhLabMCd= Rh.RhLabMCd
	   		and  ( (Rth.RhFrLn<= Rh.RhFrLn and
	      			Rth.RhToLn>= Rh.RhFrLn)
			    or  	(Rth.RhFrLn<= Rh.RhToLn and
			      	Rth.RhToLn>= Rh.RhToLn)
	    		    or  	(Rh.RhFrLn<= Rth.RhFrLn and
				Rh.RhToLn>= Rth.RhToLn)
			 )
	  		) > 1 ))
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRtHist '
	  		goto ErrHndlr
	 	end 
	 	
	 	/************** Deletion not allowed if rec exists in LabRt  RrTcTyp='CHN'**************
	 		select @row=count('x') from deleted  del where RrTcTyp='CHN'  and  
		exists(select * from LabRt Lr where Lr.LrMCd = 'CHN' and Lr.LrSCd = 'CHN' and 
			Lr.LrCmCtg = del.RrCmCtg and Lr.LrCmCd = del.RrCmCd )
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in LabRt '
	  		goto ErrHndlr
	 	end  ***/  
	end



	if @SYS= 'XEMR' 
	BEGIN

		/******  RrCmCtg  =  valid PMCd('CMCTG')  ******/
		select @row= count('x') from inserted where RrCmCtg not in ('C', 'P', 'S', 'T')
	 	if @row> 0
	 	Begin
	  		select @errmsg= 'Customer Catagory Should Be Either ''C'', ''P'', ''S'' or ''T'' '
	  		goto ErrHndlr
	 	end

		/******  RrCmCurCd  = if RrCmCd= 'ZSELF' then valid xPMCd from xParam  (where 
							xPTyp= 'CURNCY'  and xPSCd= '') 
				     Else if RrCmCd<> 'ZSELF' then Valid CmCurCd from CustMst (Where 
					CmCtg= RrCmCtg and CmCd= RrCmCd) *****/	
		Select @row= count('x') from inserted where RrTcTyp= 'RM' and 
				(     	(RrCmCd= 'ZSELF' and 
						not Exists(select 'x' from Param where 
						PTyp= 'CURNCY' and PMCd= RrCmCurCd) 
				      	)
				      	Or 
				      	(RrCmCd <> 'ZSELF' and 
						Not exists (select 'x' from CustMst where CmCtg= RrCmCtg 
						and CmCd= RrCmCd and CmCurCd= RrCmCurCd)
					)
				)
	 	if @row> 0
 		Begin
  			select @errmsg= 'Currency Code Not Defined'
	  		goto ErrHndlr
 		end
	
		/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for the same RrTcTyp, RrCmCd, RrCtg, RrSCtg, RrCd, 
			RrDmCtg, RrLabMCd combination)  ******/
/***		select @row= count('x') from inserted ins where 
  			IsNull((Select PValue from Param where PTyp= 'RMSCTG' and 
                	        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and 
	  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and 
   			Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and Rt.RrCmCurCd= ins.RrCmCurCd and 
			Rt.RrCtg= ins.RrCtg and Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
			Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and Rt.RrLsCtg= ins.RrLsCtg and 
			Rt.RrLabMCd= ins.RrLabMCd 
   			and  (    (Rt.RrFrLn<= ins.RrFrLn and
	      			 Rt.RrToLn>= ins.RrFrLn)
			    or  	(Rt.RrFrLn<= ins.RrToLn and
			      	 Rt.RrToLn>= ins.RrToLn)
	    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
				 ins.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1
		if @row> 0
	 	Begin
  			select @errmsg= 'Size Range Already Defined'
  			goto ErrHndlr
	 	end
***/
	END



return
ErrHndlr:
	begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end


GOGO

ALTER TRIGGER [RmRtHist_INUPDL] ON [RmRtHist] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS 
BEGIN 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @ReplAgt BIT  
 	DECLARE @SYS VARCHAR(5)      
	DECLARE @wSelfCd VARCHAR(8)
   
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RmRtHist' ) 
		RETURN 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
 	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')       

	set @wSelfCd = 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	
      
       	/******** YyyyMm > 0 ********/      
	select @row= count('x') from inserted where     
  		(len(convert (varchar(6), RhYyyyMm)) <> 6 or       
   		(substring(convert (varchar(6), RhYyyyMm), 1, 4) not between 1900 and 2099) or       
   		(substring(convert (varchar(6), RhYyyyMm), 5, 2) not between 1 and 12)   )    
	if @row> 0      
  	Begin      
    		select @errmsg= 'Invalid YyyyMm '      
    		goto ErrHndlr      
  	end      
      
 	/******** TcType = 'RM' only ********/      
 	select @row= count('x') from inserted where RhTcTyp <> 'RM'      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Tc Type should be ''RM'' '      
    		goto ErrHndlr      
  	end      
      
 	/****** RmCtg can be 'D' or 'C' only ******/      
 	Select @Row = count('x') from Inserted where RhCtg NOT IN ('D', 'C')      
 	If @Row > 0       
   	begin      
   		Select @ErrMsg = 'RM Category can be ''D'' or ''C'' only '       
    		goto ErrHndlr      
  	end      
      
 	/****** If TcStr records does not exist for an RrTcTyp & RrCtg combination       
     	then do not allow the user to add such a record       
   	P.N.: TsTbl is 'RmRt' since we have not changed the TcStr for RmRtHist ******/      
 	select @row= count('x') from inserted where not exists(Select 'x' from TcStr       
  	where TsTbl= 'RmRt' and TsTyp= RhTcTyp and TsSTyp= RhCtg)      

  	if @row>0      
  	Begin      
    		select @errmsg= 'TcType & RmCtg Combination Not Defined In Tc Structure '      
    		goto ErrHndlr      
  	end      
      
 	/******  RrCmCd  =  valid CmCd from CustMst (CmCtg= RrCmCtg)  ******/      
 	select @row= count('x') from inserted where      
    		not exists (select 'x' from CustMst where CmCtg= RhCmCtg and CmCd= RhCmCd)      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Customer Code/ Price List Customer Not Defined '      
    		goto ErrHndlr      
  	end      
      
 	/******  If TsBlank from TcStr(TsTbl= 'RmRtHist', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSCtg') = 'N'  then  RrSCtg  =  Not Blank  ******/      
 	select @row= count('x') from inserted where RhSCtg = '' and      
    		(Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RhTcTyp       
   		and TsSTyp=RhCtg and TsIdName= 'RrSCtg') = 'N'      
  	
	if @row> 0      
  	Begin      
    		select @errmsg= 'Raw Material Sub Category Cannot Be Blank'      
    		goto ErrHndlr      
  	end      
      
 	/******  RrSCtg  =  Blank  or  PSCd ('RMCTG', RrCtg)  ******/      
 	select @row= count('x') from inserted where RhSCtg <> '' and      
    		not exists (select 'x' from Param where      
         	PTyp= 'RMSCTG' and PMCd= RhCtg and PSCd= RhSCtg)      
  	if @row>0      
  	Begin      
    		select @errmsg= 'Raw Material Sub Category Not Defined'      
    		goto ErrHndlr      
  	end      
      
 	/******  RrCd  =  Blank  or  valid RmCd from RmMst (RmCtg= RrCtg, RmSCtg= RrSCtg)  ******/      
 	select @row= count('x') from inserted where RhCd<> '' and      
    		not exists (select 'x' from RmMst where      
         	RmCtg= RhCtg and RmSCtg= RhSCtg and RmCd= RhCd and RmZ= 'N')      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Raw Material Code Not Defined'      
    		goto ErrHndlr      
  	end      
      
 	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RhTcTyp, TsSTyp= RhCtg,       
    	TsIdName= 'RrCd') = 'N' then RrCd = Not Blank  ******/      
  	select @row= count('x') from inserted where RhCd= '' and      
    		(Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RhTcTyp       
  		and TsSTyp= RhCtg and TsIdName= 'RrCd') = 'N'      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Raw Material Code Cannot Be Blank'      
    		goto ErrHndlr      
  	end      
      
 	/******  RrCmCtg  =  valid PMCd('CMCTG')  ******/      
 	select @row= count('x') from inserted where RhCmCtg not in ('C', 'P')      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Customer Catagory Should Be Either ''C'' or ''P'' '      
    		goto ErrHndlr      
  	end      

	/* Zubin 212 (18/12/05) 'ZVALUE' and 'ZSELF' can be added by Usr Lvl 1 only */ 
	select @row=count('x') from Inserted Ins where (RhCmCd= 'ZVALUE' or RhCmCd= 'ZSELF') and 
		Not Exists (Select 'x' from Param where PTyp= 'USR' and PMCd= Ins.ModUsr and PSCd= '' and PNum= 1) 
	if @row > 0 
 	begin
  		select @errmsg= 'Cannot Add ''ZVALUE'' and ''ZSELF'' Records As User Is Not Authorised To Do So'
  		goto ErrHndlr
 	end 
 	/******  RrToLn   >=   RrfRLn  ******/      
 	select @row= count('x') from inserted  ins where RhToLn < RhFrLn       
  		and not(RhTcTyp = 'RM' and (exists(Select 'x' from RmMst       
   		join Param on PTyp= 'RMSCTG' and PmCd= RmCtg and PSCd= RmSCtg       
   		where RmCtg= RhCtg and RmSCtg= RhSCtg and RmCd= RhCd       
   		and PValue= 'BS') or exists (select 'x' from RmRt Rr where 
       		Rr.RrTcTyp='BS' and Rr.RrCmCtg=ins.RhCmCtg and Rr.RrCmCd=ins.RhCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg=ins.RhCtg and
		Rr.RrSctg=ins.RhSctg and Rr.RrSTWGrp='' and  Rr.RrCd='' and Rr.RrDmCtg='' and 
		Rr.RrLsCtg=''  and  Rr.RrLabMCd='' and  Rr.RrFrLn='' and Rr.RrToLn='' )))      

  	if @row> 0      
  	Begin      
    		select @errmsg= 'From Value Should Be <= Than To Value '      
    		goto ErrHndlr      
  	end      
      
	/*select * from TcStr where TsTbl = 'RmRt' and TsTyp = 'RM' and TsSTyp = 'D' and       
	TsIdName = 'RhToLn'      
	*/      
	/******  If TsBlank from TcStr(TsTbl= 'RmRtHist', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrToLn') = 'N'  then  RrToLn  =  Not Zero  ******/      
 	select @row= count('x') from inserted where RhToLn = 0 and      
    		(Select TsBlank from TcStr where TsTbl= 'RmRt'      
     		and TsTyp= RhTcTyp and TsSTyp= RhCtg and TsIdName='RrToLn') = 'N'      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'To Value Cannot Be Zero '      
    		goto ErrHndlr      
  	end      
      
	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrCstRt') = 'N'  then  RrCstRt  =  Not Blank  ******/      
 	select @row= count('x') from inserted where RhCstRt = 0 and      
    		(Select TsBlank from TcStr where TsTbl='RmRt'      
     		and TsTyp= RhTcTyp and TsSTyp=RhCtg and TsIdName= 'RrCstRt') = 'N'      

  	if @row> 0      
  	Begin      
    		select @errmsg= 'Purchase Rate Cannot Be Zero '      
    		goto ErrHndlr      
  	end      

  	/******  If TsBlank from TcStr(TsTbl= 'RmRtHist', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSalRt') = 'N'  then  RrSalRt  =  Not Blank  ******/      
 	select @row= count('x') from inserted where RhSalRt= 0 and      
    		(Select TsBlank from TcStr where TsTbl= 'RmRt'      
     		and TsTyp= RhTcTyp and TsSTyp= RhCtg and TsIdName= 'RrSalRt') = 'N'      
  	if @row> 0      
  	Begin      
    		select @errmsg= 'Sales Rate Cannot Be Zero '      
    		goto ErrHndlr      
  	end      
      
/* Zubin 213 (Before 213) */
/* 	select @row= count('x') from inserted where @SYS= '' and RhTcTyp= 'RM' and       
  		RhCmCurCd<> 'US$'       
 	if @row> 0       
 	begin      
  		select @errmsg= 'Currency Code Should Be US$ '       
  		goto ErrHndlr      
 	end      
*/
	/* Zubin 213 Curr Cd = valid curr cd from Param where CmCd = 'ZSELF' or 'ZVALUE' 
		     Curr Cd = valid curr cd from CustMst where CmCd <> 'ZSELF' */ 

	Select @row= count('x') from inserted where @SYS= '' and RhTcTyp = 'RM' and 
		(     	((RhCmCd= 'ZSELF' or RhCmCd= 'ZVALUE') and 
				Not Exists(select 'x' from Param where PTyp= 'CURNCY' and PMCd= RhCmCurCd and PSCd= '') 
		      	)
		      	Or 
		      	((RhCmCd <> 'ZSELF' and RhCmCd<> 'ZVALUE') and 
				Not exists (select 'x' from CustMst where CmCtg= RhCmCtg 
					and CmCd= RhCmCd and CmCurCd= RhCmCurCd) 
			)
		)
	if @row> 0 
	begin
		select @errmsg= 'Invalid Currency Code' 
		goto ErrHndlr
	end

	/* NOT REQUIRED */ 
	/* Zubin 213 (if CmCurCd= Base Cur then it's '01/01/80' rec shld exist with other base curr in 
			DtTbl (DtTag= 'CNV')) 
		(if CmCurCd<> Base Cur then it's '01/01/80' rec shld exist with all base curr in DtTbl (DtTag= 'CNV')) */ 
/*	Select @row= count('x') from inserted where @SYS= '' and RhTcTyp = 'RM' and 
		(
		(
			Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= RhCmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and HBaseCurCd<> RhCmCurCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= RhCmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= RhCmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
		)
		OR 
		(
			Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= RhCmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= RhCmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= RhCmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
		)
		)
	if @row>0 
	Begin
		select @errmsg= 'Invalid Currency Code As Record Does Not Exist In Date Table With All Base Currencies'
		goto ErrHndlr
	end
*/
	/**********************Geeta***Emr206**05/04/04****** If 'BS' Record exists for the same 
				Combination then don't check the Size Range******/
 	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for the same RrTcTyp, RrCmCd, RrCtg, RrSCtg, RrCd,       
    	RrDmCtg, RrLabMCd combination)  ******/      

 	select @row= count('x') from inserted ins where      
    		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and      
                         PMCd= RhCtg and PSCd= RhSCtg), '') <> 'BS' and      
		not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
   		Rr.RrCmCtg=ins.RhCmCtg and Rr.RrCmCd= ins.RhCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg= ins.RhCtg and
   		Rr.RrSCtg= ins.RhSCtg and Rr.RrSTWGrp= '' and 
		Rr.RrCd= '' and Rr.RrDmCtg= '' and 
		Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
		and
    		(Select count('x') from RmRtHist Rt where Rt.RhYyyyMm = ins.RhYyyyMm and       
  		Rt.RhTcTyp= ins.RhTcTyp and Rt.RhCmCtg= ins.RhCmCtg and Rt.RhCmCd= ins.RhCmCd and       
		Rt.RhCmCurCd= ins.RhCmCurCd and Rt.RhCtg= ins.RhCtg and Rt.RhSCtg= ins.RhSCtg and 
		Rt.RhSTWGrp= ins.RhSTWGrp and Rt.RhCd= ins.RhCd and Rt.RhDmCtg= ins.RhDmCtg and 
		Rt.RhLsCtg= ins.RhLsCtg and Rt.RhLabMCd= ins.RhLabMCd      
     		and  (    (Rt.RhFrLn<= ins.RhFrLn and      
          			Rt.RhToLn>= ins.RhFrLn)      
      			or   (Rt.RhFrLn<= ins.RhToLn and      
          			Rt.RhToLn>= ins.RhToLn)      
			or   (ins.RhFrLn<= Rt.RhFrLn and      
    				ins.RhToLn>= Rt.RhToLn)      
   		)      
    		) > 1      

	if @row> 0      
  	Begin      
    		select @errmsg= 'Size Range Already Defined '      
    		goto ErrHndlr      
  	end      
      
 	if @SYS= 'XEMR'       
 	BEGIN      
	  	/******  RrCmCurCd  = if RrCmCd= 'ZSELF' then valid xPMCd from xParam  (where       
	       	xPTyp= 'CURNCY'  and xPSCd= '')       
	        Else if RrCmCd<> 'ZSELF' then Valid CmCurCd from CustMst (Where       
	     	CmCtg= RrCmCtg and CmCd= RrCmCd) *****/       
	  	Select @row= count('x') from inserted where RhTcTyp= 'RM' and       
	    		(      (RhCmCd= 'ZSELF' and       
	      				not Exists(select 'x' from Param where       
	      				PTyp= 'CURNCY' and PMCd= RhCmCurCd)       
	        		)      
	           	Or       
	           		(RhCmCd <> 'ZSELF' and       
	      				Not exists (select 'x' from CustMst where CmCtg= RhCmCtg       
	      				and CmCd= RhCmCd and CmCurCd= RhCmCurCd)      
	     			)      
	    		)      
	   	if @row> 0      
	   	Begin      
	     		select @errmsg= 'Currency Code Not Defined '      
	     		goto ErrHndlr      
	   	end      
		/**********************Geeta***Emr206**05/04/04****** If 'BS' Record exists for the same 
		Combination then don't check the Size Range******/
	  	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for the same RrTcTyp, RrCmCd, RrCtg, RrSCtg, RrCd,       
	   	RrDmCtg, RrLabMCd combination)  ******/      
	  	select @row= count('x') from inserted ins where       
	     		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and       
	        		PMCd= RhCtg and PSCd= RhSCtg), '') <> 'BS' and       
			not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
	   		Rr.RrCmCtg=ins.RhCmCtg and Rr.RrCmCd= ins.RhCmCd and 
			Rr.RrCmCurCd='' and Rr.RrCtg= ins.RhCtg and
	   		Rr.RrSCtg= ins.RhSCtg and Rr.RrSTWGrp= '' and 
			Rr.RrCd= '' and Rr.RrDmCtg= '' and 
			Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
			and
	     		(Select count('x') from RmRtHist Rt where Rt.RhYyyyMm = ins.RhYyyyMm and       
	   		Rt.RhTcTyp= ins.RhTcTyp and Rt.RhCmCtg= ins.RhCmCtg and Rt.RhCmCd= ins.RhCmCd and       
	   		Rt.RhCmCurCd= ins.RhCmCurCd and Rt.RhCtg= ins.RhCtg and Rt.RhSCtg= ins.RhSCtg and       
	   		Rt.RhSTWGrp= ins.RhSTWGrp and Rt.RhCd= ins.RhCd and Rt.RhDmCtg= ins.RhDmCtg and       
	   		Rt.RhLsCtg= ins.RhLsCtg and Rt.RhLabMCd= ins.RhLabMCd       
	      		and  (    (Rt.RhFrLn<= ins.RhFrLn and      
	           			Rt.RhToLn>= ins.RhFrLn)      
	       			or   (Rt.RhFrLn<= ins.RhToLn and      
	           			Rt.RhToLn>= ins.RhToLn)      
	           		or   (ins.RhFrLn<= Rt.RhFrLn and      
	     				ins.RhToLn>= Rt.RhToLn)      
	    			)      
	     		) > 1      
	
	  	if @row> 0      
	   	Begin      
	     		select @errmsg= 'Size Range Already Defined '      
	     		goto ErrHndlr      
	   	end      
	END      

	/************** Deletion not allowed if rec exists in OrdMst **************
			-- Ask the level till which recs can be deleted 
			-- ??? Should the check be made till the OrdRm level ***/
 	IF @mode = 'D'
 	Begin
  		Select @Row = count('x') from Deleted where RhTcTyp = 'RM' and 
			Exists (Select 'x' from OrdMst where OmHistYyyyMm = RhYyyyMm and 
			OmHistCmCtg = RhCmCtg and OmHistCmCd = RhCmCd)
  		if @Row>0 
  		begin
   			select @errmsg = 'Cannot Delete record as related record exists in Order/Quotation/PDC/Sketch Quotation '
   			goto ErrHndlr
  		end 
 	END 
      
return      
ErrHndlr:      
 begin      
    select @errmsg='|'+@errmsg      
    raiserror(@errmsg,16,1)      
    rollback transaction      
  end      
end      

GOGO

ALTER TRIGGER [RoleDefinitions_INUPDL] ON [RoleDefinitions]  --with Encryption
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode CHAR(1)
	DECLARE @errmsg VARCHAR(255)
	DECLARE @SYS VARCHAR(5)

	IF @@ROWCOUNT = 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RoleDefinitions' )
		RETURN

	SELECT @mode = 	CASE (SELECT COUNT(1) FROM Inserted)
					WHEN 0 THEN 'D'
	       			ELSE
						CASE (SELECT COUNT(1) FROM Deleted)
						WHEN 0 THEN 'A'
						ELSE 'C'
						END
	       			END

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')

 	IF @mode = 'C'
 	BEGIN
	/******** Key Fields Cannot Be Changed ********/
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.RoleId= del.RoleId)
		IF @row>0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Key Field of This Table'
			GOTO ErrHndlr
		END
	END

 	IF @mode ='D'
 	BEGIN
		/******** Cannot Delete in Use in MenuRoles********/
		SELECT @row = COUNT(1) FROM Deleted  WHERE
			EXISTS (SELECT 1 FROM MenuRoles WHERE UserRoleId=RoleId)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Cannot Delete in Use in MenuRoles Table' 
			GOTO ErrHndlr
		END

	/******** Cannot Delete in Use in UserRole********/
		SELECT @row = COUNT(1) FROM Deleted  del WHERE
			EXISTS (SELECT 1 FROM UserRole ur WHERE ur.RoleId=del.RoleId)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Cannot Delete in Use in UserRole Table' 
			GOTO ErrHndlr
		END
	END
RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END



/****** Object: Trigger dbo.SysDb_INUPDL Script Date: 03/10/05 ******/ 

GOGO

ALTER TRIGGER [SYyMm_INUPDL] ON [SYyMm] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
  
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'SYyMm' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
  	End
	
 return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  

GOGO

ALTER TRIGGER [Tag_INUPDL] ON [Tag] 
       FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  

	/****** Trigger Version - 3.10.0 ******/
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Tag' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		If @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 
 	IF @mode = 'C'
 	BEGIN
		/******** Key Cannot Be Changed ********/
		SELECT @Row = COUNT(1) FROM Deleted Del WHERE
			 NOT EXISTS (SELECT 1 FROM Inserted Ins WHERE
			 	Ins.TgCoCd = Del.TgCoCd AND Ins.TgTc = Del.TgTc AND Ins.TgYy = Del.TgYy AND
				Ins.TgChr = Del.TgChr AND Ins.TgNo = Del.TgNo AND Ins.TgSr = Del.TgSr)
		IF @Row > 0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Key Fields'
			GOTO ErrHndlr
		END

		/******** Tag Code, Tag Level and Tag Average Type can not Change ********/
		/***** Manali 3.10.0 - DsgMst as Source - TgSrcDsg, TgSrcOrd added below *****/
		SELECT @Row = COUNT(1) FROM Deleted Del WHERE
			 NOT EXISTS (SELECT 1 FROM Inserted Ins WHERE
			 	Ins.TgCoCd = Del.TgCoCd AND Ins.TgTc = Del.TgTc AND Ins.TgYy = Del.TgYy AND
				Ins.TgChr = Del.TgChr AND Ins.TgNo = Del.TgNo AND Ins.TgSr = Del.TgSr AND
				Ins.TgCd = Del.TgCd AND Ins.TgLevel = Del.TgLevel AND Ins.TgAvgTyp = Del.TgAvgTyp AND
				Ins.TgWt = Del.TgWt AND Ins.TgPrice = Del.TgPrice AND Ins.TgSrcDsg = Del.TgSrcDsg AND Ins.TgSrcOrd = Del.TgSrcOrd) AND
			EXISTS (SELECT 1 FROM TagData Tgd WHERE
			 	Tgd.TgdCoCd = Del.TgCoCd AND Tgd.TgdTc = Del.TgTc AND Tgd.TgdYy = Del.TgYy AND
				Tgd.TgdChr = Del.TgChr AND Tgd.TgdNo = Del.TgNo AND Tgd.TgdSr = Del.TgSr)
		IF @Row > 0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Tag Fields when Record Exists in TagData'
			GOTO ErrHndlr
		END

		-- 4.1.2.0
    	select @row= count('x') from inserted ins where 
			not exists (select 'x' from deleted del where ins.TgCoCd=del.TgCoCd and ins.TgTc= del.TgTc and ins.TgYy= del.TgYy 
				and ins.TgChr= del.TgChr and ins.TgNo= del.TgNo and ins.TgSr= del.TgSr and ins.TgDt= del.TgDt)
			and exists(Select 'x' from TagData where TgdCoCd= TgCoCd and TgdTc= TgTc 
				and TgdYy= TgYy and TgdChr= TgChr and TgdNo= TgNo) 
		if @row> 0 
		begin
			select @errmsg= 'Tag Date Cannot Be Changed When TagData Rec exists'
			goto ErrHndlr
		end
	END

 	IF @mode in ('A', 'C')
 	BEGIN
		/*** 4.1.2.0 ***/
		select @row= count('x') from inserted where TgDt in('01/01/1980', '01/01/1900')
		if @row> 0 
		begin
			select @errmsg= 'Tag Date Cannot Be Blank'
			goto ErrHndlr
		end
		/*** 4.1.2.0 ***/

		/******** Valid TgTc ********/
		/* Zubin FG TagPrnt */ 
		SELECT @row = COUNT(1) FROM Inserted WHERE 
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'TC' AND PMCd = TgTc AND 
					PValue IN (SELECT PMCd FROM Param WHERE PTyp = 'TCTYP' AND PValue1 IN ('IN', 'FGBAG', 'TAG')))
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Tc not Defined'
			GOTO ErrHndlr
		END
		/* Zubin FG TagPrnt */ 
		/* Zubin (06/12/05) */
		SELECT @row = count('x') FROM Inserted WHERE TgTc IN (SELECT PMCd FROM Param WHERE PTyp = 'TC' AND 
			PMCd = TgTc AND PValue IN (SELECT PMCd FROM Param WHERE PTyp = 'TCTYP' AND PValue1 IN ('TAG'))) 
			and TgSr<> 0 
		IF @row>0 
		BEGIN
			SELECT @errmsg = 'Tag Sr Should Be Zero' 
			GOTO ErrHndlr
		END
		/* Zubin (06/12/05) */

		/******** Valid TgYy ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'YY' AND PMCd = TgYy)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Year not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgChr ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM vParam WHERE vPTyp = 'CHR' AND vPMCd = TgTc AND vPSCd = TgChr)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Character not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgCd ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM TagFmt WHERE TgfCd = TgCd)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Format Code not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgLevel ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'TagLevel' AND PMCd = TgLevel)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Level not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgAvgTyp for TgLevel = 'P' ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'TgAvgTyp' AND PMCd = TgAvgTyp)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Avg Type not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgWt ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'INVAL' AND PMCd = TgWt
				AND PMCD <> 'S')
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Weight Option not Defined'
			GOTO ErrHndlr
		END

		/******** Valid TgPrice ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'INVAL' AND PMCd = TgPrice
				AND PMCD <> 'S')
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Price Option not Defined'
			GOTO ErrHndlr
		END

		/******** MulBy > 0 ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			TgMulBy <= 0
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Tag Multiply By Value Must be Greater Than ''0'' '
			GOTO ErrHndlr
		END
		
		/***** Manali 3.10.0 - DsgMst as Source *****/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'YN' AND PMCd = TgSrcDsg)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Specify Design Master as Source (Y/N)'
			GOTO ErrHndlr
		END
		
		/***** Manali 3.10.0 - OrdRm as Source *****/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'YN' AND PMCd = TgSrcOrd)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Specify Order Rm as Source (Y/N)'
			GOTO ErrHndlr
		END

	END

	IF @mode = 'D'
	BEGIN
		/****** Cannot delete Record WHERE LocTyp = 'B' which is IN use IN Loc Table ******/
		SELECT @row = COUNT(1) FROM Deleted Del WHERE
			EXISTS (SELECT 1 FROM TagData Tgd WHERE
			 	Tgd.TgdCoCd = Del.TgCoCd AND Tgd.TgdTc = Del.TgTc AND Tgd.TgdYy = Del.TgYy AND
				Tgd.TgdChr = Del.TgChr AND Tgd.TgdNo = Del.TgNo AND Tgd.TgdSr = Del.TgSr)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Cannot Delete As Tag IN Use IN TagData Table'
			GOTO ErrHndlr
		END

	END

RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

ALTER TRIGGER [TagData_INUPDL] ON [TagData] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
	DECLARE @SYS VARCHAR(5)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TagData' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgdCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgdCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Key Cannot Be Changed ********/
 	IF @mode = 'C'
 	BEGIN
		SELECT @Row = COUNT(1) FROM Deleted Del WHERE
			 NOT EXISTS (SELECT 1 FROM Inserted Ins WHERE
			 	Ins.TgdCoCd = Del.TgdCoCd AND Ins.TgdTc = Del.TgdTc AND Ins.TgdYy = Del.TgdYy AND
				Ins.TgdChr = Del.TgdChr AND Ins.TgdNo = Del.TgdNo AND
				Ins.TgdSr = Del.TgdSr AND Ins.TgdSrNo = Del.TgdSrNo)
		IF @Row > 0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Key Fields'
			GOTO ErrHndlr
		END
	END

/* Zubin FG TagPrnt */ 
	SELECT @row = COUNT('x') FROM Inserted WHERE
		NOT EXISTS (SELECT 'x' FROM Param WHERE PTyp = 'TC' AND PMCd = TgdTc AND
				PValue IN (SELECT PMCd FROM Param WHERE
					PTyp = 'TCTYP' AND PValue1 IN ('IN', 'FGBAG', 'TAG')))
	IF @row>0
	BEGIN
		SELECT @errmsg = 'Tag Tc Not Defined'
		GOTO ErrHndlr
	END
/* Zubin FG TagPrnt */ 

	/* Zubin (06/12/05) */
	SELECT @row = count('x') FROM Inserted WHERE TgdTc IN (SELECT PMCd FROM Param WHERE PTyp = 'TC' AND 
		PMCd = TgdTc AND PValue IN (SELECT PMCd FROM Param WHERE PTyp = 'TCTYP' AND PValue1 IN ('TAG'))) 
		and TgdSr<> 0 
	IF @row>0
	BEGIN
		SELECT @errmsg = 'Tag Sr. Should Be Zero' 
		GOTO ErrHndlr
	END

	SELECT @row = count('x') FROM Inserted WHERE TgdTc IN (SELECT PMCd FROM Param WHERE PTyp = 'TC' AND 
		PMCd = TgdTc AND PValue IN (SELECT PMCd FROM Param WHERE PTyp = 'TCTYP' AND PValue1 IN ('TAG'))) 
		and TgdIdSr<> 0 
	IF @row>0
	BEGIN
		SELECT @errmsg = 'Id/Fd Sr. Should Be Zero' 
		GOTO ErrHndlr
	END
	/* Zubin (06/12/05) */

	SELECT @row = COUNT('x') FROM Inserted WHERE
		NOT EXISTS (SELECT 'x' FROM Param WHERE
				PTyp = 'YY' AND PMCd = TgdYy)
	IF @row> 0
	BEGIN
		SELECT @errmsg = 'Tag Year Not Defined'
		GOTO ErrHndlr
	END

	SELECT @row = COUNT('x') FROM Inserted WHERE
		NOT EXISTS (SELECT 'x' FROM vParam WHERE
			 vPTyp = 'CHR' AND vPMCd = TgdTc AND vPSCd = TgdChr)
	IF @row> 0
	BEGIN
		SELECT @errmsg = 'Tag Character Not Defined'
		GOTO ErrHndlr
	END

RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

