			GOTO ErrHndlr
		END
	END

	/* *** Jay 3.01 *** */
	SELECT @row=count('x') FROM Inserted WHERE TgfCd in ('DFDMX', 'DFZEB')
	IF @row>0
	BEGIN
		SELECT @errmsg='Cannot Add/ Change As Default Tag Format Code'
		GOTO ErrHndlr
	END
	/* *** Jay 3.01 *** */

	/****** TgfCd  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfCd = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Format Code Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfStartStr  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfStartStr = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Start String Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfDarkness  =  Not Blank  ******/
/*	SELECT @row=count(1) FROM inserted WHERE TgfDarkness = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Darkness String Cannot Be Blank'
		GOTO ErrHndlr
	END
*/	/****** TgfHeat  =  Not Blank  ******/
/*	SELECT @row=count(1) FROM inserted WHERE TgfHeat  = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Heat String Cannot Be Blank'
		GOTO ErrHndlr
	END
*/	/****** TgfQtyStr  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfQtyStr = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Quantity String Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfEndStr  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfEndStr = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag End String Code Cannot Be Blank'
		GOTO ErrHndlr
	END
	IF @mode = 'D'
	BEGIN
		/* *** Jay 3.01 *** */
		SELECT @row=count('x') FROM deleted WHERE TgfCd in ('DFDMX', 'DFZEB')
		IF @row>0
		BEGIN
			SELECT @errmsg='Cannot Delete As Default Tag Format Code'
			GOTO ErrHndlr
		END
		/* *** Jay 3.01 *** */

		/* Zubin 213 (CoCd chk added) */ 
		SELECT @row=count(1) FROM deleted del WHERE
			exists (SELECT 1 FROM TagFmtSr Tfs WHERE Tfs.TgfsCoCd= del.TgfCoCd and Tfs.TgfsCd= del.TgfCd) 
		IF @row>0
		BEGIN
			SELECT @errmsg='Cannot Delete As Tag Format Code In Use In TagFmtSr Table'
			GOTO ErrHndlr
		END
		/* Zubin 213 */ 
		SELECT @row=count('x') FROM deleted WHERE
			exists (SELECT 'x' FROM Tag WHERE TgCoCd= TgfCoCd and TgCd= TgfCd) 
		IF @row>0
		BEGIN
			SELECT @errmsg='Cannot Delete As Tag Format Code In Use In Tag Table'
			GOTO ErrHndlr
		END
	END
RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

ALTER TRIGGER [TagFmtSr_INUPDL] ON [TagFmtSr] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TagFmtSr' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgfsCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TgfsCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End 

 	/******** Key Cannot Be Changed ********/
 	IF @mode = 'C'
 	BEGIN
		SELECT @Row=Count(1) FROM deleted del WHERE
			 not exists (SELECT 1 FROM inserted ins WHERE
					ins.TgfsCoCd = Del.TgfsCocd And ins.TgfsCd= del.TgfsCd
				And ins.TgfsSr = del.TgfsSr)
		IF @Row > 0
		BEGIN
			SELECT @ErrMsg='Cannot Change Tag Format Code / Serial No.'
			GOTO ErrHndlr
		END
	END

	/* *** Jay 3.01 *** */
	SELECT @row=count('x') FROM Inserted WHERE TgfsCd in ('DFDMX', 'DFZEB')
	IF @row>0
	BEGIN
		SELECT @errmsg='Cannot Add/ Change As Default Tag Format Code'
		GOTO ErrHndlr
	END
	/* *** Jay 3.01 *** */

	/****** TgfsCd  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfsCd= ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Format Code Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfsSr  =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfsSr= ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Format Serail No. Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfsSr  Betweeen 1 to 9  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfsSr Not Between 1 And 12
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Format Serail No. should be in betseen 1 to 12'
		GOTO ErrHndlr
	END
	/****** TgfsPrintStr =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfsPrintStr = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Print String Cannot Be Blank'
		GOTO ErrHndlr
	END
	/****** TgfsField =  Not Blank  ******/
	SELECT @row=count(1) FROM inserted WHERE TgfsField = ''
	IF @row>0
	BEGIN
		SELECT @errmsg='Tag Field Cannot Be Blank'
		GOTO ErrHndlr
	END

 	IF @mode = 'D'
 	BEGIN
		/* *** Jay 3.01 *** */
		SELECT @row=count('x') FROM deleted WHERE TgfsCd in ('DFDMX', 'DFZEB')
		IF @row>0
		BEGIN
			SELECT @errmsg='Cannot Change As Default Tag Format Code'
			GOTO ErrHndlr
		END
		/* *** Jay 3.01 *** */
	End
RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

ALTER TRIGGER [TreeDet_INUPDL] ON [TreeDet] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
	Declare @wHCd Varchar(8)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TreeDet' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrdCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrdCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	/******* If Mode = 'C' then Cannot change Key Values **********/
	If @Mode = 'C'
	Begin
		select @Row=Count('x') from Deleted Del where
			 Not Exists (Select 'x' from Inserted Ins where Ins.TrdCoCd=Del.TrdCoCd
					and Ins.TrdYmd=Del.TrdYmd and Ins.TrdChr= Del.TrdChr and Ins.TrdNo=Del.TrdNo
					and Ins.TrdSr=Del.TrdSr )
		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change  Voucher No.'
			GoTo ErrHndlr
		end
	End

	/********* field level Checks ********/
	/********************************/
	/******* Valid TrdCoCd,TrdYmd,TrdChr,TrdNo ********/
	Select @Row=Count('x') From Inserted Ins Where
		Not Exists (Select 'x' From TreeMst Where TrCoCd=Ins.TrdCoCd
			And TrYmd=Ins.TrdYmd And  TrChr=Ins.TrdChr And TrNo=Ins.TrdNo)
  	If @Row>0
 	begin
		Select @ErrMsg='Voucher No. not Defined '
		GoTo ErrHndlr
  	end
	/***** TrdSr <> 0 *****/
	Select @Row=Count('x') From Inserted Ins Where TrdSr=0
	If @Row>0
	BEGIN
	  	Select @ErrMsg='Sr. Cannot be 0'
	  	GoTo ErrHndlr
	END
/*	Select @Row=Count('x') From Inserted Ins Where TrdBagPcs<=0
	If @Row>0
	BEGIN
	  	Select @ErrMsg='Bag Pcs cannot be<= 0'
	  	GoTo ErrHndlr
	END */

	/**************sum(TrdBagPcs)<=	BQty*************************/
/*	select @Row=Count('x') from Inserted ins where
		exists (select TrdCoCd,TrdBYy,TrdBChr,TrdBNo,sum(TrdBagPcs) from TreeDet Td
			where ins.TrdCoCd=Td.TrdCoCd and ins.TrdBYy=Td.TrdBYy and ins.TrdBChr=Td.TrdBChr
					and ins.TrdBNo=Td.TrdBNo
			group by TrdCoCd,TrdBYy,TrdBChr,TrdBNo
			having  sum(TrdBagPcs) >(select BQty from Bag where BCoCd=TrdCoCd and
									BYy=TrdBYy and BChr=TrdBChr and BNo=TrdBNo))
	If @Row>0
	BEGIN
	  	Select @ErrMsg='Bag Pcs cannot be > Bag Quantity '
	  	GoTo ErrHndlr
	END   */

Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
end

GOGO

ALTER TRIGGER [TreeMst_INUPDL] ON [TreeMst] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	/****** Trigger Version - 3.8.0 ******/
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
		
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TreeMst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	if @mode in ('A','C')
	Begin
		/******  TrCoCd = HCoCd   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Head where HCoCd= TrCoCd and HCd= @wHCd)
		if @row>0
		begin
			select @errMsg= 'Invalid Company Code '
			goto ErrHndlr
		end
		select @row= count('x') from inserted where not exists
			(select 'x' from Param where PTyp='TRCHR' and PMCd= TrChr)
		if @row> 0
		begin
			select @errmsg= 'Voucher Character  Not Defined'
			goto ErrHndlr
		end
	  	select @row= count('x') from inserted where TrNo= 0
	  	if @row> 0
  		begin
	   		select @errmsg= 'Voucher Number Cannot Be Zero'
   			goto ErrHndlr
	  	end
		
		
		/*****4.1.2********/	
			Select @Row=Count('x') From Inserted ins where 
				(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=TrCoCd)='Y' and
				(@Mode='A' or (@Mode='C' and  ins.TrDt<>IsNull((Select TrDt From Deleted del where 
										ins.TrCoCd= del.TrCoCd and ins.TrYmd=ins.TrYmd and  
											 ins.TrChr= del.TrChr and ins.TrNo= del.TrNo),ins.TrDt))) and  
								 exists(Select 'x' From DtTbl Where DtTag='HOL' and TrDt=DtDt and DtHolYN='Y')
			If @Row> 0
			begin  
				select @errmsg= 'Cannot Add Voucher on Holidays.'  
				goto ErrHndlr  
			end  


		select @row= count('x') from inserted where not exists
			(select 'x' from RmMst where RmCd=TrRmCd)
		if @row> 0
		begin
			select @errmsg= 'Tree Kt  Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where not exists
			(select 'x' from Param where PTyp='DMCOl' and PMCd= TrCol)
		if @row> 0
		begin
			select @errmsg= 'Tree Color  Not Defined'
			goto ErrHndlr
		end
	  	select @row= count('x') from inserted where  TrDt in('01/01/1980', '01/01/1900')
	  	if @row>0
  		begin
	   		select @errmsg= 'Tree  Date Cannot Be Blank'
   			goto ErrHndlr
	  	end

		/* ******** Manali 3.6.0 - 19/09/09 - - TrNetPcWt added below ******** */
		select @row= count('x') from inserted where  TrCstDt in('01/01/1980', '01/01/1900')
			and (Convert (decimal(10,3),TrFrMetWt)<>0 or Convert (decimal(10,3),TrUsdMetWt)<>0
				or Convert (decimal(10,3),TrRecdMetWt)<>0 or Convert (decimal(10,3),TrCastLoss)<>0
				or Convert (decimal(10,3),TrCutLoss)<>0 or Convert (decimal(10,3),TrScrap)<>0
				or Convert (decimal(10,3),TrStripLoss)<>0 or Convert (decimal(10,3),TrGrsPcWt)<>0
				or  Convert (decimal(10,3),TrGrindLoss)<>0 /*or Convert (decimal(10,3),TrNetPcWt)<>0*/)
		if @row>0
  		begin
	   		select @errmsg= 'Casting date is blank,cannot enter Fresh MetWt/ReUsd MetWt/RecdMetWt/Loss/Gross Pc Wt'	/* Net Pc Wt'*/
   			goto ErrHndlr
	  	end

		/* ******** Manali 3.6.0 - 19/09/09 - TrNetPcWt < 0 ******** */
		/*select @row= count('x') from inserted where Convert (decimal(10,3),TrNetPcWt)< 0
		if @row> 0
		begin
			select @errmsg= 'Net Pc Wt Cannot Be Negative'
			goto ErrHndlr
		end*/

	End
	if @mode in ('C')
	Begin
		/*** Cannot change the Primary Key ***/
		select @Row=Count('x') from deleted del where
			not exists (Select 'x' from inserted ins where ins.TrCoCd= del.TrCoCd
			and ins.TrYmd= del.TrYmd and ins.TrChr= del.TrChr and ins.TrNo= del.TrNo)
  		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Key Field.'
			GoTo ErrHndlr
		end
		select @Row=Count('x') from deleted del where
			not exists (Select 'x' from inserted ins where ins.TrCoCd= del.TrCoCd  and
			 ins.TrYmd= del.TrYmd and ins.TrChr= del.TrChr and ins.TrNo= del.TrNo and ins.TrDt=Del.TrDt)
			and exists( select * from  TreeDet where TrdCoCd=del.TrCocd and TrdYmd=del.Trymd
					  and TrdChr=del.TrChr and TrdNo=del.TrNo )
  		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Voucher Date. Child records exists'
			GoTo ErrHndlr
 		end
	End
	if @mode in ('D')
	Begin
		/*** Cannot Delete Transaction If Child Record Exists (Txnd) ***/
		select @row=count('x') from deleted join TreeDet on TrCoCd= TrdCoCd
			and TrYmd= TrdYmd and TrChr= TrdChr and TrNo= TrdNo
		if @row>0
  		begin
   			select @errmsg='Cannot Delete As Child Record Exists'
   			goto ErrHndlr
  		end
	End
RETURN
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	End
END

GOGO

ALTER TRIGGER [Txn_INUPDL] ON [Txn] 
   FOR INSERT,UPDATE,DELETE
   NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 3.10.0  */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wTcTyp varchar(3)
	DECLARE @wEntTyp varchar(8)
	Declare @wHCd Varchar(8) 
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
		
	IF @@ROWCOUNT=0   RETURN
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Txn' )
	RETURN
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'
	else
		case (select count('x') from deleted) when 0 then 'A' else 'C' end
	end

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.TIdNo=del.TIdNo and ins.TCoCd=del.TCoCd and ins.TTc=del.TTc and
									ins.TYy=del.TYy and ins.TChr=del.TChr and ins.TNo=del.TNo and ins.TPrtKey<>del.TPrtKey) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end

	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where TPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where TPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Partition Key Not required */
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= TTc and PScd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Partition Key Not Required */
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd=TTc and PSCd=''
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted on'
		GoTo ErrHndlr
	END

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= TTc and PSCd=''
	end

	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= TTc and PSCd=''
	end

