			(Select count('x') from Txn T 
				join Param P1 on P1.PTyp= 'TC' and P1.PMCd= T.TTc and P1.PSCd= '' 
 				join Param P2 on P2.PTyp= 'TCTYP' and P2.PMCd= P1.PValue and P2.PSCd= '' 
				where P2.PValue1= @wEntTyp and T.TCoCd= ins.TCoCd and T.TBoeNo= ins.TBoeNo) >1 
	  	if @row>0 
  		begin
	   		select @errmsg= 'This Bill Of Entry Number Already Exists'
   			goto ErrHndlr
	  	end

		/* ****** Sachin 2.13.0 - Multi-Currency ****** */
		/* Current Partition */
	  	select @row= count('x') from Inserted Ins where TPrtKey=@wCurrPrtn and TTc = 'PR'
		 	And Not Exists 
			(Select 'x' from CustMst where CmCtg= 'S' and CmCd= Ins.TSuppCd And CmCurCd=Ins.TCurrCd )
 	  	if @row>0
  		begin
	   		select @errmsg= 'Supplier Currency Code Not Defined / Invalid'
   			goto ErrHndlr
	  	end

		/* Current Partition */
	  	select @row= count('x') from Inserted Ins where TPrtKey=@wCurrPrtn and TTc = 'SA'
		 	And Not Exists 
			(Select 'x' from CustMst where CmCtg= 'C' and CmCd= Ins.TSuppCd And CmCurCd=Ins.TCurrCd )
 	  	if @row>0
  		begin
	   		select @errmsg= 'Customer Currency Code Not Defined / Invalid'
   			goto ErrHndlr
	  	end

		/* Zubin 213 */
		/* Current Partition */
		select @row= count('x') from inserted where @wTcTyp in ('PR', 'TZ') AND TPrtKey=@wCurrPrtn and
			Convert(Decimal(16, 4), TCnvRt)<= 0
		if @row> 0 
		begin
			select @errmsg= 'Currency Conversion Rate Should Be > 0'
			goto ErrHndlr
		end

		/* Zubin 213 */
		/* Current Partition */
		select @row= count('x') from inserted where @wTcTyp in ('PR', 'TZ') AND TPRtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'MULDIV' and PMCd= TMulDiv and PSCd= '')
		if @row> 0 
		begin
			select @errmsg= 'Currency Multiplication Factor Not Defined'
			goto ErrHndlr
		end
		/* ****** Sachin 2.13.0 - Multi-Currency ****** */
	End

	if @mode in ('C')
	Begin
		/* Sachin 2.12 */ 
		/*** Cannot change the Tran Date when Txnd Recs exists ***/
		/* Current Partition */
/*		select @row= count('x') from inserted ins where ins.TPRtKey=@wCurrPrtn and
			not exists (select 'x' from deleted del where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd and ins.TTc= del.TTc 
				and ins.TYy= del.TYy and ins.TChr= del.TChr and ins.TNo= del.TNo and ins.TDt= del.TDt and ins.TPRtKey=del.TPRtKey)
			and exists(Select 'x' from Txnd where TdTIdNo=TIdNo and TdCoCd= TCoCd and TdTc= TTc 
				and TdYy= TYy and TdChr= TChr and TdNo= TNo and TdPrtKey=TPrtKEy) 
		if @row> 0 
		begin
			select @errmsg= 'Txn Date Cannot Be Changed When Txnd Rec exists'
			goto ErrHndlr
		end
*/
		/* Sachin 2.12 */ 

		/*** Cannot change the Primary Key ***/
		/* Current Partition */
		select @Row=Count('x') from deleted del where del.TPrtKEy=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd 
			and ins.TTc= del.TTc and ins.TYy= del.TYy and ins.TChr= del.TChr 
			and ins.TNo= del.TNo and ins.TPrtKey=del.TPrtKey)
  		If @Row > 0
		begin    
			Select @ErrMsg='Cannot Change Voucher No.'
			GoTo ErrHndlr
 		end

		/*** Cannot change Default Bag Loc, RM Fr & To Locs when Txnd Rec exists ***/
		/* Current Partition */
		select @Row=Count('x') from deleted del where del.TPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd and ins.TTc= del.TTc 
			and ins.TYy= del.TYy and ins.TChr= del.TChr and ins.TNo= del.TNo and ins.TPrtKey=del.TPRtKey and ins.TFrBLoc= del.TFrBLoc 
			and ins.TFrRmLoc= del.TFrRmLoc and ins.TToRmLoc= del.TToRmLoc 
			and ins.TTrfQty= del.TTrfQty) and 
			exists (Select 'x' from Txnd where TdTIdNo=del.TIdNo and TdCoCd= del.TCoCd and TdTc= del.TTc 
			and TdYy= del.TYy and TdChr= del.TChr and TdNo= del.TNo and TdPrtKey=del.TPrtKey)
  		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Change Default Bag Loc/ RM Fr-To Loc/ Cross Transfer Qty When Txnd Record Exists'
			GoTo ErrHndlr
 		end

		/******  Cannot change TImpTyp when Child Record Exists ******/ 
/*		select @Row= Count('x') from deleted del where @wEntTyp in ('Tz') and 
			not exists (Select 'x' from inserted ins where ins.TCoCd= del.TCoCd and ins.TTc= del.TTc and ins.TYy= del.TYy 
				    and ins.TChr= del.TChr and ins.TNo= del.TNo and ins.TImpTyp= del.TImpTyp) 
			and exists (Select 'x' from Txndz where TzCoCd= del.TCoCd and TzTc= del.TTc and TzYy= del.TYy 
				    and TzChr= del.TChr and TzNo= del.TNo) 
  		If @Row > 0
		begin    
			Select @ErrMsg= 'Cannot Change Import Type When Child Record Exists'
			GoTo ErrHndlr
 		end
*/
		/******  Cannot change TUseBefDt when Custom Match Records Exist ******/ 
		/* Current Partition */
		select @Row=Count('x') from deleted del where @wEntTyp in ('Tz') and TPRtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd and ins.TTc= del.TTc and ins.TYy= del.TYy 
				    and ins.TChr= del.TChr and ins.TNo= del.TNo and ins.TPrtKey=del.TPrtKEy and ins.TUseBefDt= del.TUseBefDt) 
			and exists (Select 'x' from Txndz where TzTIdNo=del.TIdNo and TzCoCd= del.TCoCd and TzTc= del.TTc and TzYy= del.TYy 
				    and TzChr= del.TChr and TzNo= del.TNo and TzPrtKey=del.TPrtKey and Round(TzRmDespWt, 3)> 0 )
  		If @Row > 0
		begin    
			Select @ErrMsg= 'Cannot Change Use Before Date When Custom Match Record Exists '
			GoTo ErrHndlr
 		end

/* **** Zubin 212 **** */ 
		/* Current Partition */
	  	select @row= count('x') from inserted ins 
			where @wEntTyp= 'TxnRm' and @wTcTyp IN ('PR', 'MV') and TPrtKey=@wCurrPrtn and
				Not Exists (Select 'x' from deleted del where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd and 
					ins.TTc= del.TTc and ins.TYy= del.TYy and ins.TChr= del.TChr and 
					ins.TNo= del.TNo and ins.TPrtKey=del.TPrtKey and ins.TLotNo= del.TLotNo) 
				and Exists (Select 'x' from Txnd where TdTIdNo=TIdNo and TdCoCd= TCoCd and TdTc= TTc and TdYy= TYy and 
					TdChr= TChr and TdNo= TNo and TdPrtKey=TPrtKey) 
	  	if @row>0 
		begin
	   		select @errmsg= 'Cannot Change Lot No. As Child Record Exists'
			goto ErrHndlr
	  	end
/* **** Zubin 212 **** */ 


/* **** Sachin 2.13.0 **** */ 
		/* Current Partition */
	  	select @row= count('x') from inserted ins 
			where @wEntTyp= 'TxnRm' and @wTcTyp IN ('PR', 'MV') and TPrtKey=@wCurrPrtn and
				Not Exists (Select 'x' from deleted del where ins.TIdNo=del.TIdNo and ins.TCoCd= del.TCoCd and 
					ins.TTc= del.TTc and ins.TYy= del.TYy and ins.TChr= del.TChr and 
					ins.TNo= del.TNo and ins.TPrtKey=del.TPrtKey and convert(decimal (16, 4), ins.TCnvRt)= convert(decimal (16, 4), del.TCnvRt)) 
				and Exists (Select 'x' from Txnd where TdTIdNo=TIdNo and TdCoCd= TCoCd and TdTc= TTc and TdYy= TYy and 
					TdChr= TChr and TdNo= TNo and TdPrtKey=TPrtKey) 
	  	if @row>0 
		begin
	   		select @errmsg= 'Cannot Change Conversion Factor As Child Record Exists'
			goto ErrHndlr
	  	end
/* **** Sachin 2.13.0 **** */ 
	End

	-- 4.1.3.0
	if @mode='C' And Update(TDt)
	Begin
		if @wTcTyp ='PR'
			Update Txnd Set TdDt=TDt From Inserted Where TCoCd=TdCoCd And TTc=TdTc And TYy=TdYy And TChr=TdChr And
					TNo=TdNo And TdDt<>TDt
	End

	if @mode in ('D')
	Begin
		/*** Cannot Delete Transaction If Child Record Exists (Txnd) ***/
		/* Current Partition */
		select @row=count('x') from deleted join Txnd on TIdNo=TdTIdNo and TCoCd= TdCoCd and TTc= TdTc 
			and TYy= TdYy and TChr= TdChr and TNo= TdNo and TPrtKey=@wCurrPrtn 
		if @row>0 
  		begin
   			select @errmsg='Cannot Delete Transaction As Child Record Exists'
   			goto ErrHndlr
  		end

		/*** Cannot Delete Transaction If Child Record Exists (TxndZ) ***/
		/* Current Partition */
		select @row=count('x') from deleted join TxndZ on TIdNo=TzTIdNo and TCoCd= TzCoCd and TTc= TzTc and TYy= TzYy and 
			TChr= TzChr and TNo= TzNo and TPrtKey=@wCurrPrtn
		if @row>0 
  		begin
   			select @errmsg='Cannot Delete Purchase Entry As Child Record Exists'
   			goto ErrHndlr
  		end

 	End

RETURN
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction 
 	End
END

GOGO

ALTER TRIGGER [TxndPrd_INUPDL] ON [TxndPrd] 
        FOR INSERT,UPDATE,DELETE  
		NOT FOR REPLICATION
AS  
BEGIN  
	 /* Trigger Version 3.11.0 */
	 DECLARE @ROW INT  
	 DECLARE @mode char(1)  
	 DECLARE @errmsg varchar(255)  
	 DECLARE @ReplAgt BIT  
	 DECLARE @wCurrPrtn VarChar(1)

	IF @@ROWCOUNT=0   RETURN  
  
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TxndPrd' )  
	RETURN  
  
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   

	Select @wCurrPrtn='C'
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TpPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins 
									Where ins.TpIdNo=del.TpIdNo and ins.TpCoCd=del.TpCoCd and ins.TpTc=del.TpTc and
										  ins.TpYy=del.TpYy and ins.TpChr=del.TpChr and ins.TpNo=del.TpNo and 
										  ins.TpSr=del.TpSr and ins.TpSrNo=del.TpSrNo and ins.TpPrtKey<>del.TpPrtKey) 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end

	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TpPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TpPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where  TpPRtKey=@wCurrPrtn and
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TpCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where TpPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TpCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	if @mode in ('A', 'C')
	Begin
		/*** Voucher Sr should Exist In Txnd ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and not exists (select 'x' from Txnd where
			TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
			and TdNo= TpNo and TdSr= TpSr ) /*and TdPrdYN= 'Y'*/
		if @row>0
		begin
			select @errmsg= 'Voucher Sr Not Defined In Txnd' /* /TdPrdYn = 'N' */
			goto ErrHndlr
		end

		/*** TpSrNo > 0  ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSrNo<= 0
		if @row>0
		begin
			select @errmsg= 'Serial Number Cannot Be Zero'
			goto ErrHndlr
		end

		/*** Valid Worker ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpByWrk<> '' and
			not exists (select vPMCd from vParam where vPCoCd = TpCoCd
				and vPTyp= 'WORK' and vPMCd= TpByWrk and vPValidYN='Y')
		if @row>0
		begin
			select @errmsg= 'Worker Code Not Defined'
			goto ErrHndlr
		end

		/*** TdBQty (Txnd) >= 0 ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and not exists (select 'x' from Txnd where
			TdPrtKey=TpPRtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
			and TdNo= TpNo and TdSr= TpSr and TdBQty>= 0)
		if @row>0
		begin
			select @errmsg= 'Bag Qty Should Be >= 0'
			goto ErrHndlr
		end

		/****** Cannot Add/ Change As Not The Last Transaction Of The Bag ********/
		/* Current Partition */
		select @Row= Count('x') from inserted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo
				and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
				and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0
			where TpPrtKey=@wCurrPrtn and not exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdno=TdBIdNo 
				and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BLstYyKey= TdYyKey)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Edit Since Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSubPrc<> '' and
				not exists (select PSCd from Param where PTyp= 'SUBPRC'
					and PMCd= (Select TdByLoc from Txnd where TdPRtKey=TpPrtKey and TdIdNo=TpTdIdNo 
					and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
					and TdSr= TpSr and TdSrNo= 0) and PSCd= TpSubPrc)
		if @row>0
		begin
			select @errmsg= 'Sub Process Not Defined'
			goto ErrHndlr
		end
/*
		select @row= count('x') from inserted where (TpBQty< 0 or TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('GN')
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Bag Qty Should Be >= 0, Rm Qty = 0, PrdCtg Not Blank, RmCtg/RmSubCtg/SetTyp Blank'
			goto ErrHndlr
		end
*/

		/* (Bef 2.13)		
		select @row= count('x') from inserted where (TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('GN')
		(Bef 2.13) */


		/*** (Jen 2.13) ***/		
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg= '' or TpRmQty<> 0 or TpRmCtg<> '' or TpRmSCtg<> '' or TpSetTyp<> '') and
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
						from Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy 
						and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 ) in ('GN')
		/*** (Jen 2.13) ***/		
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Rm Qty = 0, PrdCtg Not Blank, RmCtg/RmSubCtg/SetTyp Blank'
			goto ErrHndlr
		end
/*
		select @row= count('x') from inserted where (TpBQty< 0 or TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
						and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Bag Qty Should Be >= 0, Rm Qty > 0, PrdCtg Blank, RmCtg/RmSubCtg/SetTyp Not Blank'
			goto ErrHndlr
		end
*/

		/* (Bef 2.13)
		select @row= count('x') from inserted where (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc 
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		(Bef 2.13) */

		/*** (Jen 2.13)	***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp= '') and
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
					From Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WS', 'GS')
		/*** (Jen 2.13)	***/
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry, Rm Qty <> 0, PrdCtg Blank, RmCtg/RmSubCtg/SetTyp Not Blank'
			goto ErrHndlr
		end
/*	#################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date:	08/12/2003																			 */
/*	Cnange:	Following Check is added for checking only required values are Entered				 */

		
		/* (Bef 2.13)
		select @row= count('x') from inserted where (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp<> '') and 
					(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc 
					where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WP', 'GP')
		(Bef 2.13) */

		/*** (Jen 2.13)	***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and (TpPrdCtg<> '' or TpRmQty= 0 or TpRmCtg= '' or TpRmSCtg= '' or TpSetTyp<> '') and 
					(Select (Select LocPrdTyp from Loc where LocCoCd= TdCoCd and LocCd= TdByLoc) 
					from Txnd where TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr 
						and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0) in ('WP', 'GP')
		/*** (Jen 2.13)	***/
		if @row> 0
		begin
			select @errmsg= 'In Prd Pts Entry for PrdTyp in (''GP'',''WP''), Rm Qty <> 0, PrdCtg Blank, RmCtg/RmSubCtg Not Blank, SetTyp Blank'
			goto ErrHndlr
		end
		/*  #########################################  Manoj  #########################################  */

		/******  If not Blank then TpPrdCtg= valid PMCd('PRDCTG')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpPrdCtg<> '' and
	  		not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= TpPrdCtg)
 		if @row> 0
	 	Begin
  			select @errmsg= 'Production Category Not Defined'
  			goto ErrHndlr
	 	end

		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmCtg<> '' and not exists (select PMCd from Param where PTyp= 'RMCTG'
				and PMCd= TpRmCtg)
		if @row>0
		begin
			select @errmsg= 'Raw Material Category Not Defined'
			goto ErrHndlr
		end

		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmSCtg<> '' and not exists (select PSCd from Param where PTyp= 'RMSCTG'
				and PMCd= TpRmCtg and PSCd= TpRmSCtg)
		if @row>0
		begin
			select @errmsg= 'Raw Material Sub Category Not Defined'
			goto ErrHndlr
		end

		/******  If not Blank then TpSetTyp= valid PSCd('LABSCD', 'SET')  ******/
		/* 3.11.0 */
		Select @row= count('x') from inserted 
					Join Head On HCoCd=TpCoCd And HCd='ZSELF'
		Where TpPrtKey=@wCurrPrtn and TpSetTyp<> '' and
		 ((hSetTypOnlyFrOrdYN='N' And Not exists (Select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= TpSetTyp)) OR
		  (hSetTypOnlyFrOrdYN='Y' And Not exists (select 'x' from Txnd 												
														Join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
														Join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and OrNo= BOdNo and OrSr= BOdSr
													Where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr 
														And TdSrNo=0 And OrRmCtg= TpRmCtg and OrRmSCtg= TpRmSCtg And OrSetSCd=TpSetTyp))) 			

 		if @row> 0
	 	Begin
  			select @errmsg= 'Setting Type Not Defined or Absent in Order'
  			goto ErrHndlr
	 	end

		/* Current Partition */
		/* Before 3.11.0 */
		/* select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpSetTyp<> '' and
	  		not exists (select 'x' from Param where PTyp= 'LABSCD' and PMCd= 'SET' and PSCd= TpSetTyp)
 			if @row> 0
	 		Begin
  				select @errmsg= 'Setting Type Not Defined'
  				goto ErrHndlr
	 		end */

/*	#################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date:	08/12/2003				Ver:	2.0.6												*/
/*	Cnange:	In this Check is condition is added for allowing SETTYP Blank When PRDTYP in ('GP','WP')*/
		/* Current Partition */
/* **** Manali 3.5.0 - Check for Setting Type from OrdRm removed **** */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and TpRmCtg<> '' and
			not exists (select 'x' from inserted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy 
						and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 
					join Bag on BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo 
					join OrdRm on OrPrtKey=BPrtKey and OrOdIdNo=BOdIdNo and OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr 
						and OrNo= BOdNo and OrSr= BOdSr 
					where OrRmCtg= TpRmCtg and OrRmSCtg=TpRmSCtg /*and 
						(OrSetSCd= TpSetTyp Or (Select LocPrdTyp From Loc Where LocCoCd = TdCoCd 
						And LocCd = TdByLoc) in ('GP', 'WP'))*/) 
		If @row> 0
		begin
			select @errmsg= 'Raw Material Ctg/ Sub Ctg Combination Not Defined In OrderRm'
			/* select @errmsg= 'Raw Material Ctg/ Sub Ctg/ SetTyp Combination Not Defined In OrderRm' */
			goto ErrHndlr
		end
/*
		select @row= count('x') from inserted where TpRmCtg<> '' and
			not exists (select 'x' from inserted join Txnd on TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and
				    TdNo= TpNo and TdSr= TpSr and TdSrNo= 0 join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and
				    BNo= TdBNo join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and
				    OrNo= BOdNo and OrSr= BOdSr where OrRmCtg= TpRmCtg and OrRmSCtg=TpRmSCtg
				    and OrSetSCd= TpSetTyp)
		if @row>0
		begin
			select @errmsg= 'Raw Material Ctg/ Sub Ctg/ SetTyp Combination Not Defined In OrderRm'
			goto ErrHndlr
		end
*/
/*  #########################################  Manoj  #########################################  */
/*		select @row= count('x') from inserted where TpPts= 0
		if @row>0
		begin
			select @errmsg= 'Production Points Cannot Be Zero'
			goto ErrHndlr
		end
*/
		/* (Bef 2.13) select @row= count('x') from inserted where Str(TpPts, 16, 2)= Str(0, 16, 2) */
		/*** (Jen 2.13) ***/
		/* Current Partition */
		select @row= count('x') from inserted where TpPrtKey=@wCurrPrtn and convert (decimal (16, 2), TpPts)= convert (decimal (16, 2), 0)
		/*** (Jen 2.13) ***/
		if @row> 0
		begin
			select @errmsg= 'Production Points Cannot Be Zero'
			goto ErrHndlr
		end
/*		*** Do not allow negative values for a Bag+ RmCtg+ RmSCtg+ SetTyp (this check to be applied later) ***
		select @row= count('x') from inserted ins join Txnd Td on TdTc= TpTc and TdYy= TpYy
			and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr
			and exists(Select 'x' from Txnd Td1 join TxndPrd Tp on Tp.TpTc= Td1.TdTc
			and Tp.TpYy= Td1.TdYy and Tp.TpChr= Td1.TdChr and Tp.TpNo= Td1.TdNo
			and Tp.TpSr= Td1.TdSr where Td1.TdBYy= Td.TdBYy
			and Td1.TdBChr= Td.TdBChr and Td1.TdBNo= Td.TdBNo
			group by Tp.TpRmCtg, Tp.TpRmSCtg, Tp.TpSetTyp
			having Round(sum(Tp.TpBQty), 1)< 0 or sum(Tp.TpRmQty) < 0
			or Round(sum(Tp.TpPts), 2)< 0)
		if @row> 0
		begin
			select @errmsg= 'Total Production Points Cannot Be Negative For The Bag'
			goto ErrHndlr
		end
*/
	/* **** Zubin 211 **** */
/* NOT REQUIRED */
/*		select @row= count('x') from inserted ins where ins.TpRmCtg In ('D', 'C') and
			Exists (select 'x' from Head where HCoCd= TpCoCd and HOrdPrdPts= 'Y') and
			(Select LocPrdTyp from Loc join Txnd on LocCoCd= TdCoCd and LocCd= TdByLoc
				where TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr and TdNo= TpNo
					and TdSr= TpSr and TdSrNo= 0) In ('GP', 'GS', 'WP', 'WS') and
			(select Convert(decimal(16, 2), Sum(Tp.TpRmQty) /
					Sum(case when Convert(decimal(16, 1), Tp.TpBQty)= 0 then 1 else Tp.TpBQty end))
				from TxndPrd Tp
				join Txnd on TdCoCd= Tp.TpCoCd and TdTc= Tp.TpTc and TdYy= Tp.TpYy and
					TdChr= Tp.TpChr and TdNo= Tp.TpNo and TdSr= Tp.TpSr and TdSrNo= 0
				join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
				where Tp.TpCoCd= ins.TpCoCd and Tp.TpTc= ins.TpTc and Tp.TpYy= ins.TpYy and
					Tp.TpChr= ins.TpChr and Tp.TpNo= ins.TpNo and Tp.TpSr= ins.TpSr and
					Tp.TpRmCtg= ins.TpRmCtg and Tp.TpRmSCtg= ins.TpRmSCtg
				Group By Tp.TpRmCtg, Tp.TpRmSCtg )>
			(select Convert(decimal(16, 2), Sum(OrPrdQty)) from Txnd
				Join Bag on BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo
				join OrdRm on OrCoCd= BCoCd and OrTc= BOdTc and OrYy= BOdYy and OrChr= BOdChr and
					OrNo= BOdNo and OrSr= BOdSr
			where TdSrNo= 0 and Exists (Select 'x' from TxndPrd where TdCoCd= TpCoCd and TdTc= TpTc and
				TdYy= TpYy and TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and OrRmCtg= TpRmCtg and
				OrRmSCtg= TpRmSCtg ) and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and
				TdChr= TpChr and TdNo= TpNo and TdSr= TpSr and OrRmCtg= ins.TpRmCtg and
				OrRmSCtg= ins.TpRmSCtg
				Group By OrRmCtg, OrRmSCtg )
		if @row> 0
		begin
			select @errmsg= 'Cannot Give Production Points For RmQty More Than In Order'
			goto ErrHndlr
		end
*/
/* **** Zubin 211 **** */
	End
	if @mode in ('C')
	Begin
		/****** Key Cannot Be Changed ******/
		/* Current Partition */
		select @Row=Count('x') from deleted del where del.TpPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.TpPrtKey=del.TpPrtKey and ins.TpIdNo=del.TpIdNo
			and ins.TpCoCd= del.TpCoCd and ins.TpTc= del.TpTc and ins.TpYy= del.TpYy and ins.TpChr= del.TpChr
			and ins.TpNo= del.TpNo and ins.TpSr= del.TpSr and ins.TpSrNo= del.TpSrNo)
		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Voucher No.'
			GoTo ErrHndlr
		end
	End
	
	
	If @mode in ('D')
	Begin
		/****** Cannot Delete As Not The Last Transaction Of The Bag ********/
		/* Current Partition */
		select @Row= Count('x') from Deleted join Txnd on TdPrtKey=TpPrtKey and TdIdNo=TpTdIdNo
				and TdCoCd= TpCoCd and TdTc= TpTc and TdYy= TpYy and TdChr= TpChr
				and TdNo= TpNo and TdSr= TpSr and TdSrNo= 0
			where TpPrtKey=@wCurrPrtn and not exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdno=TdBIdNo 
				and BCoCd= TdCoCd and BYy= TdBYy and BChr= TdBChr and BNo= TdBNo and BLstYyKey= TdYyKey)
		If @Row > 0
		begin
			Select @ErrMsg= 'Cannot Delete Since Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

	End
RETURN
ErrHndlr:
	Begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	End
END



GOGO

ALTER TRIGGER [TxndRwrk_INUPDL] ON [TxndRwrk] 
   FOR INSERT,UPDATE,DELETE  
	NOT FOR REPLICATION
AS  
BEGIN
	/* Trigger Version 3.02.0 (Speed Optimization) */  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)
	Declare @wEntTyp Varchar(8)
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TxndRwrk' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'
		
	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= TrwTc and PSCd=''
	end
	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= TrwTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TrwPrtKey<>@wCurrPrtn
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.TrwCoCd=del.TrwCoCd and
									ins.TrwTc=Del.TrwTc and ins.TrwYy=del.TrwYy and ins.TrwChr=del.TrwChr 
									and ins.TrwNo=del.TrwNo and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo 
									and ins.TrwPrtKey<>del.TrwPrtKey) 
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TrwPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TrwPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where TrwPrtKey=@wCurrPrtn and  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrwCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		/* Current Partition */
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where TrwPrtKey=@wCurrPrtn and 
			Exists (select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrwCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End 
	/******** Only One TcTyp records can be Inserted at a time ********/
	/* Partition Key Not Required */
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= TrwTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time *********/
	/* Partition Key Not Required */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd= TrwTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END
	
	/*** Storing Entry Type In The Variable @wEntTyp ***/
	select @wEntTyp= PValue1 from Param  where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''
	
	if @mode in ('A','C')
	Begin
		/********** EntTyp Should Be 'FgBag' or 'FgRm' (Check In Param) ********/
		/* Current Partition */
		select @row=count('x') from inserted 
			where TrwPrtKey=@wCurrPrtn and TrwTc <> 'DT' 
		if @row> 0
		Begin
			Select @ErrMsg='Transactions of only ''DT'' Types permitted'
			GoTo ErrHndlr
		end
		
		/*****4.1.2********/	
		Select @Row=Count('x') From Inserted ins where 
			(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=TrwCoCd)='Y' and
			(@Mode='A' or (@Mode='C' and  ins.TrwDt<>IsNull((Select TrwDt From Deleted del where 
									ins.TrwPrtKey=del.TrwPrtKey and ins.TrwIdNo=del.TrwIdNo 
									and ins.TrwCoCd= del.TrwCoCd and ins.TrwTc= del.TrwTc and ins.TrwYy= del.TrwYy 
										and ins.TrwChr= del.TrwChr and ins.TrwNo= del.TrwNo 
										and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo),ins.TrwDt))) and  
							 exists(Select 'x' From DtTbl Where DtTag='HOL' and TrwDt=DtDt and DtHolYN='Y')
		If @Row> 0
		begin  
			select @errmsg= 'Cannot Add Voucher On Holidays.'  
			goto ErrHndlr  
		end  
				

		/******  TrwCoCd = HCoCd   *******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and not exists (select 'x' from Head where HCoCd= TrwCoCd and HCd= @wHCd)
		if @row> 0
		begin
			select @errMsg= 'Company Code Not Valid'
			goto ErrHndlr
		end

		/******  TrwYy  =  PMCd ('YY')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='YY' and PMCd= TrwYy)
		if @row> 0
		begin
			select @errmsg= 'Voucher Year Not Defined'
			goto ErrHndlr
		end

		/******  TrwChr  =  PSCd ('CHR', TrwTc)  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= TrwCoCd and
					vPTyp='CHR' and vPMCd= TrwTc and vPSCd= TrwChr)
		if @row> 0
		begin
			select @errmsg= 'Voucher Character Not Defined'
			goto ErrHndlr
		end

		/******  TrwNo  <>  0  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and TrwNo= 0
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Cannot Be Zero'
			goto ErrHndlr
		end

		/****** Voucher Date Cannot Be Blank ******/
		/* Current Partition */
		select @Row= Count('x') from Inserted where TrwPrtKey=@wCurrPrtn and TrwDt in ('01/01/1980', '01/01/1900')
		If @Row > 0
		begin
			Select @ErrMsg= 'Date Cannot Be Blank'
			GoTo ErrHndlr
		end

		
		/******  TrwByLoc Valid Loc, LocTyp = 'P'   ********/
		Select @Row= Count('x') From Inserted Ins 
			Where Not Exists (Select 'x' From Loc where LocCoCd = TrwCoCd and 
				LocTyp = 'P' and LocCd = TrwByLoc) 
  	  	If @Row> 0 
		begin
			Select @ErrMsg= 'Process Loc Not Defined'
		  	GoTo ErrHndlr
		end

		/******  TrwRwrk valid PMCd=ByLoc   ******/
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='RWRK' and PMCd=TrwByLoc and PSCd = TrwRwrkCd)
		if @row> 0
		begin
			select @errmsg= 'Rework Code Not Defined'
			goto ErrHndlr
		end

		/******  TrwByWrk  =  vPMCd ('WORK')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= TrwCoCd and
					vPTyp='WORK' and vPMCd= TrwByWrk)
		if @row> 0
		begin
			select @errmsg= 'Worker Code Not Defined'
			goto ErrHndlr
		end
	End

	If @Mode = 'C'
	Begin
		/*******Cannot Change Key values ********/
		/* Current Partition */
		select @Row= Count('x') from Deleted Del where Del.TrwPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.TrwIdNo=Del.TrwIdNo and
					Ins.TrwPrtKey=Del.TrwPrtKey and Ins.TrwCoCd=Del.TrwCoCd and Ins.TrwTc=Del.TrwTc and Ins.TrwYy=Del.TrwYy
					and Ins.TrwChr= Del.TrwChr and Ins.TrwNo=Del.TrwNo and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo)
		If @Row> 0
		BEGIN
			Select @ErrMsg= 'Cannot Change Voucher No'
			GoTo ErrHndlr
		END

	End

/**	if @mode in ('D')
	Begin
			
	End  **/
Return
ErrHndlr:
	Begin
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	End
END


GOGO

ALTER TRIGGER [TxndZ_INUPDL] ON [TxndZ] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
 /* Trigger Version 3.11.3 */
 DECLARE @ROW INT  
 DECLARE @mode char(1)  
 DECLARE @errmsg varchar(255)  
 DECLARE @ReplAgt BIT  
 Declare @wTcTyp Char(3)
 Declare @wEntTyp Char(8)
 DECLARE @wCurrPrtn VarChar(1)
		  
 IF @@ROWCOUNT=0   RETURN  
  
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TxndZ' )  
  RETURN  
  
 select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
   case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   

	/* Sachin 3.02 - Constant For Current Partition */
	Select @wCurrPrtn = 'C'	

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TzPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TzPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TzPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */	

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where TzPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TzCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		If @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		If @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where TzPrtKEy=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TzCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 
	/******* If Mode = 'C' then Cannot change Key Values **********/
	If @Mode = 'C'
	Begin
		/****** Cannot Change Voucher SrNo, TzKey ******/
		/* Current Partition */
		select @Row=Count('x') from Deleted Del where Del.TzPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.TzPrtKey=Del.TzPrtKey and Ins.TzCoCd= Del.TzCoCd
					and Ins.TzTc= Del.TzTc and Ins.TzYy= Del.TzYy
					and Ins.TzChr= Del.TzChr and Ins.TzNo= Del.TzNo
					and Ins.TzSr= Del.TzSr and Ins.TzSrNo= Del.TzSrNo
					and Ins.TzKey= Del.TzKey)
		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Voucher No.'
			GoTo ErrHndlr
		end
	End
	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Current Partition */
	select @Row= Count(distinct(PValue)) from inserted Join param On
			 PTyp= 'TC' and PMCd= TzTc and PScd= '' Where TzPrtKey=@wCurrPrtn 
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time.*********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
				PTyp='TC' and PMcd=TzTc and PSCd='' Where TzPrtKey=@wCurrPrtn
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted on'
		GoTo ErrHndlr
	END

	/********** Select @wTcTyp from Inserted **********/
	If @Mode in ('A','C')
	Begin
		select @wTcTyp= max(PValue) from Inserted Join param On PTyp= 'TC'
				and PMcd= TzTc and PScd= ''
	end
	/********** Select @wTcTyp from Deleted **********/
	If @Mode in ('D')
	Begin
		select @wTcTyp= max(PValue) from Deleted Join param On PTyp= 'TC'
				and PMcd= TzTc and PScd= ''
	end

	/********** Select @wTcEntTyp from Param ********/
	select @wEntTyp = PValue1 from Param where PTyp='TCTYP' and PMcd=@wTcTyp and PSCd=''

	If @wEntTyp <> 'Tz' and @wEntTyp <> 'In'
	begin
		Select @ErrMsg= 'Entries of only ''Tz'' and ''In'' Type permitted'
		GoTo ErrHndlr
	end

	If @wTcTyp<> 'TZ' and @wTcTyp<> 'IN'
	begin
		Select @ErrMsg= 'Transactions of only ''TZ'' and ''IN'' Type permitted'
		GoTo ErrHndlr
	end

	If @Mode in ('C') and @wTcTyp= 'Tz'
	Begin
		/****** Cannot Change TzRmZCd, TzPurRt  if TzRmDespWt <> 0 ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted Del where Del.TzPrtKey=@wCurrPrtn and cast(Del.TzRmDespWt as decimal(16, 3))<> 0 and
			 Not Exists (Select 'x' from Inserted Ins where Ins.TzPrtKey=Del.TzPrtKey and Ins.TzCoCd= Del.TzCoCd
					and Ins.TzTc= Del.TzTc and Ins.TzYy= Del.TzYy
					and Ins.TzChr= Del.TzChr and Ins.TzNo= Del.TzNo
					and Ins.TzSr= Del.TzSr and Ins.TzSrNo= Del.TzSrNo
					and Ins.TzRmZCd= Del.TzRmZCd
					and Str(Ins.TzPurRt, 16, 3)= Str(Del.TzPurRt, 16, 3)
				     )
		If @Row > 0
		begin
			Select @ErrMsg='Cannot Change Custom Cd/ Purchase Rt When Despatch Weight <> 0'
			GoTo ErrHndlr
		end

		/****** Cannot Change TzRmZCd, TzPurRt  if TzRmDespWt <> 0 ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted Del where Del.TzPrtKey=@wCurrPrtn and Del.TzCls= 'Y' and
			 Not Exists (Select 'x' from Inserted Ins where Ins.TzPrtKey=Del.TzPrtKey and Ins.TzCoCd= Del.TzCoCd
					and Ins.TzTc= Del.TzTc and Ins.TzYy= Del.TzYy
					and Ins.TzChr= Del.TzChr and Ins.TzNo= Del.TzNo
					and Ins.TzSr= Del.TzSr and Ins.TzSrNo= Del.TzSrNo
					and Ins.TzRmZCd= Del.TzRmZCd
					and Str(Ins.TzPurRt, 16, 3)= Str(Del.TzPurRt, 16, 3)
					and Ins.TzRmQty= Del.TzRmQty
					and convert( decimal (16, 3), Ins.TzRmWt)= convert( decimal (16, 3), Del.TzRmWt)
					and convert( decimal (16, 3), Ins.TzRmDespWt)= convert( decimal (16, 3), Del.TzRmDespWt))
					and @ReplAgt<> 1
		If @Row> 0
		Begin
			Select @ErrMsg= 'Cannot Change Rm Qty/ Wt/ Purchase Rt/ Despatch Wt When Custom Purchase Is Closed'
			GoTo ErrHndlr
		End
	End
	If @Mode in ('A', 'C') and @wTcTyp= 'Tz'
	Begin
		/******* Valid TzTc, TzYy, TzChr, TzNo (From Txn if TcTyp= 'Tz') ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and
	  		Not Exists (Select 'x' From Txn Where Txn.TPrtKey=Ins.TzPrtKey and Txn.TCoCd= Ins.TzCoCd And
				    Txn.TTc= Ins.TzTc And Txn.TYy= Ins.TzYy And
				    Txn.TChr= Ins.TzChr And Txn.TNo= Ins.TzNo)
	  	If @Row> 0
 		Begin
			Select @ErrMsg='Voucher No. Does Not Exist In Txn'
			GoTo ErrHndlr
	  	End

		/***** TzSr <> 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPRtn and TzSr= 0
		If @Row>0
		begin
		  	Select @ErrMsg='Sr. Cannot Be Zero'
		  	GoTo ErrHndlr
		end

		/***** TzSrNo = 0 if 'Tz' *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPRtn and TzSrNo<> 0
			or (@wTcTyp= 'In' and TzSrNo<= 0)
		If @Row>0
		begin
		  	Select @ErrMsg= 'SrNo. Should Be Zero For ''Tz'' '
		  	GoTo ErrHndlr
		end

		/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
		/*********** RmCd <> Blank *********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzRmZCd = ''
  	  	If @Row>0
		begin
			Select @ErrMsg='Rm Customs Code Can Not Blank'
		  	GoTo ErrHndlr
		end

		/*********** Valid RmCd, RmZ='Y' *********/
		/* Current Partition */
		select @row= count('x') from Inserted Ins where TzPrtKey=@wCurrPrtn and TzRmZCd = '' Or
			(Ins.TzRmZCd <> IsNull((Select Del.TzRmZCd From Deleted Del Where Ins.TzPrtKey=Del.TzPrtKey and
				Ins.TzCoCd = Del.TzCoCd And Ins.TzTc = Del.TzTc And Ins.TzYy = Del.TzYy And
				Ins.TzChr = Del.TzChr And Ins.TzNo = Del.TzNo And
				Ins.TzSr = Del.TzSr And Ins.TzSrNo = Del.TzSrNo), '')
			And Not Exists (select 'x' from RmMst where RmPrtKey=TzPrtKey and RmCd= TzRmZCd and RmZ= 'Y' And RmValidYN = 'Y'))
		if @row>0
			begin
			select @errmsg= 'Rm Customs Code Not Defined / Invalid'
			goto ErrHndlr
		end
		/*********** Valid RmCd, RmZ='Y' *********/
/*		Select @Row=Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From RmMst where RmCd= TzRmZCd and RmZ= 'Y')
  	  	If @Row>0
		begin
			Select @ErrMsg='Invalid Rm Customs Code'
		  	GoTo ErrHndlr
		end  */
/*  #########################################  Manoj  #########################################  */
		/******* TzRmCdDesc <> Blank ***********/
		/* Current Partition */
  		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzRmCdDesc= ''
		If @Row>0
		begin
			Select @ErrMsg= 'Rm Code Description Should Not Be Blank'
			GoTo ErrHndlr
		end

		/****** urmi to be changed precision for comparison with 0 ***********/
		/***** If TzBm = 'B' then TzRmQty>= 0 and TzRmWt>= 0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and (TzRmQty< 0 or convert(decimal(16, 3), TzRmWt)< 0)
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Rm Wt/Qty Should Be > 0'
		  	GoTo ErrHndlr
		end

		/***** If TzBm = 'B' then TzRmQty>= 0 and TzRmWt>= 0 ***** 2.10.0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzBm = 'B' and (convert(decimal(16, 3), TzRmDespPurgeWt)< 0)
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Purged Despatched Wt Should Be >= 0'
		  	GoTo ErrHndlr
		end

		/***** If TzBm = 'B' then TzRmDespWt<= TzRmWt *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and Cast(TzRmDespWt as decimal(16, 3)) > cast(TzRmWt as decimal(16, 3))
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Rm Wt Should Be > Despatch Wt'
		  	GoTo ErrHndlr
		end

		/***** If TzBm = 'B' then TzRmDespPurgeWt<= TzRmDespWt ***** 2.10.0    *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and Cast(TzRmDespPurgeWt as decimal(16, 3)) > cast(TzRmDespWt as decimal(16, 3))
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Despatch Wt Should Be > Purged Despatch Wt'
		  	GoTo ErrHndlr
		end

		/******* TzKey <> 0 ***********/
		/* Current Partition */
  		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzKey<= 0
		If @Row>0
		begin
			Select @ErrMsg= 'Key Should Be > 0'
			GoTo ErrHndlr
		end

		/***** If TzBm = 'B' then TzRefYy= TzYy, TzRefKey = TzKey *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPRtKey=@wCurrPrtn and (TzRefYy <> TzYy or TzRefKey <> TzKey)
		If @Row> 0
		begin
		  	Select @ErrMsg= 'RefYy & RefKey of Base Recs Should Be Same As Yy & Key Respectively'
		  	GoTo ErrHndlr
		end

		/***** TzPurRt> 0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and convert(decimal(16, 2), TzPurRt)<= 0
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Purchase Rate Should Be > 0'
		  	GoTo ErrHndlr
		end

		/***** TzPurAmt> 0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPRtn and TzPurAmt<= 0
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Purchase Amount Should Be > 0'
		  	GoTo ErrHndlr
		end

		/***** TzBm = 'B' if 'Tz' *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and TzBm<> 'B'
		If @Row> 0
		begin
		  	Select @ErrMsg= 'TzBM should Be ''B'' '
	  		GoTo ErrHndlr
		end

		/***** If TzBm = 'B' then TzRmDespWt>= 0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKEy=@wCurrPrtn and convert(decimal(16, 3), TzRmDespWt)< 0
		If @Row>0
		begin
		  	Select @ErrMsg= 'Despatch Wt Should Be >= 0'
		  	GoTo ErrHndlr
		end

		/***** TzCls= Valid Param('YN') *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and not exists(Select 'x' From Param where PTyp= 'YN' and PMCd= TzCls)
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Purchase Close Option Not Defined'
		  	GoTo ErrHndlr
		end
/* ### 		***** These Updates are done when the TcTyp= 'In'  *****
		*** Update TzCls = 'Y' if TzRmWt= TzRmDespWt ***
		update TxndZ set
		TxndZ.TzCls= 'Y'
		from inserted ins where ins.TzYy= TxndZ.TzYy and ins.TzKey= TxndZ.TzKey and ins.TzRmWt= Round(ins.TzRmDespWt, 3)
		*** Update TzCls = 'N' if TzRmWt<> TzRmDespWt ***
		update TxndZ set
		TxndZ.TzCls= 'N'
		from inserted ins where ins.TzYy= TxndZ.TzYy and ins.TzKey= TxndZ.TzKey and ins.TzRmWt<> Round(ins.TzRmDespWt, 3)
### */
 
		/*** (Jen 3.1.2) ***/
		/***** Either All Best Use Order Fields are filled up or all are blank *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
		Where Ins.TzPrtKey=@wCurrPrtn and (TzOdTc<> '' or TzOdYy<> '' or TzOdChr<> '' or TzOdNo<> 0)
			and (TzOdTc= '' or TzOdYy= '' or TzOdChr= '' or TzOdNo= 0) 
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Either All Order Fields Should Be Filled Or All Should Be Blank'
		  	GoTo ErrHndlr 
		end 

		/***** TzOdNo = Valid Order Number *****/ 
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPRtn and TzOdNo<> 0 
			and not exists(Select 'x' From OrdMst where OmPrtKey=TzPrtkey and OmCoCd= TzCoCd and OmTc= TzOdTc and OmYy= TzOdYy 
				and OmChr= TzOdChr and OmNo= TzOdNo) 
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'Order Number Not Defined'
		  	GoTo ErrHndlr
		end

		/***** TzDmCd = Valid Design Code *****/ 
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzDmCd<> '' 
			and not exists(Select 'x' From DsgMst where DmPrtKey=TzPrtKey and DmTcTyp= 'DM' and DmCd= TzDmCd and DmSz= '') 
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'Design Code Not Defined'
		  	GoTo ErrHndlr
		end

		/***** TzRmCd = Valid RM Code *****/ 
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzRmCd<> '' 
			and not exists(Select 'x' From RmMst Where RmPrtKey=TzPrtKey and RmCd= TzRmCd and RmZ= 'N') 
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'RM Code Not Defined' 
		  	GoTo ErrHndlr
		end

		/***** TzRmSzFr<= TzRmSzTo *****/ 
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and (TzRmSzFr> TzRmSzTo and TzRmSzTo<> 0)
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'RM Size Range Not Proper' 
		  	GoTo ErrHndlr
		end
		/*** (Jen 3.1.2) ***/

		/*** Manali 350Nxt ***/
		/** Manali 3.6.2 - Following Check to be applied Only for Manually closed Vouchers */
		select @row= count('x') from inserted where TzPrtKey=@wCurrPrtn and TzCls='Y' and TzClsDt in ('01/01/1980', '01/01/1900')
			and Convert(Decimal(16,3), TzRmWt) <> Convert(Decimal(16,3), TzRmDespWt)
		if @row> 0 
		begin
			select @errmsg= 'Closing Date Cannot Be Blank When Voucher is Manually Closed'
			goto ErrHndlr
		end
		/*** Manali 350Nxt ***/

		/*** Manali 350Nxt ***/
		/** Manali 3.6.2 - Following Check excluded only for Manually Closed Vouchers */
		select @row= count('x') from inserted where TzPrtKey=@wCurrPrtn 
				and (TzCls='N' or Convert(Decimal(16,3), TzRmWt) = Convert(Decimal(16,3), TzRmDespWt)) 
				and TzClsDt Not in ('01/01/1980', '01/01/1900')
		if @row> 0 
		begin
			select @errmsg= 'Closing Date Should Be Blank When Voucher Is Not Closed Manually'
			goto ErrHndlr
		end
		/*** Manali 350Nxt ***/

		/** Manali 3.6.2 - Closing date checked against max Mathing Date */
		select @row= count('x') from inserted B where TzPrtKey=@wCurrPrtn and 
					Cast(TzRmWt-TzRmDespWt as Decimal(14,3))>0 and  TzCls='Y' and TzBM='B' and
			 TzClsDt <IsNull((Select  Max(InDt) 
					From InvHd Join TxndZ M On M.TzCoCd=InCoCd and M.TzTc=InTc and M.TzYy=InYy and 
								M.TzChr=InChr and M.TzNo=InNo and M.TzBM='M'
								where M.TzCoCd=B.TzCoCd and M.TzRefYy=B.TzYy and M.TzRefKey=B.TzKey
		Group By M.TzCoCd,M.TzRefYy,M.TzRefKey),TzClsDt)
		if @row> 0 
		begin
			select @errmsg= 'Closing Date Should Be > Max Match Date.'
			goto ErrHndlr
		end

	End
	If @Mode in ('D') and @wTcTyp= 'Tz'
	Begin
		/****** Cannot delete if TzRmDespWt <> 0 ******/
		/* Current Partition */
		select @row= count('x') from deleted where TzPrtKey=@wCurrPrtn and cast(TzRmDespWt as decimal(16, 3)) <> 0
		if @row> 0
		begin
			select @errmsg= 'Cannot Delete As Despatch Weight > 0'
			goto ErrHndlr
		end
	End
	If @Mode in ('A', 'C')  and @wTcTyp= 'In'
	Begin
		/******* Valid TzTc, TzYy, TzChr, TzNo (From InvHd if TcTyp= 'In') ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and
	  		Not Exists (Select 'x' From InvZRm Where IzPrtKey=Ins.TzPrtKey and IzCoCd= Ins.TzCoCd And
				    IzTc= Ins.TzTc And IzYy= Ins.TzYy And IzChr= Ins.TzChr And
				    IzNo= Ins.TzNo and IzSr= Ins.TzSr)
  		If @Row> 0
	 	begin
			Select @ErrMsg= 'Voucher Sr. Does Not Exist In Inv Customs Rm File'
			GoTo ErrHndlr
  		end

		/***** TzSrNo >0 if 'In' *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPRtKey=@wCurrPrtn and @wTcTyp= 'In' and TzSrNo<= 0
		If @Row> 0
		begin
		  	Select @ErrMsg= 'SrNo. Should Be > 0'
		  	GoTo ErrHndlr
		end

		/*********** Valid RmCd, RmZ='Y' *********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins
			Where Ins.TzPrtKey=@wCurrPrtn and Not Exists (Select 'x' From RmMst where RmPrtKey=TzPrtKey and RmCd= TzRmZCd and RmZ= 'Y')
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'Invalid Rm Customs Code'
		  	GoTo ErrHndlr
		end

		/******* TzRmCdDesc = Blank ***********/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where TzPRtKey=@wCurrPrtn and TzRmCdDesc<> ''
		If @Row> 0
		begin
			Select @ErrMsg= 'Rm Code Description Should Be Blank'
			GoTo ErrHndlr
		end

		/***** TzRmQty= 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and  (TzRmQty<> 0 or TzPcPerCt<> 0)
		If @Row>0
		begin
		  	Select @ErrMsg= 'Rm Qty/ Pc Per Ct Should Be = 0'
		  	GoTo ErrHndlr
		end

		/***** TzRmWt> 0 *****/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and convert(decimal(16, 3), TzRmWt)<= 0
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Rm Wt/Qty Should Be > 0'
		  	GoTo ErrHndlr
		end

		/******* TzKey <> 0 ***********/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzKey<= 0
		If @Row> 0
		begin
			Select @ErrMsg= 'Key Should Be > 0'
			GoTo ErrHndlr
		end
		/***** Match.TzRefYy= Base.TzYy, Match.TzRefKey = Base.TzKey *****/
/*		Select @Row=Count('x') From Inserted Ins Where Not Exists (Select 'x' From
			TxndZ B where B.TzCoCd= ins.TzCoCd and B.TzYy= ins.TzRefYy
			and B.TzKey= ins.TzRefKey and B.TzRmZCd= ins.TzRmZCd
			and convert(decimal(16, 2), B.TzPurRt)= convert(decimal(16, 2), ins.TzPurRt)
			and B.TzBM= 'B')
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Reference Year, Key Not Defined'
		  	GoTo ErrHndlr
		end
*/
		/**************Geeta********Emr207***Purchase in Rs.**/
		/*** (Bef 2.13)
		Select @Row= Count('x') From Inserted Ins 
			Where Not Exists (Select 'x' From 
			TxndZ B Join Txn On B.TzCoCd=TCoCd and B.TzTc=TTc and B.TzYy=TYy 
			and B.TzChr=TChr and B.TzNo=TNo 
			where B.TzCoCd= ins.TzCoCd and B.TzYy= ins.TzRefYy 
			and B.TzKey= ins.TzRefKey and B.TzRmZCd= ins.TzRmZCd 
			and convert(decimal(16, 2), ins.TzPurRt)= convert(decimal(16, 2), B.TzPurRt) 
			and B.TzBM= 'B') 
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'Reference Year, Key Not Defined/ Purchase Rate Changed' 
		  	GoTo ErrHndlr 
		end
		(Bef 2.13) ***/

		/*** (Jen 2.13) ***/
		/* Current Partition */
		/* ***** Manali 3.6.0 - 31/10/09 - Check for TzPurRt skipped When InNotionRtYn='N' */
		Select @Row= Count('x') From Inserted Ins 
			join InvHd on InPrtKey=Ins.TzPrtKey and InCoCd= Ins.TzCoCd and InTc= Ins.TzTc and InYy= Ins.TzYy 
				and InChr= Ins.TzChr and InNo= Ins.TzNo 
			Where Not Exists (Select 'x' From TxndZ B Join Txn On B.TzPrtKey=TPrtKey and B.TzCoCd= TCoCd and B.TzTc=TTc 
					and B.TzYy= TYy and B.TzChr= TChr and B.TzNo= TNo 
					where B.TzPrtKey=ins.TzPrtKey and B.TzCoCd= ins.TzCoCd and B.TzYy= ins.TzRefYy 
					and B.TzKey= ins.TzRefKey and B.TzRmZCd= ins.TzRmZCd 
					and	convert(decimal(16, 1), convert(decimal(16, 3), ins.TzPurRt) 
							/ convert(decimal(16, 4), (case when InMulDiv= 'M' then InCnvFct else 1 end)) 
							* convert(decimal(16, 4), (case when InMulDiv= 'D' then InCnvFct else 1 end)) )= 
					    (Case When InNotionRtYn='Y' and (Select RmCtg from RmMst Where RmCd=ins.TzRmZCd) In ('G', 'P', 'S', 'L')	Then 
							convert(decimal(16, 1), convert(decimal(16, 3), ins.TzPurRt) 
							/ convert(decimal(16, 4), (case when InMulDiv= 'M' then InCnvFct else 1 end)) 
							* convert(decimal(16, 4), (case when InMulDiv= 'D' then InCnvFct else 1 end)))
						Else
							convert(decimal(16, 1), convert(decimal(16, 3), B.TzPurRt) 
							/ convert(decimal(16, 4), (case when TMulDiv= 'M' then TCnvRt else 1 end))
							* convert(decimal(16, 4), (case when TMulDiv= 'D' then TCnvRt else 1 end)))   
						End)
			and B.TzBM= 'B') 
		If @Row> 0 
		begin
		  	Select @ErrMsg= 'Reference Year, Key Not Defined/ Purchase Rate Changed' 
		  	GoTo ErrHndlr 
		end
		/*** (Jen 2.13) ***/

		/**************Geeta********Emr207*****/
		/******* TzPurAmt > 0 ***********/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and convert(decimal(16, 2), TzPurAmt)<= 0
		If @Row> 0
		begin
			Select @ErrMsg= 'Purchase Amount Should Be > 0'
			GoTo ErrHndlr
		end

		/***** TzBm = 'M' if 'In' *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and TzBm<> 'M'
		If @Row>0
		begin
		  	Select @ErrMsg= 'TzBM Should Be ''M'' '
	  		GoTo ErrHndlr
		end

		/******* TzRmDespWt = 0 ***********/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where Ins.TzPrtKey=@wCurrPrtn and convert(decimal(16, 3), TzRmDespWt)<> 0
		If @Row> 0
		begin
			Select @ErrMsg= 'Despatch Weight Should Be = 0'
			GoTo ErrHndlr
		end
		/******* TzRmDespPurgeWt = 0 *********** 2.10.0  *****/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and convert(decimal(16, 3), TzRmDespPurgeWt)<> 0
		If @Row> 0
		begin
			Select @ErrMsg= 'Purged Despatch Weight Should Be = 0'
			GoTo ErrHndlr
		end
		/******* TzCls = Blank ***********/
		/* Current Partition */
  		Select @Row= Count('x') From Inserted Ins Where TzPrtKey=@wCurrPrtn and TzCls<> ''
		If @Row> 0
		begin
			Select @ErrMsg= 'Purchase Close Option Should Be Blank'
			GoTo ErrHndlr
		end

		/*** Manali 350Nxt ***/
		select @row= count('x') from inserted where TzPrtKey=@wCurrPrtn and TzClsDt Not in ('01/01/1980', '01/01/1900')
		if @row> 0 
		begin
			select @errmsg= 'Closing Date Should Be Blank'
			goto ErrHndlr
		end
		/*** Manali 350Nxt ***/
	End

	If @Mode in ('D', 'C')  and @wTcTyp= 'In' And (@ReplAgt<>1)
	Begin
		/* Update Tz Base record, Set TzRmDespWt = (Subtract TzRmWt from delete,Add TzRmWt from insert) */
		/* Current Partition */
		update TxndZ set
		TxndZ.TzRmDespWt= TxndZ.TzRmDespWt - IsNull((Select sum(del1.TzRmWt) from deleted del1 where
			del1.TzCoCd= TxndZ.TzCoCd and del1.TzRefYy= TxndZ.TzYy
			and del1.TzRefKey= TxndZ.TzKey), 0)
		from deleted del where del.TzPrtKey=Txndz.TzPrtKey and del.TzCoCd= TxndZ.TzCoCd and del.TzRefYy= TxndZ.TzYy
			and del.TzRefKey= TxndZ.TzKey
		/* Update Base TzCls = 'N' if Base TzRmWt<> TzRmDespWt */
		/* Manali 3.6.1 - TzClsDt update */
		Update TxndZ Set TxndZ.TzCls= 'N', TxndZ.TzClsDt= '01/01/80'
		From deleted del Where del.TzPrtKey=TxndZ.TzPrtKey and del.TzCoCd= TxndZ.TzCoCd and del.TzRefYy= TxndZ.TzYy
			and del.TzRefKey= TxndZ.TzKey and cast(TxndZ.TzRmWt as decimal(16, 3))<> cast(TxndZ.TzRmDespWt as decimal(16, 3))
	End

	If @Mode in ('A', 'C')  and @wTcTyp= 'In' And (@ReplAgt<>1)
	Begin
		/* Update Tz Base record, Set TzRmDespWt = (Subtract TzRmWt from delete,Add TzRmWt from insert) */
		/* Current Partition */
		update TxndZ set
		TxndZ.TzRmDespWt= /* convert(decimal(16, 3), */ TxndZ.TzRmDespWt + IsNull((Select sum(ins1.TzRmWt) from inserted ins1 where
			ins1.TzPrtKey=TxndZ.TzPrtKey and ins1.TzCoCd= TxndZ.TzCoCd and ins1.TzRefYy= TxndZ.TzYy
			and ins1.TzRefKey= TxndZ.TzKey), 0) /*)*/
		from inserted ins where ins.TzPrtKey=TxndZ.TzPrtKey and ins.TzCoCd= TxndZ.TzCoCd and ins.TzRefYy= TxndZ.TzYy
			and ins.TzRefKey= TxndZ.TzKey
		/********* urmi 2.04-3 After Updating DespQty Check for RmWt<DespQty */
		Select @Row= Count('x') From Inserted M
				join Txndz B on M.TzPrtKey=B.TzPrtKey and M.TzCoCd= B.TzCoCd and M.TzRefYy= B.TzYy and
						M.TzRefKey= B.TzKey
		where cast(B.TzRmDespWt as decimal(16, 3)) > cast(B.TzRmWt as decimal(16, 3))
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Rm Wt Should Be > Despatch Wt'
		  	GoTo ErrHndlr
		end
		/********************************************************************/
		/********* Jen ***/
		/* Current Partition */
		Select @Row= Count('x') From TxndZ Tz
				join InvZRm on IzPrtKey=TzPrtKey and IzCoCd= TzCoCd and IzTc= TzTc and
				IzYy= TzYy and IzChr= TzChr and IzNo= TzNo and
				IzSr= TzSr
				where exists(Select 'x' from Inserted where
					TzPrtKey=IzPrtKey and TzCoCd= IzCoCd and TzTc= IzTc
					and TzYy= IzYy and TzChr= IzChr and TzNo= IzNo
					and TzSr= IzSr)
				Group By IzCoCd, IzTc, IzYy, IzChr, IzNo, IzSr
				having convert(decimal(16, 3), sum(TzRmWt))> convert(decimal(16, 3), max(IzRmZWt))
		If @Row> 0
		begin
		  	Select @ErrMsg= 'Inv Rm Wt Should Be > Match Wt'
		  	GoTo ErrHndlr
		end
		/********************************************************************/
		/* Update Base TzCls = 'Y' if Base TzRmWt= TzRmDespWt */
			/* Current Partition */
			/* Manali 3.6.1 - TzClsDt update */
			/** Manali 3.6.2 - TzClsDt Update removed *** */
			update TxndZ set TxndZ.TzCls= 'Y'
			from inserted ins where ins.TzPRtKey=@wCurrPrtn and ins.TzPrtKey=TxndZ.TzPRtKey and ins.TzCoCd= TxndZ.TzCoCd and ins.TzRefYy= TxndZ.TzYy
				and ins.TzRefKey= TxndZ.TzKey and cast(TxndZ.TzRmWt as decimal(16, 3))= cast(TxndZ.TzRmDespWt as decimal(16, 3))	
	End
Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
END

GOGO

ALTER TRIGGER [UserRole_INUPDL] ON [UserRole]  --with Encryption
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode CHAR(1)
	DECLARE @errmsg VARCHAR(255)

	IF @@ROWCOUNT = 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UserRole' )
		RETURN

	SELECT @mode = 	CASE (SELECT COUNT(1) FROM Inserted)
					WHEN 0 THEN 'D'
	       			ELSE
						CASE (SELECT COUNT(1) FROM Deleted)
						WHEN 0 THEN 'A'
						ELSE 'C'
						END
	       			END

 	IF @mode = 'C'
 	BEGIN
	/******** Key Fields Cannot Be Changed ********/
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.UserId= del.UserId and ins.RoleId=del.RoleId)
		IF @row>0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Key Field of This Table'
			GOTO ErrHndlr
		END
	END

 	IF @mode in ('A','C')
 	BEGIN

		/********Valid UserCd ********/
		SELECT @row = COUNT(1) FROM inserted   WHERE
			not Exists (SELECT 'x' FROM CrmUsr WHERE  CuUsrCd=UserId )
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Invalid User Code' 
			GOTO ErrHndlr
		END

		/********Valid RoleId ********/
		SELECT @row = COUNT(1) FROM inserted  ins WHERE
			not Exists (SELECT 'x' FROM RoleDefinitions rd  WHERE  rd.RoleId=ins.RoleId )
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Invalid RoleId' 
			GOTO ErrHndlr
		END

	END
RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END



GOGO

ALTER TRIGGER [UsrAccess_INUPDL] ON [usraccess] 
	    FOR INSERT,UPDATE,DELETE 
		NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 3.8.0 */
	DECLARE @ROW INT
	DECLARE @mode CHAR(1)
	DECLARE @errmsg VARCHAR(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT = 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrAccess' )
		RETURN

	SELECT @mode = 	CASE (SELECT COUNT(1) FROM Inserted)
					WHEN 0 THEN 'D'
	       			ELSE
						CASE (SELECT COUNT(1) FROM Deleted)
						WHEN 0 THEN 'A'
						ELSE 'C'
						END
	       			END

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete Allowed if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin
		If   Exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' ) /* or
		Exists (select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' )*/
			Begin
				select @errmsg= 'Cannot Insert /Update /Delete '
				goto ErrHndlr
			end
		End
	End


 	IF @mode = 'C'
 	BEGIN
	/******** Key Fields Cannot Be Changed ********/
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.UaUsrCd= del.UaUsrCd 
				and ins.UaMnuCd= del.UaMnuCd)
		IF @row>0
		BEGIN
			SELECT @ErrMsg = 'Cannot Change Key Field of This Table'
			GOTO ErrHndlr
		END
	END

 	IF @mode in ('A')
 	BEGIN
		/******** Valid UaUsrCd ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'USR' AND PMCd = UaUsrCd and PValidYn = 'Y')
		IF @row>0
		BEGIN
			SELECT @errmsg = 'User Code not Defined / Invalid.'
			GOTO ErrHndlr
		END


		/*Select @row = Count('x') From Inserted Ins Where Ins.UaUsrCd Not In ('MIC','CRM','SUPP') And 
			Not Exists (Select 'x' From UsrAccess uMic Where  uMic.UaUsrCd = 
							(Case When Ins.UaMnuForm In ('MDI','LST') Then  'MIC' 
									When Ins.UaMnuForm In ('CRM') Then  'CRM' 
									When Ins.UaMnuForm In ('MTN') Then 'SUPP' END)) 
			And Ins.UaMnuCd=uMic.UaMnuCd)*/				

		/****** Sachin 2.14.0 Next ******/
		/***** Manali 3.8.0 - JMIC added ****/
		Select @row = Count('x') From Inserted Ins Where Ins.UaUsrCd Not In ('MIC','CRM','SUPP', 'JMIC') And 
			Not Exists (Select 'x' From UsrAccess uMic Where  ((uMic.UaUsrCd = 
							(Case When Ins.UaMnuForm In ('MDI','LST') Then  'MIC' 
									When Ins.UaMnuForm In ('CRM') Then  'CRM' 
									When Ins.UaMnuForm In ('MTN') Then 'SUPP' END)) Or 
							 (uMic.UaUsrCd = (Case When Ins.UaMnuForm In ('MDI','LST') Then 'JMIC' End)))
			And Ins.UaMnuCd=uMic.UaMnuCd)				
		IF @row>0
		Begin
			SELECT @errmsg = 'Menu Code Not Defined/Invalid Menu Code'
			GOTO ErrHndlr
		End
		/****** Sachin 2.14.0 Next ******/

	END

 	IF @mode in ('A', 'C')
 	BEGIN
		/******** UaTag cannot be duplicated for the same user UaUsrCd ********/
		SELECT @row = COUNT(1) FROM Inserted Ins WHERE
			EXISTS (SELECT 1 FROM UsrAccess UA WHERE UA.UaUsrCd = Ins.UaUsrCd And UA.UaMnuForm = Ins.UaMnuForm 
						 And UA.UaMnuCd <> Ins.UaMnuCd And UA.UaTag = Ins.UaTag )
		IF @row> 0
		BEGIN
			SELECT @errmsg = 'Tag can not be Duplicate' 
			GOTO ErrHndlr
		END

		/* *** JAY 2.14  *** */ 
		/*  UaSeoYn valid (Y/N) or '' */
		Select @row= count('x') from Inserted Ins where Ins.UaSeoYn<> '' and 
			not exists (Select 'x' from Param where PTyp = 'YN' and PMCd = Ins.UaSeoYn and PSCd = '')
		if @row> 0 
		Begin
			select @errmsg= 'Enter ''Y'' To Give SEO Equivalent Rights Or ''N''/'''' Not To Give'
			goto ErrHndlr
		End
		/* *** JAY 2.14  *** */ 

		/* *** JAY 2.14  *** */ 
		/* If UaSeoYn = 'Y', User Password Can Not Be Blank */
		Select @row= count('x') from Inserted Ins where Ins.UaSeoYn= 'Y' and 
			exists (Select 'x' from Param where PTyp= 'USR' and PMCd= Ins.UaUsrCd and PSCd= '' and PValue= '')
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Sanction SEO Rights As User Password Is Blank' 
			goto ErrHndlr
		End
		/* *** JAY 2.14  *** */ 

		/*Select @row= count('x') from Inserted Ins where Ins.UaMetlrCd<> '' and 
			not exists (Select 'x' from Param where PTyp = 'METLR' and PMCd = Ins.UaMetlrCd and PSCd = '')
		if @row> 0 
		Begin
			select @errmsg= 'Enter Valid Metler Code or Keep it blank'
			goto ErrHndlr
		End*/

	END
RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

ALTER TRIGGER [UsrLogin_INUPDL] ON [UsrLogin]  
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode CHAR(1)
	DECLARE @errmsg VARCHAR(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	
	IF @@ROWCOUNT = 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrLogin' )
		RETURN
	SELECT @mode = 	CASE (SELECT COUNT(1) FROM Inserted)
					WHEN 0 THEN 'D'
	       			ELSE
						CASE (SELECT COUNT(1) FROM Deleted)
						WHEN 0 THEN 'A'
						ELSE 'C'
						END
	       			END

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')

	
	
 	IF @mode = 'C'
 	BEGIN
	/******** Any Field Cannot Be Changed ********/
		SELECT @ErrMsg = 'Cannot Change Any Field of This Table'
		GOTO ErrHndlr
	END
 	IF @mode in ('A')
 	BEGIN
		/******** Valid UlUsrCd ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Param WHERE PTyp = 'USR' AND PMCd = UlUsrCd)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'User Code not Defined'
			GOTO ErrHndlr
		END
		/******** Valid UlCoCd ********/
		SELECT @row = COUNT(1) FROM Inserted WHERE
			NOT EXISTS (SELECT 1 FROM Head WHERE HCoCd= UlCoCd AND HCd = 'ZSELF')
			AND NOT EXISTS(SELECT 'x' FROM xHead WHERE @SYS= 'XEMR' AND xHCd= UlCoCd)
		IF @row>0
		BEGIN
			SELECT @errmsg = 'Company Code not Defined'
			GOTO ErrHndlr
		END
	END

RETURN
ErrHndlr:
	BEGIN
		SELECT @errmsg = '|' + @errmsg
		RAISERROR(@errmsg, 16, 1)
		ROLLBACK TRANSACTION
	END
END

GOGO

ALTER TRIGGER [UsrMail_INUPDL] ON [UsrMail] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
 DECLARE @ROW INT  
 DECLARE @mode char(1)  
 DECLARE @errmsg varchar(255)  
 DECLARE @ReplAgt BIT  
	 
 IF @@ROWCOUNT=0   RETURN  
  
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrMail' )  
  RETURN  
  
 select @mode=case (select count('x') from inserted) when 0 then 'D'  
       else  
   case (select count('x') from deleted) when 0 then 'A' else 'C' end  
       end   
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
	
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
END  

GOGO

ALTER TRIGGER [UsrOpt_INUPDL] ON [UsrOpt]
               FOR INSERT,UPDATE,DELETE
			   NOT FOR REPLICATION
AS
BEGIN
	/****** Trigger Version - 3.11.1 ******/
	DECLARE @ROW INT
	declare @mode char(1)
	declare @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wSelfCoCd varchar(3)

	set @wSelfCoCd= 'ZZZ'
	set @wSelfCd = 'ZSELF'	

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrOpt' )
		RETURN

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	select @mode=case (select count('x') from inserted) when 0 then 'D'
	      else
		case (select count('x') from deleted) when 0 then 'A' else 'C' end
	     end

	
	/****** added RepTxnRetMem, RepVchPrnRetMem (Jen 2.14 Next) ******/
	/****** added RepGRFormBackMulti, RepWipBRmBkDt (Jen 2.14) ******/
	/****** added RepGSPFORMMulti, RepGSPDetLetMulti, RepGSPCertMulti, RepDeclnLetMulti (Jen 3.01) ******/
	/* **** Zubin 211 'RepFltBagPrn' added **** */ 
	/* ****** Sachin 2.14.0 'RepWIWExp', 'RepWIWLongExp', 'RepWIWPrd', 'RepWIWLongPrd', 'RepWipBPcs','RepWipFgBPcs'  Removed ****** */	
	/* 'RepWipBRm', 'RepWipFgBRm', 'RepWipBPcsBkDt', 'RepWipFgBPcsBkDt','RepStkLed','RepFlashStk','RepSalAnaDsg', 'RepSalAnaRm','RepSalAnaLab', 'RepStkSumm',  */
	/* 'RepGldLs', 'RepBrkMsg', 'RepRejAna', RepWipBRmBkDt  */
	/* (Jen Bef 3.01) 'RepLoc', */
	/* Zubin 3.01.01 (260308) 'RepTravExcel' */
	/*** Jay 3.4(FG)***/
	/* ***** Manali Trading Module ***** */
	/**** Manali 3.7.1 - RepJtPndRm added ****/
	/**** Manali 3.8.0 - 'RepValAddnDta' added ****/
	/***** Manali 3.10.0 - 'RepSoPnd', 'RepJtPnd', 'RepJtOpnOrd', 'RepJtPndRm', 'RepPrd' from Following List to allow Multi Companyu in reports ****/
	select @row= count('x') from inserted where UoMnuCd in (
	'RepAnnexValAddn', 'RepValAddnDta', 'RepAvgOrd', 'RepBagHist', 'RepBagLst', 'RepBagPrn', 'RepFltBagPrn', 
	'RepBv','RepCustmStk', 'RepDeclnLet', 'RepDetInv', 'RepDetInvCTB', 
	'RepDetOrd', 'RepFbLst', 'RepFrLst', 'RepGrFormBack',
	'RepGrFormFrnt', 'RepGspCert', 'RepGspDetLet', 'RepGspForm', 'RepInv','RepInvCustStmt',
	'RepInvCat', 'RepInvCTBCat', 'RepInvLossSubRep', 'RepOrdCat', 
	'RepOrdProfitMrg', 'RepPckLst', 'RepCTBPckLst', /*'RepPrd',*/ 'RepRmReq', 
	'RepRmReqDyn', 'RepRmReqLoc', 'RepRmReqStat', 'RepShpBill', /*'RepSoPnd', 'RepJtPnd', 'RepJtOpnOrd', 'RepJtPndRm',*/
	'RepTxnBS', 'RepTxnBV', 'RepTxnCnv', 'RepTxnDT', 'RepTxnMLT', 
	'RepTxnMV', 'RepTxnPR', 'RepTxnREC', 'RepTxnREJ', 'RepValAddn', 'RepVchPrnBS', 
	'RepVchPrnBV', 'RepVchPrnCNV', 'RepVchPrnDT', 'RepVchPrnMLT', 'RepVchPrnMV', 
	'RepVchPrnPR', 'RepVchPrnREC', 'RepVchPrnREJ',   'RepBvRm', 
	'RepVarPrm', 'RepPckLstInv', 'RepCntrlCpy', 'RepOrdPln', 'RepFgMvm',
	'RepTreeInvst','RepTreePerform','RepFgBagLed', 
	'RepInvLoose', 'RepShpBillLoose', 'RepGrFormLoose', 'RepPckLstLoose', 'RepShpBillMulti', 
	'RepGrFormFrntMulti', 'RepGRFormBackMulti', 'RepTxnRetMem', 'RepVchPrnRetMem', 
	'RepGSPFORMMulti', 'RepGSPDetLetMulti', 'RepGSPCertMulti', 'RepDeclnLetMulti', 'RepTravExcel',
	'REPFGDET','REPFGAVG','REPFGCAT','RepFgInv','RepFgPckLst','RepFgShpBill','RepFgGrFrnt','RepFgGrBk','RepFgGsp','RepFgLclInv',
	'REPJTDET','REPJTAVG','REPJTCAT','RepJTInv','RepJTPckLst','RepJTShpBill','RepJTGrFrnt','RepJTGrBk','RepJTGsp','RepJTLclInv', 'RepShpBillFile',
	'REPMULTIPRCQT') 
		and not exists (select 'x' from Head where HCoCd = UoCoCdFr) 
	if @row> 0 
	Begin
		select @errmsg= 'Company Code Not Defined'
		goto ErrHndlr
	end
	
	/* Manali 3.3.0 - RepInvBOELst removed */
	/* ***** Manali 3.6.0 - 19/09/09 - MenuCd RepGldLs Changed to RepMetLs ***** */
	/**** Manali 3.8.0 - RepMetLsFg added ****/
	select @row= count('x') from inserted where UoMnuCd in 
		('RepCustAly', 'RepRmMst' /*, 'RepMetLsWip'*/ , 'RepMetLsFg' /*'RepGldLs'*/, 'RepBrkMsgRm', 'RepBrkMsgPrd', 
		 'RepStkSumm', /*'RepInvBOELst',*/ 'RepNetStk') and /* 'RepRmZ', */
		not exists (select 'x' from param where PTyp ='RMCTG' and UoRmCtgFr= PMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Invalid Raw Material Category'
		goto ErrHndlr
	end

	/* **** Manali 3.5.0 - 05/11/08 - ErrMsg changed for Radio buttons   */
	select @row= count('x') from inserted where UoMnuCd in ('RepRmMst') and 
		not exists (select 'x' from param where PTyp ='YN' and PMCd= UOYN and PSCd= '') 
	if @row> 0 
	begin
		/* select @errmsg= 'Invalid ''Show Custm Cd'' Option ' */
		select @errmsg= 'Select if to Show Customs Codes Or Rm Codes '
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepRmReqDyn', 'RepRmReqStat', 'RepRmReqLoc', 'RepStkLed', 'RepFlashStk') and UoRmCtgFr<> '' and 
		not exists (select 'x' from param where PTyp ='RMCTG' and UoRmCtgFr= PMCd)
	if @row> 0 
	begin
		select @errmsg= 'Enter Blank Or Valid Raw Material Category'
		goto ErrHndlr
	end

/* **** Zubin 211 **** */ 
	select @row= count('x') from inserted where UoMnuCd in ('RepRmStkReq') and UoRmCtgFr<> 'D' and UoRmCtgFr<> 'C'
	if @row> 0 
	begin
		select @errmsg= 'Raw Material Category Can Be ''D'' Or ''C'' Only'
		goto ErrHndlr
	end 

/* **** Sachin 3.11.1.0 **** */ 
	select @row= count('x') from inserted where UoMnuCd in ('RepEPSMetImpEx') 
			and ((UoRmCtgFr<>'' and (UoRmCtgFr<> 'G' and UoRmCtgFr<> 'P' and UoRmCtgFr<> 'S' and UoRmCtgFr<> 'L')) Or 
				 (UoRmCtgTo<>'' and (UoRmCtgTo<> 'G' and UoRmCtgTo<> 'P' and UoRmCtgTo<> 'S' and UoRmCtgTo<> 'L')) Or 
				 (UoRmCtgSel<>'' And (UoRmCtgSel Like '%''D''%' Or UoRmCtgSel Like '%''C''%' Or UoRmCtgSel Like '%''X''%')))
	if @row> 0 
	begin
		select @errmsg= 'Only Metal Raw Material Categories can be Entered'
		goto ErrHndlr
	end 


	/* ****** Manali 3.5.0 - 17/11/08 - ErrMsg Changed For Check Boxes */
	select @row= count('x') from inserted where UoMnuCd in ('RepRmStkReq') and 
		Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd= UOYN2 and PSCd= '') 
	if @row> 0 
	begin
		select @errmsg= 'Check To Show Order Box Detail?'
		/* select @errmsg= 'Show Order Box Detail?   (Enter ''Y'' / ''N'')' */
		goto ErrHndlr
	end 

	/* ***** Manali Trading Module ***** */
	Select @row= count('x') from inserted Where UoMnuCd In ('REPJTDET','REPJTAVG') and 
		not exists(Select 'x' from Param Where PTyp='TCTYP' and PMCd =UoTcTypFr and PMCd='JT')
	if @row> 0 
	begin
		select @errmsg= 'TcTyp Should Be ''JT'''
		goto ErrHndlr
	end

	Select @row= count('x') from inserted Where UoMnuCd In ('REPJTDET','REPJTAVG') and 
		not exists(Select 'x' from Param Where PTyp='TC' and PMCd In (UoOmTcFr, UoOmTcTo) and PValue=UoTcTypFr)
	if @row> 0 
	begin
		select @errmsg= 'Tc Should Be of TcTyp ''JT'''
		goto ErrHndlr
	end
	/* ***** Manali Trading Module ***** */
	
	/*** Jay 3.4(FG)***/
	/* ***** Manali Trading Module ***** */
	select @row= count('x') from inserted where UoMnuCd in ('RepDetInv', 'RepDetInvCTB', 
			'RepAvgInv', 'RepAvgInvCTB', 'RepDetOrd', 'RepAvgOrd', 'REPFGDET','REPFGAVG', 'REPJTDET','REPJTAVG', 'REPMULTIPRCQT') and 
		not exists (select 'x' from param where PTyp ='YN' and UOYN2= PMCd) 
	if @row> 0 
	begin
		/* select @errmsg= 'Show All Value? (Enter ''Y'' or ''N'')' */
		select @errmsg= 'Select If To Show All Value? '
		goto ErrHndlr
	end

  /***** Manali 3.9.0 - LME Selection *****/
	select @row= count('x') from inserted where UoMnuCd in ('RepDetInv', 'RepDetInvCTB', 
			'RepAvgInv', 'RepAvgInvCTB', 'RepDetOrd', 'RepAvgOrd', 'REPFGDET','REPFGAVG', 'REPJTDET','REPJTAVG') and 
			(UoLme1 Not In ('LMG', 'LMP', 'LMS', 'LML', '') or UoLme2 Not In ('LMG', 'LMP', 'LMS', 'LML', '')) 
		  
	if @row> 0 
	begin
		select @errmsg= 'Invalid Lme Selected'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepDetInv', 'RepDetInvCTB', 
			'RepDetOrd', 'REPFGDET','REPJTDET') and UoYn23='Y'
			 and (UoLme1 <>  '' or UoLme2 <> '') 
	if @row> 0 
	begin
		select @errmsg= 'Lme Cannot Be Selected when Excel Format is Selected'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepRmStkReq') and 
		Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd= UOYN4 and PSCd= '') 
	if @row> 0 
	begin
		/* select @errmsg= 'Show Stock Box Detail?   (Enter ''Y'' / ''N'')' */
		select @errmsg= 'Show Stock Box Detail?  '
		goto ErrHndlr
	end 

	/* **** Zubin 211 **** */ 
	/*** Jay 3.4(FG) ***/
	/**** Manali Trading Module *****/
	select @row= count('x') from inserted where UoMnuCd in ('RepStkLed', 'RepStkSumm','RepFgStkLed', 'RepJtStkLed') 
		and UoOpnYYMm  > convert(int,convert(varchar(6),UoDtFr,112))

	if @row> 0 
	begin
		select @errmsg= 'Open Year/Month Should Be <= From Voucher Date'
		goto ErrHndlr
	end

	/*** Jay 3.4(FG) ***/
	/**** Manali Trading Module *****/
	select @row= count('x') from inserted where UoMnuCd in ('RepStkLed','RepFgStkLed', 'RepJtStkLed') and UoDtTo< UoDtFr 
	if @row> 0 
	begin
		select @errmsg= 'To Date Should Be Greater Than From Date'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepFlashStk') and 
		UoOpnYyMM > UoYyMmFr
	if @row> 0 
	begin
		select @errmsg= 'Open Year/Month Should Be Less Than From Year/Month'
		goto ErrHndlr
	end

	/* **** Zubin 211 (RepRmStkReq added) **** */ 
	select @row= count('x') from inserted where UoMnuCd in ('RepFlashStk', 'RepRmStkReq') and UoYyMmTo< UoYyMmFr 
	if @row> 0 
	begin
		select @errmsg= 'To YyyyMm Should Be Greater Than From YyyyMm'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepDsg', 'RepFbLst', 'RepFwbLst', 'RepWIWPrd', 'RepWIWExp', 'RepWIWLongPrd', 'RepWIWLongExp') and 
		not exists (select 'x' from param where PTyp ='YN' and UoYN= PMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Show The Second Detail Line Of Report Yes/No?   (Enter ''Y'' / ''N'')'
		goto ErrHndlr
	end

	/* ***** Manali 3.5.0 - 10/11/08 - Show Special Remark in wiw ***** */
	/* ***** Manali Trading Module ***** */
	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp', 'RepWIWLongPrd', 'RepWIWLongExp', 'RepSoPnd', 'RepJtPnd', 'RepJtOpnOrd') and 
		not exists (select 'x' from param where PTyp ='YN' and UoYN4= PMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Check if To Show Special Remark ? '
		goto ErrHndlr
	end

	/* ***** Manali 3.5.0 - 12/11/08 - Apply Colours in wiw ***** */
	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp', 'RepWIWLongPrd', 'RepWIWLongExp') and 
		not exists (select 'x' from param where PTyp ='YN' and UoYN5= PMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Check if To Apply Colors ?'
		goto ErrHndlr
	end

	/*** Jay 3.4(FG) ***/ 
	/* ***** Manali Trading Module ***** */
	/***** Manali 3.8.0 - RepPckLstInvBag added  ****/
	select @row= count('x') from inserted where UoMnuCd in ('RepDsgCrd', 
		'RepDetOrd', 'RepAvgOrd', 'RepInvCustStmt', 'RepDetInv', 'RepDetInvCTB', 'RepAvgInv', 
		'RepAvgInvCTB', 'RepInv','REPFGDET','REPFGAVG','RepFgInv','REPJTDET','REPJTAVG','RepJtInv', 'RepPckLstInvBag',
		'REPMULTIPRCQT') and 
		not exists (select 'x' from param where PTyp ='YN' and UoYN= PMCd) 
	if @row> 0 
	begin
		/* select @errmsg= 'Show Picture Yes/No?    (Enter ''Y'' / ''N'')' */
		select @errmsg= 'Show Picture ?'
		goto ErrHndlr
	end

	/* **** Manali 3.5.0 - 06/11/08 - ErrMsg changed for Radio Buttons  */
	select @row= count('x') from inserted where UoMnuCd in ('RepBagLst', 'RepWipBPcs', 'RepWipFgBPcs') and UoYN<> '' and 
		not exists (select 'x' from param where PTyp ='YN' and UoYN= PMCd) 
	if @row> 0 
	begin
		/* select @errmsg= 'Show Open/ Closed/ All Bags?   (Enter ''N'' / ''Y'' / Blank)' */
		select @errmsg= 'Select if to Show Open/ Closed/ All Bags'
		goto ErrHndlr
	end

	/* ****** Sachin 2.14.0 [23-11-2006] - [Multi-Company] - Changed Company to Self CoCd  ****** */
	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp') and UoYn2='N'
		And not exists (select 'x' from vparam where vPCoCd = @wSelfCoCd 
				and vPTyp ='WIWSEQ' and UoSeqCdFr= vPMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Enter Valid WIW Sequence Code'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepWIWLongPrd', 'RepWIWLongExp') and UoYn2='N'
		And not exists (select 'x' from vparam where vPCoCd = @wSelfCoCd and 
				vPTyp ='WIWLONG' and UoSeqCdFr= vPMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Enter Valid WIW Long Sequence Code'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp') and UoYn2='Y'
		And not exists (select 'x' from vparam where vPCoCd = @wSelfCoCd 
				and vPTyp ='WIWSEQ' and UoPrntSeqCdFr= vPMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Enter Valid WIW Parent Sequence Code'
		goto ErrHndlr
	end

	select @row= count('x') from inserted where UoMnuCd in ('RepWIWLongPrd', 'RepWIWLongExp') and UoYn2='Y'
		And not exists (select 'x' from vparam where vPCoCd = @wSelfCoCd and 
				vPTyp ='WIWLONG' and UoPrntSeqCdFr= vPMCd) 
	if @row> 0 
	begin
		select @errmsg= 'Enter Valid WIW Long Parent Sequence Code'
		goto ErrHndlr
	end

	/* ****** Sachin 2.14.0 [23-11-2006] - [Multi-Company] - Changed Company to Self CoCd  ****** */
	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp', 
			'RepWIWLongPrd', 'RepWIWLongExp') and 
		not exists (select 'x' from param where PTyp ='YN' and UOYN2= PMCd) 
	if @row> 0 
	begin
		/* select @errmsg= 'Show Parent Sequence (Y/N)? (Enter ''Y'' or ''N'')' */
		select @errmsg= 'Show Parent Sequence ?'
		goto ErrHndlr
	end
	/* ****** Sachin 2.14.0 [23-11-2006] - [Multi-Company] - Changed Company to Self CoCd  ****** */
	
       /****Geeta***Emr208****/
	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd', 'RepWIWExp','RepWIWLongPrd', 'RepWIWLongExp',
								'RepWipBPcs', 'RepWipFgBPcs', 'RepWipBPcsBkDt', 'RepWipFgBPcsBkDt') and 
		not exists (select 'x' from Param where PTyp ='YN' and UoYN1= PMCd) 
	if @row> 0 
	begin
		/* select @errmsg= 'Show Picture Yes/No?    (Enter ''Y'' / ''N'')' */
		select @errmsg= 'Show Picture ? '
		goto ErrHndlr
	end
/* *** JAY 2.13(CT) *** */
/* **** Zubin 211 **** */ 
	/****** added RepWipBRmBkDt (Jen 2.14) ******/
	/* ***** Manali 3.6.0 - 19/09/09 - MenuCd RepGldLs Changed to RepMetLs ***** */
	select @row= count('x') from inserted where 
		(UoMnuCd In ('RepWipBPcs', 'RepWipBPcsBkDt', 'RepPrd', 'RepBv', 'RepBagHist', 'RepRejAna', 
			'RepBrkMsgRm', 'RepBrkMsgPrd', /* 'RepTxnDT', 'RepTxnBS', 'RepTxnMLT', 'RepTxnBV', 
			'RepTxnREJ', 'RepTxnBM', */ 'RepBagLst', 'REPBAGRECO','RepWipBRm', 'RepWipBRmBkDt', 'RepBvRm', 'RepMetLsWip' /*'RepGldLs'*/)
			and UoBagTyp<> '' and 
			not exists (select 'X' from param where PTyp= 'BTYP' and UoBagTyp= PMCd and PSCd= '')) 
	if @row> 0 
	Begin
		select @errmsg= 'Invalid Bag Type Option. (''P'' For Primary, ''F'' For Flute, ''C'' For Component Bags, '''' For All)' 
		goto ErrHndlr
	end

/* *** BEF 2.13(CT) *** */
/*	select @row= count('x') from inserted where 
		(UoMnuCd In ('RepWipBPcs', 'RepWipBPcsBkDt', 'RepPrd', 'RepBv', 'RepBagHist', 'RepRejAna', 
			'RepBrkMsgRm', 'RepBrkMsgPrd', */ 
			/* 'RepTxnDT', 'RepTxnBS', 'RepTxnMLT', 'RepTxnBV', 'RepTxnREJ', 'RepTxnBM', */ 
			/*'RepBagLst', 'REPBAGRECO') and UoYN2<> '' and 
			not exists (select 'X' from param where PTyp= 'YN' and UoYN2= PMCd and PSCd= '')) 
		OR 
		(UoMnuCd In ('RepWipBRm', 'RepBvRm', 'RepGldLs') and UoYN3<> '' and 
			not exists (select 'x' from param where PTyp= 'YN' and UoYN3= PMCd and PSCd= '') )
	if @row> 0 
	Begin
		select @errmsg= 'Invalid ''Show Flute/Primary Bags'' Option. (''Y'' For Flute, ''N'' For Primary Bags, '''' For Both)' 
		goto ErrHndlr
	end
*/

	select @row= count('x') from inserted where UoMnuCd in ('RepWIWPrd','RepWIWExp','RepWIWLongExp','RepWIWLongPrd') 
		and not exists (select 'x' from param where PTyp= 'BTYP' and UoBagTyp= PMCd and PSCd= '') 
	if @row> 0 
	Begin
		select @errmsg= 'Show Flute/ Component Or Primary Bags? (''F'' For Flute, ''C'' For Component, ''P'' For Primary Bags)'
		goto ErrHndlr
	end 

	/****** (added RepWipBRmBkDt) (Jen 2.14) ******/
	/* ***** Manali 3.6.0 - 19/09/09 - MenuCd RepGldLs Changed to RepMetLs ***** */
	select @row= count('x') from inserted where UoBChrFr<> '' and 
		UoMnuCd In ('RepWIWPrd', 'RepWIWExp', 'RepWIWLongExp', 'RepWIWLongPrd', 'RepWipBPcs', 
				'RepWipBPcsBkDt', 'RepPrd', 'RepBrkMsgRm', 'RepBrkMsgPrd', 'REPBAGRECO', 'RepWipBRm', 
				'RepWipBRmBkDt', 'RepBvRm', 'RepMetLsWip' /*'RepGldLs'*/) and UoBagTyp= '' 
	if @row> 0 
	Begin
		select @errmsg= 'Bag Character Should Not Be Entered' 
		goto ErrHndlr
	end

/* *** BEF 2.13(CT) *** */
/*	select @row= count('x') from inserted where UoBChrFr<> '' and 
		(	(	UoMnuCd In ('RepWIWPrd', 'RepWIWExp', 'RepWIWLongExp', 'RepWIWLongPrd', 'RepWipBPcs', 
				'RepWipBPcsBkDt', 'RepPrd', 'RepBrkMsgRm', 'RepBrkMsgPrd', 'REPBAGRECO') and 
				UoYN2 = '' 
			)
			Or
			(	UoMnuCd In ('RepWipBRm', 'RepBvRm', 'RepGldLs') and UoYN3 = '' 
			)
		)
	if @row> 0 
	Begin
		select @errmsg= 'Bag Character Should Not Be Entered' 
		goto ErrHndlr
	end
*/
	
	/****** added RepWipBRmBkDt (Jen 2.14) ******/
	/* ***** Manali 3.6.0 - 19/09/09 - MenuCd RepGldLs Changed to RepMetLs ***** */
	select @row= count('x') from inserted where UoBChrFr<> '' and 
	UoMnuCd In ('RepWIWPrd', 'RepWIWExp', 'RepWIWLongExp', 'RepWIWLongPrd', 'RepWipBPcs', 
	'RepWipBPcsBkDt', 'RepPrd', 'RepBrkMsgRm', 'RepBrkMsgPrd', 'REPBAGRECO','RepWipBRm', 
	'RepWipBRmBkDt', 'RepBvRm', 'RepMetLsWip' /*'RepGldLs'*/) and 
	Not Exists (select 'x' from param where PTyp= 'BCHR' and UoBChrFr= PMCd and PSCd= '' and PValue= UoBagTyp) 
