			not exists (select 'x' from xTcTyp where xTpVchTyp= UoVchTypFr)  
		if @row> 0 
		begin
			select @errmsg= 'InValid Voucher Type'
			goto ErrHndlr
		end
***/

/*** Zubin xEmr2.05 ********************************************************************/
		select @row= count('x') from inserted where (UoMnuCd in ('RepAnaRm', 
			'RepAnaLab') and 
			not exists (select 'x' from xTcTyp where xTpVchTyp= UoVchTypFr) )
