				and xPmCd = UoxRepGrp)
		If @Row > 0 
		Begin
			Select @ErrMsg = 'Invalid Report Summary Group Option'
			Goto ErrHndlr
		End
/*** Zubin xEmr2.05 ********************************************************************/

		select @row= count('x') from inserted where UoMnuCd in ('RepAnaDsg') and 
			not exists (select 'x' from param where PTyp= 'DMTCTYP' and 
			UoDmTypFr= PMCd) 
