		/*('Select xTpVchTyp from xTcTyp where xTpCoCd= '' + _
              	adc('UoCoCdFr') + '' and xTpTcTyp= '' + adc('UoTcTypFr') + ''')*/

		select @row= count('x') from inserted where UoMnuCd in ('RepProfitMargin') 
			and not exists (select 'x' from xTcTyp where xTpTcTyp= UoxTcTypFr and 
			xTpVchTyp not in('PUR', 'PORD', 'MVM') and xTpVchTyp in ('SAL', 'SORD')) 
		if @row> 0 
		begin
			select @errmsg= 'InValid Voucher(Tc) Type (Select Only ''SAL''/''SORD'' TcTypes)'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet', 'RepVchAvg') and 
			not exists (select 'x' from param where PTyp ='YN' and UoYN= PMCd) 
		if @row> 0 
		begin
			select @errmsg= 'Show Picture ? '
			/* select @errmsg= 'Show Picture ? (Enter ''Y'' / ''N'')' */
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet', 'RepVchAvg') and 
			not exists (select 'x' from param where PTyp ='ORDVAL' and UoOrdVal= PMCd) 
		if @row> 0 
		begin
			select @errmsg= 'Show Sales Prc/Cost Prc ? (Enter ''Y'' / ''N'')'
			goto ErrHndlr
		end
		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet', 'RepVchAvg') and 
			not exists (select 'x' from param where PTyp ='YN' and UoYN4= PMCd) 
		if @row> 0 
		begin
			select @errmsg= 'Show Unit Val/Total Val ? (Enter ''Y'' / ''N'')'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet', 'RepVchAvg') and 
			UoYN1<> '' and not exists (select 'x' from param where PTyp ='YN' and UoYN1= PMCd) 
		if @row> 0 
		begin
			select @errmsg= 'Entered + Amendment Qty ? (Enter ''Y'' / ''N'')'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchAvg') and 
			not exists (select 'x' from param where PTyp ='YN' and UoYN2= PMCd) 
		if @row> 0 
		begin
			select @errmsg= 'Show Value ? (Enter ''Y'' / ''N'')'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet') and 
			not exists (select 'x' from xparam where xPTyp= 'RmGrp' and 'OrdDet'= xPMCd and UoRmGrp= xPSCd) 
		if @row> 0 
		begin
			select @errmsg= 'Invalid RmGrp Option '
			goto ErrHndlr
		end

		select @row= count('x') from inserted where UoMnuCd in ('RepVchDet') and 
			not exists (select 'x' from xparam where xPTyp= 'LabGrp' and 'OrdDet'= xPMCd and UoLabGrp= xPSCd) 
		if @row> 0 
		begin
			select @errmsg= 'Invalid LabGrp Option '
			goto ErrHndlr
		end

    /*** Manali 3.9.0 - UoRepSbFile ***/
		select @row= count('x') from inserted where UoMnuCd in ('RepShpBillFile') and 
			UoSbICC='' or UoSbPOD='' or UoSbCOD='' or UoSbAF=''
		if @row> 0 
		begin
			select @errmsg= 'Fields Cannot be Blank'
			goto ErrHndlr
		end


/*** Zubin xEmr2.05 *****************************************************************/
		Select @Row= count('x') from Inserted 
			where (UoMnuCd = 'REPANADSG' And UoYN= 'Y' 
				and UoxRepGrp <> '') 
				and Not Exists (Select 'x' from Param where PTyp = 'DC' 
					and PmCd = UoxDc)
		If @Row> 0 
		Begin
			Select @ErrMsg = 'Invalid Positive Value As Option'
			Goto ErrHndlr
		End

		Select @Row= count('x') from Inserted 
			where UoMnuCd = 'REPANADSG' and UoxRepGrp = '' and UoxDc <> '' 
		If @Row> 0 
		Begin
			Select @ErrMsg= ' ''Positive Value As'' Option Should Be Blank '
			Goto ErrHndlr
		End
/*** Zubin xEmr2.05 *****************************************************************/

	END

	return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end


GOGO

ALTER TRIGGER [UsrOptDsgAna_INUPDL] ON [UsrOptDsgAna] 
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	declare @mode char(1)
	declare @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	IF @@ROWCOUNT= 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrOptDsgAna' )
		RETURN
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '')
	select @mode= case (select count('x') from inserted) when 0 then 'D'
		      else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
		      end
	select @row= count('x') from inserted where UdMnuCd in ('RepDsgCat') and
		not exists (select 'x' from param where PTyp= 'DAANAFLD' and UdAnaSr= PMCd and PValue= 'Y')
	if @row> 0
	begin
		select @errmsg= 'Invalid Analysis Code Field'
		goto ErrHndlr
	end
	return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
end

GOGO
ALTER TRIGGER [UsrRight_INUPDL] ON [UsrRight] 
       FOR INSERT, UPDATE, DELETE 
	   NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @ReplAgt BIT

	IF @@ROWCOUNT= 0		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'UsrRight')
		RETURN

	select @mode=case (Select count('x') from inserted) when 0 then 'D'
		     Else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
		     End	

	set @wSelfCd = 'ZSELF'	

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin  
			If   Exists( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  Or  
				Exists (Select 'x' From SysDb where SysId='CRM' and SysDb ='WEB') 
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

 	if @mode = 'A'
	Begin
		if Exists (Select 'x' from Head where HCd= @wSelfCd and HCoCd= 'ZZZ' and HCustomiseOrd= 'N') 
			and exists(Select 'x' from inserted where not(UrGrp= '')) 
		begin
			   select @errmsg= 'Cannot Insert Records As Rights For Customising Order Entry Screen Are Reserved' 
			   goto ErrHndlr  		
		end

		/*** Cannot add 'GRD' column record if corresponding 'GRD' record does not exist ***/ 
		select @row= count('x') from inserted ins where ins.UrCtlTyp= 'GRD' and ins.UrName<> '' 
			and not exists (select 'x' from UsrRight Ur where Ur.UrGrp= ins.UrGrp and Ur.UrTcTyp= ins.UrTcTyp 
					and Ur.UrCtlTyp= ins.UrCtlTyp and Ur.UrCtlSTyp= ins.UrCtlSTyp and Ur.UrName= '') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Insert Column Records As Grid Record Does Not Exist'
			goto ErrHndlr
		end

		/*** Cannot add Text Box record if corresponding Parent record does not exist ***/ 
		select @row= count('x') from inserted ins where ins.UrCtlTyp= 'X' and ins.UrName<> '' 
			and not exists (select 'x' from UsrRight Ur where Ur.UrGrp= '' and Ur.UrTcTyp= ins.UrTcTyp 
					and Ur.UrCtlTyp= ins.UrCtlTyp and Ur.UrCtlSTyp= ins.UrCtlSTyp and Ur.UrName= '') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Insert Textbox Records As Parent Record Does Not Exist'
			goto ErrHndlr
		end

	End 

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		/*** Cannot Update If User Group = '' ***/ 
		/* Select @Row= count('x') from inserted where UrGrp= '' 
	 	If @Row> 0 
		Begin  
			Select @ErrMsg= 'Update of IDE Definition Not Allowed'
			GoTo ErrHndlr
		End
		*/

		/*** Cannot Change Key ***/
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.UrTcTyp= del.UrTcTyp 
				     and ins.UrGrp= del.UrGrp and ins.UrCtlTyp= del.UrCtlTyp 
				     and ins.UrCtlSTyp= del.UrCtlSTyp and ins.UrName= del.UrName)
		If @Row> 0
		Begin 
			Select @ErrMsg= 'Cannot Change Tc Type/ User Group/ Control Type/ Control SubType/ Name'
			GoTo ErrHndlr
		End

		/*** Update the Description ***/
		update UsrRight set UrDesc= ins.UrDesc 
		From inserted ins where ins.UrGrp= '' and ins.UrTcTyp= UsrRight.UrTcTyp 
		     and UsrRight.UrGrp<> '' and ins.UrCtlTyp= UsrRight.UrCtlTyp 
		     and ins.UrCtlSTyp= UsrRight.UrCtlSTyp and ins.UrName= UsrRight.UrName 
	End

	if @mode in ('A','C')
	begin
		/****** Valid Tc Type ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
				    PTyp= 'TCTYP' and PMCd= UrTcTyp and PValue1= 'OM')
		if @row> 0 
		Begin
			select @errmsg= 'Tc Type Not Defined'
			goto ErrHndlr
		end

		/****** Blank Or Valid User Group ******/
		select @row= count('x') from inserted where 
			UrGrp<> '' and not exists (select 'x' from Param where 
				    PTyp= 'USRGRP' and PMCd= UrGrp)
		if @row> 0 
		Begin
			select @errmsg= 'User Group Not Defined'
			goto ErrHndlr
		end

		/****** Valid Control Type ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
				    PTyp= 'CTRLTYP' and PMCd= UrCtlTyp)
		if @row> 0 
		Begin
			select @errmsg= 'Control Type Not Defined'
			goto ErrHndlr
		end
		
		/****** If Control Type<> 'GRD' or 'X' then Control Sub Typ= Blank ******/
		select @row= count('x') from inserted where UrCtlTyp not in ('GRD', 'X') and UrCtlSTyp<> '' 
		if @row> 0 
		Begin
			select @errmsg= 'Control Sub Type Should Be Blank'
			goto ErrHndlr
		end

		/****** If Control Type= 'GRD' or 'X' then Control Sub Typ<> Blank ******/
		select @row= count('x') from inserted where UrCtlTyp in ('GRD', 'X') and UrCtlSTyp= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Control Sub Type Cannot Be Blank'
			goto ErrHndlr
		end

		/****** If User Group<> '' and Control Type= 'GRD' or 'X' then Control Sub Typ= valid Sub Type ******/
		select @row= count('x') from inserted ins where ins.UrGrp<> '' and ins.UrCtlTyp in ('GRD' , 'X') 
				and not exists (Select 'x' from UsrRight Ur where Ur.UrTcTyp= ins.UrTcTyp 
						and Ur.UrGrp= '' and Ur.UrCtlTyp= ins.UrCtlTyp and Ur.UrCtlSTyp= ins.UrCtlSTyp) 
		if @row> 0 
		Begin
			select @errmsg= 'Control Sub Type Not Defined'
			goto ErrHndlr
		end

		/****** If Control Type <> 'GRD' or 'X' then Name<> Blank ******/
		select @row= count('x') from inserted where UrCtlTyp not in ('GRD', 'X') and UrName= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Name Cannot Be Blank'
			goto ErrHndlr
		end

		/****** If Control Type = 'X' and Group <> '' then Name<> Blank ******/
		select @row= count('x') from inserted where UrCtlTyp= 'X' and UrGrp<> '' and UrName= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Name Cannot Be Blank'
			goto ErrHndlr
		end

		/****** If User Group<> '' then Name= valid Name ******/ 
		select @row= count('x') from inserted ins where ins.UrGrp<> '' 
				and not exists (Select 'x' from UsrRight Ur where Ur.UrTcTyp= ins.UrTcTyp 
						and Ur.UrGrp= '' and Ur.UrCtlTyp= ins.UrCtlTyp 
						and Ur.UrCtlSTyp= ins.UrCtlSTyp and Ur.UrName= ins.UrName) 
		if @row> 0 
		Begin
			select @errmsg= 'Name Not Defined'
			goto ErrHndlr
		end

		/****** Desc<> Blank ******/
		select @row= count('x') from inserted where UrDesc= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Description Cannot Be Blank'
			goto ErrHndlr
		end

		/****** Style can be Blank only if Control Type= 'GRD' and Name= '' ******/ 
		select @row= count('x') from inserted ins 
			where not (ins.UrCtlTyp in ('GRD', 'X') and ins.UrName= '') and UrStyle= ''
		if @row> 0 
		Begin
			select @errmsg= 'Style Cannot Be Blank'
			goto ErrHndlr
		end

		/****** Style should be Blank if Control Type= 'X' and Name= '' ******/ 
		select @row= count('x') from inserted ins 
			where ins.UrCtlTyp= 'X' and ins.UrName= '' and UrStyle<> '' 
		if @row> 0 
		Begin
			select @errmsg= 'Style Should Be Blank'
			goto ErrHndlr
		end

		/****** Blank or valid Style ******/ 
		select @row= count('x') from inserted ins 
			where UrStyle<> '' and not exists (select 'x' from Param where 
				    PTyp= 'IDE' and PMCd= UrStyle)
		if @row> 0 
		Begin
			select @errmsg= 'Style Not Defined'
			goto ErrHndlr
		end

		/****** If Control Type= 'CMD' then Style cannot be 'D' ******/ 
		select @row= count('x') from inserted ins 
			where UrCtlTyp= 'CMD' and UrStyle= 'D' 
		if @row> 0 
		Begin
			select @errmsg= 'Style Of A Button Control Can Only Be ''I'' Or ''E'' '
			goto ErrHndlr
		end

	End


	/****** Check For Use In UsrRight  ******/	
	/****** If In Use Do Not Allow Delete ******/
	if @mode = 'D' 
	Begin
		/*** Cannot delete IDE definition if User group record exists ***/
		select @row= count('x') from deleted del where del.UrGrp= '' 
			and exists (select 'x' from UsrRight Ur where Ur.UrGrp<> '' and Ur.UrTcTyp= del.UrTcTyp 
					and Ur.UrCtlTyp= del.UrCtlTyp and Ur.UrCtlSTyp= del.UrCtlSTyp 
					and Ur.UrName= del.UrName) 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Record In Use'
			goto ErrHndlr
		end

		/*** Cannot delete 'GRD' definition if corresponding column record exists ***/ 
		select @row= count('x') from deleted del where del.UrCtlTyp= 'GRD' and del.UrName= '' 
			and exists (select 'x' from UsrRight Ur where Ur.UrGrp= del.UrGrp and Ur.UrTcTyp= del.UrTcTyp 
					and Ur.UrCtlTyp= del.UrCtlTyp and Ur.UrCtlSTyp= del.UrCtlSTyp and Ur.UrName<> '') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Grid Record As Column Record Exists'
			goto ErrHndlr
		end

		/*** Cannot delete 'X' definition if corresponding Textbox record exists ***/ 
		select @row= count('x') from deleted del where del.UrCtlTyp= 'X' and del.UrName= '' and del.UrGrp= '' 
			and exists (select 'x' from UsrRight Ur where Ur.UrTcTyp= del.UrTcTyp 
					and Ur.UrCtlTyp= del.UrCtlTyp and Ur.UrCtlSTyp= del.UrCtlSTyp and Ur.UrName<> '') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Parent Record As Textbox Record Exists'
			goto ErrHndlr
		end


	End



	return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
END

GOGO

/****** Object:  Trigger dbo.VldRmLn_INUPDL    Script Date: 01/01/02 5:36:40 PM ******/
ALTER TRIGGER [VldRmLn_INUPDL] ON [VldRmLn]
    FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCd VARCHAR(8)
	
	IF @@ROWCOUNT=0
		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'VldRmLn' )
		RETURN

	Select @mode=case (select count('x') from inserted) when 0 then 'D'
	Else
		Case (select count('x') from deleted) when 0 then 'A' else 'C' end
	End

	set @wSelfCd = 'ZSELF'	

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

	if @mode in ('A','C')
	Begin
		select @row= count('x') from inserted where
			not exists (select 'x' from Param where PTyp='RMCTG' and PMCd= VrsRmCtg)
		if @row> 0
		begin
			select @errmsg= 'Rm Category Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where
			not exists (select 'x' from Param 
					where PTyp='RMID' and PMCd= VrsRmCtg And PSCd=VrsRmId)
		if @row> 0
		begin
			select @errmsg= 'Rm Id Not Defined'
			goto ErrHndlr
		end

		select @row=count('x') from inserted where VrsLn1=0
		if @row>0
		begin
			select @errmsg='Please Enter a Valid Size 1'
			goto ErrHndlr
		End		
	End 
 return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction
	end
END

GOGO

ALTER TRIGGER [vParam_INUPDL] ON [vParam] 
   For INSERT,UPDATE,DELETE
   NOT FOR REPLICATION
As
BEGIN
 /* Trigger Version 2.14.0 [Original] */	
 DECLARE @ROW INT
 DECLARE @mode char(1)
 DECLARE @errmsg varchar(255)
 DECLARE @vPTyp varchar(8)
 DECLARE @wHCd VARCHAR(8)
 DECLARE @wSelfCoCd VARCHAR(3)
 DECLARE @ReplAgt BIT  
	
 IF @@ROWCOUNT=0   RETURN

 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'vParam' )
  RETURN

 select @mode=case (select count('x') from inserted) when 0 then 'D'
       else
   case (select count('x') from deleted) when 0 then 'A' else 'C' end
       end

	set @wHCd = 'ZSELF'	
	set @wSelfCoCd= 'ZZZ'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One vPTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One vPTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/*** Storing PTyp In The Variable @PTyp ***/
	select @vPTyp= case  when @mode in ('C', 'A') then (Select max(vPTyp) from inserted)  else (Select max(vPTyp) from deleted) end  

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	select @Row=Count('x') from vParam vPm where (@vPTyp= 'PTYP') or 
		(vPm.vPTyp= 'PTYP' and vPm.vPMCd= @vPTyp and vPm.vPValue= 'M')
	If @Row > 0
	begin 
		Select @ErrMsg='Cannot Add/Change/Delete Microway Parameter - '+ @vPTyp
		GoTo ErrHndlr
	end		

 	/******** Key Cannot Be Changed  (i.e.vPCoCd, vPTyp, vPMCd and vPSCd cannot be changed) ********/ 
 	If @mode = 'C'
 	Begin
  		select @Row=Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.vPCoCd= del.vPCoCd and 
			ins.vPTyp= del.vPTyp and ins.vPMCd= del.vPmCd and ins.vPSCd= del.vPSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Variable Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp<> 'PTYP' and 
		not exists (select 'x' from vParam Prm where Prm.vPCoCd= @wSelfCoCd and 
					Prm.vPTyp= 'PTYP' and Prm.vPMCd= ins.vPTyp)
		if @row> 0 
		begin
			select @errmsg= 'Variable Parameter Type Not Defined'
			goto ErrHndlr
		end

		/****** vPCoCd= valid HCoCd ******/
		select @row= count('x') from inserted ins where not exists
			 (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd)
		if @row>0 
		begin
			select @errmsg= 'Company Code Not Defined'
			goto ErrHndlr
		end

		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp= 'PTYP' and 
			ins.vPCoCd<> @wSelfCoCd 
		if @row> 0 
		begin
			select @errmsg= 'For PTyp= ''PTYP'', the Company Code should Be '+@wSelfCoCd
			goto ErrHndlr
		end

		/*** vPMCd cannot be Blank ***/
		select @row=count('x') from inserted where vPMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end
		/*** vPDesc cannot be blank ***/
		/* ******* Geeta CRM 2.12 ******** */
		select @row=count('x') from inserted where vPDesc= '' and vPTyp<>'CRMWIW'
		if @row>0 
		begin
			select @errmsg='Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @vPTyp= 'CHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row> 0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd= Not Blank ******/
			select @row= count('x') from inserted where vPSCd= ''
			if @row>0 
			begin
				select @errmsg= 'Character Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****************Geeta**Crm*2.12************************************/
			select @row= count('x') from inserted ins where vPSCd='WEB' and 
				(Not Exists(Select 'x' From SysDb where SysId='CRM') Or 
				Not Exists (Select 'x' From Param 
					where PTyp='TC' and PMCd=vPMCd  and PValue in ('SO','QT','QS','MF')))
			if @row>0 
			begin
				select @errmsg= 'WEB Chr can be Used Only for ''SO'',''QS'',''QT'',''MF'' in CRM Database  '
				goto ErrHndlr
			end
			/****Geeta*****Crm**************/  
			select @row= count('x') from inserted ins where vPCoCd='WEB' and  vPSCd<>'WEB'	
			if @row>0   
			begin  
				select @errmsg= 'Character Other than ''WEB'' cannot be defined for CoCd=''WEB''  '  
				goto ErrHndlr  
			end  
			/****** vPValue= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPValue<>'' and 
				not exists (select 'x' from Loc where LocCoCd = vPCoCd 
					and LocTyp<> 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Default From Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum= 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPDesc225<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp<> 'P' and LocCd= vPDesc225)
			if @row>0 
			begin
				select @errmsg= 'Default To Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPValue1= Valid Bag Loc ****** Bhavna removed check for tc FB as multiple locns in FB*/
			select @row= count('x') from inserted where vPValue1<> '' and vPMCd <> 'FB' and  
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp= 'P' and LocCd= vPValue1)
			if @row>0 
			begin
				select @errmsg= 'Default Bag Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum1= 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2= 'D' or 'C' (Raw Material Debit Or Credit) ******/
			select @row= count('x') from inserted ins where ins.vPValue2<> '' and 
					not exists (select 'x' from Param Prm where Prm.PTyp= 'DC' 
        						and Prm.PMCd= ins.vPValue2)
			if @row>0 
			begin
				select @errmsg= 'Default Raw Material Debit / Credit Not Defined'
				goto ErrHndlr
			end

			/****** vPValue3 = Y/N ******/
			select @row=count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' 
					    and Prm.PMCd= ins.vPValue3)

			if @row>0 
			begin
				select @errmsg= 'TrialChr Should Be Y/N'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> 'Y' and vPValidYn <> 'N' and vPValidYn <> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Y/N'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End


		if @vPTyp= 'DEFCHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row>0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end

			/****** vPValue= Valid vPSCd ('CHR') ******/
			select @row= count('x') from inserted ins where vPValue<> '' and 
				not exists (select 'x' from vParam Prm where 
						Prm.vPCoCd= ins.vPCoCd and Prm.vPTyp= 'CHR' 
						and Prm.vPMCd= ins.vPMCd 
						and Prm.vPSCd= ins.vPValue and Prm.vPValidYn <> 'N')
			if @row> 0 
			begin
				select @errmsg= 'Default Character Not Defined'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end
			/*********Geeta*******Emr207************/

		End

/****************** urmi FgSubLoc 10/8/03 *************************************************/
		if @vPTyp = 'FGSUBLOC' 
		Begin 
			/****** vPSCd = Blank ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank ******/
			select @row= count('x') from inserted ins where vPValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'vPValue Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
